/* 平成13年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h13.committeeSessions.push(...[{"id":"h13-20011009-4","meetingId":"h13-c-settlement","date":"2001年10月9日","dateIso":"2001-10-09","committee":"決算特別委員会","time":"午前１０時０５分～午後５時３５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件整理しています。","topics":[{"id":"topic-01","title":"◯横山委員長 皆さん、おはようございます。ただいまより、決算特別委員会を開きます。 平成１２年度品川区一般会計歳入歳出決算","agenda":"◯横山委員長 皆さん、おはようございます。ただいまより、決算特別委員会を開きます。 平成１２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"３町会で、何とかならないかという要望を、やはりこれは相当な事態であるということです。その後、どう対応なさったのかということを、まず伺っておきたいと思います。","respondent":"中村交通安全担当課長","answer":"今週末の１２日に再度集まりまして、じゃあ、具体的にどのように進めていくかということで会議を持つ予定になっております。その辺のところで、１２日にさらに集まりまして、具体的な対応策について検討していくということになってあります。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問・要望","question":"ある程度経験もおありでしょうから、忙しいときと忙しくない時期があるはずですから、答えを出せるのではないかと思います。お話を伺っていると、特に品川区は、こういう種類の問題にどういうスタンスがとれるのかということ。","respondent":"中村交通安全担当課長","answer":"近隣の皆さんにできるだけ負担をかけないように進めていくということで、区と警察のほうで主導しまして、それぞれ調整しているです。双方がうまくいくようにということで、工事の円滑、なおかつ交通安全というものを進めるようにやっております。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問・要望","question":"そのことが大きな渋滞の原因になるということですから、これに関しても、例えば。そういう対応が必要だと思いますけれども、２点について、お聞かせほしいと求めました。","respondent":"中村交通安全担当課長","answer":"駐車の問題についても、工事の許可条件の中で、そういうところに駐車しないようにということで実施しております。今後も、こういう関係については、警察と連絡を深めながら対応していきたいと考えております。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問・要望","question":"いろいろなことが起きてくるわけですから、経済効果の面からも、いろいろ効果があるんだということをしっかりと踏まえていただきたい。早期開通に向けて特段の努力をしていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"堺委員","kind":"質問","question":"私のほうから、３点、端的にお尋ねをしておきたいと思います。ここは旧国鉄の被服廠の跡地というんですか、それによって、進捗状況がおくれやしないかということをちょっと心配するんです。","respondent":"松代道路公園課長、中村交通安全担当課長、北村下水道河川課長","answer":"苗木原踏切付近の排水等の状況の認識というご質問です。こちらについても、上部のほうで、一度排水を改良したことがあります。こちらにつきましては、自転車とオートバイ等、自転車絡みの事故が２件発生していると聞いております。現在のところ、荏原警察署のほうに… 状況のボーリング調査等を実施いたしましたところ、３.５ｍ×２.５ｍ、掘削範囲内で２１個ほど出てまいりました。","id":"exchange-005"},{"speaker":"堺委員","kind":"質問・要望","question":"地域の人たちからもかなり強い要望があったと思うんですけども、それから反対側が中央公園ですから、要望もあったと思うんです。私は素人ですからよくわかりませんけども、あの辺をところに夜行ってみましたら、信号はあるんですけども、樹木の関係で非常に暗い地域なんです。","respondent":"松代道路公園課長、中村交通安全担当課長","answer":"これは、現地を調査しまして、横断側溝等を含めて検討を進めてまいります。非常に財源的に厳しいというお返事をいただいていますが、引き続き協議してまいります。 照会中の事故の内容等を検討しまして、２件あったということですので、現場の状況によって対応をしていきたいと考えております。","id":"exchange-006"},{"speaker":"上山委員","kind":"質問","question":"１３２ページ、都市開発費、大崎駅周辺地区再開発事業、この関連で幾つかお尋ねしたいと思います。東口第３地区は、どういう理由でＡランクになったのか、教えていただければと思うんです。","respondent":"南雲都市開発課長","answer":"土地の利用を格段に高度化することができるということで、再開発を行う効果が極めて高いということで、そのような評価になっております。今後、８、９番地区についても、どのような効果が見込めるのかについて、計測を行っていきたいと考えております。","id":"exchange-007"},{"speaker":"上山委員","kind":"質問","question":"これの進捗状況が、今、どうなっているのか教えてほしいと求めました。それからあわせて、中地区の開発の目的、前にちょっと伺ったことがありますけれども、そこら辺について、ちょっと教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"そのうち９割を超える方が準備組合に参加されておりまして、もう少し具体的な権利変換の内容、その時点でどうするかを考えたいということです。加入するかどうかをこれから決めていくということで、大きな反対というものは、権利者の中にないと認識しております。","id":"exchange-008"},{"speaker":"上山委員","kind":"質問","question":"ちょっと伺いたいんですが、買い手を早く見つけて云々というところなんですが、これは決まったんでしょうか。それから、開発の主体を一体どう思っていらっしゃるのか、もう一度お願いしたいんですが。","respondent":"南雲都市開発課長","answer":"都市計画の時期がはっきりしませんと最終的な決断はできないという状況もあるということで、現在は、有力な候補数社と交渉をしている途中です。支援しておりますのも、そういう事業を進めてほしいということが区のほうにも伝わってきまして、推進に努めているです。","id":"exchange-009"},{"speaker":"上山委員","kind":"質問・要望","question":"こういう形で進んでいった場合、何人か反対があるとか、私聞いておりますけれども、開発そのものは、最終的にどんなふうになるんでしょうか。これでどんなふうに進んでいくんでしょうか、考えていらっしゃるのか、教えてもらたいんですが。","respondent":"南雲都市開発課長","answer":"都市計画の協議を進めておりまして、都市計画審議会にかけまして、都市計画の決定ということになります。国土交通省大臣の認可を受けて、今後、事業を進めていくです。","id":"exchange-010"},{"speaker":"上山委員","kind":"質問・要望","question":"これが全部じゃないですけれども、そういう意味では、お金の使い方が問われていると思うんですよ。地元の要望があるから進めていくと言っておりますけれども、一体ここにどれだけ補助金を投入する予定ですか、端的にお願いしたいんですけども。","respondent":"南雲都市開発課長","answer":"まだ、建物の計画がはっきりしておりません。それの補助対象の部分について補助が入れられるということですが、現在の大まかな数字としては、４７億円というのが試算で出ております。","id":"exchange-011"},{"speaker":"上山委員","kind":"質問・要望","question":"才覚かもしれませんけれども、今ほんとうに大事な、住民のほんとうに求めているところにこそ使うべきだと思うんです。もう時間があれですから、住民もどんどん減り、そしてここに今４７億円も投入する。","respondent":"南雲都市開発課長","answer":"あくまで、土地については保険会社が底地を持っておりましたが、今、お住まいの借地をされている住民の皆さん、ここが再開発の主体ということで、これは密集地域と同じように、環境をよくしていくです。","id":"exchange-012"},{"speaker":"林（和）委員","kind":"質問","question":"私のほうから、２点ほどお伺いをいたしたいと思います。ですから、公園も１０年に１回は見直しをすべきではないかと思いますけれども、その点を、お尋ねをいたします。","respondent":"岩田管理工事課長","answer":"まだ設置し始めて間もございませんので、その使用方法も含めて、掲示できるようなＰＲ活動を検討してまいりたいと思います。浜川公園、大井中央公園につきましても、樹木の間引き等も検討に入れながら、委員のご指摘の趣旨に沿うような形で検討します。","id":"exchange-013"},{"speaker":"林（和）委員","kind":"提案","question":"昭和６２年から始めまして、今現在まで、そういうふうな状況で、区民の皆さんにＰＲされてないということはどういうことなんですか。もう１０年にもなるわけですけれども、どういう考えでおられるんか尋ねました。","respondent":"岩田管理工事課長","answer":"地域の皆様にはご説明した上で、設置はしておりますけれども、検討します。現在、人工芝で、多目的に３６５日使っていただけるようなもので検討させていただいているものです。","id":"exchange-014"},{"speaker":"林（和）委員","kind":"質問","question":"１０年先といったら、私、議員をやっているかどうかわかりません。それと同時に、それが完成した後の立会川の上部はどういうふうに計画をされているのか、その点、お伺いをいたします。","respondent":"北村下水道河川課長","answer":"現在、第二立会川幹線の計画といたしまして、なぎさ会館の駐車場を立坑の基地といたしまして、工事を始める予定です。検討してまいりたいと思いますので、よろしくご理解のほど、お願いいたします。","id":"exchange-015"},{"speaker":"本田委員","kind":"質問","question":"この対策、管理はどうやっているのか、お尋ねします。目撃したこともありますので、お尋ねしたいと思います。","respondent":"松代道路公園課長、中村交通安全担当課長","answer":"私のほうから、鮫洲運動公園の防塵対策についてお答え申し上げます。スプリンクラーの大型のものを設置いたしまして、多いときには４回回しまして、防塵対策をとっているところです。 この事故ほどの数ではありませんけども、増加傾向にあるということです。極端に言いますと、一時停止とか、そういうきちんとしたルール、マナーが守られていないというものが事故につながっていると考えております。","id":"exchange-016"},{"speaker":"本田委員","kind":"質問","question":"ですから、公園のあり方についても、ちょっと検討をする必要があるんではないかと思います。その辺についてのお考えを、もう一度、お尋ねをしたいと思います。","respondent":"松代道路公園課長、中村交通安全担当課長","answer":"そういった意味では、操作に非常に負担がかかるというようなことをご説明して、ご了承をいただいたところです。今後、行いまして、そういった苦情等が少なくなるように対応してまいりたいと考えているところです。自転車の事故そのものが増えている、それから、それぞれ自転車を利用されている方が認識されることが大事じゃないかということであります。","id":"exchange-017"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、軽くて安全な、関係機関とも検討するようなことをやるべき時期に来ているんではないかと思います。こういう状況についてもっと認識を深めて、ＰＲも機会あるごとにやっていく必要があるんではないかということで、要望しておきたいと思います。","respondent":"松代道路公園課長","answer":"今の委員のご指摘のとおり、いろいろ使っていただくのは、地元の方々が大変多うあります。地元の方々と再度いろいろお話をし、また散水等のご協力の点も十分に打合せをさせていただいて、取り組んでまいりたいと考えています。","id":"exchange-018"},{"speaker":"中島委員","kind":"提案","question":"これは一般質問で行おうかなと思っていたんですが、先輩議員がこれまでも何度か提案をされておりますが、ケナフの活用ということなんです。そうした空き地を利用してケナフが植えられていたんですが、区のほうでは、何か計画があるか尋ねました。","respondent":"松代道路公園課長、中島街路事業担当課長、伊佐都市計画課長","answer":"もう１点、ケナフの関係ですけれども、これは私どももいろいろと注目をしています。ただ、１年草ということから… 今後のスケジュールですけれども、事業認可を来年４月ごろに予定してございまして、その後に用地補償説明会というのを予定しております。そういった中で… 東急単独でやることになる事業ですが、今の状況では、難しいというお話をいただいています。","id":"exchange-019"},{"speaker":"中島委員","kind":"提案","question":"一般質問では、花のボランティアということで提案をさせていただきましたが、一生懸命取り組んでいらっしゃる方も中にはいらっしゃいます。そして、二酸化炭素を少しでも減らす品川区であっていただきたいと要望して、質問を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"成果報告書の１３１ページ、公園管理に関連いたしまして、それから、１３２ページ都市開発に関連して質問をします。お伺いしたいのは、もしくは品川区の考え方をしていくべきと考えますが、。","respondent":"松代道路公園課長","answer":"明らか不適切な使い方といったものを注意しまして、取り締まりという感じではございませんが、不適切なものに対して対応しているというのが現実です。引き続きいろいろと検討している状況ですが、今、取り組んでいるところです。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"もちろん人権は守らなきゃいけない、それは絶対にそのとおりかもしれませんけど、でもそれでいいんですか。アルミ缶の回収で自活をしているわけですから、今までと同じ考え方でいいんですかということをお伺いしているわけですので、ありがたいんですが。","respondent":"中谷まちづくり事業部長","answer":"ホームレスについての対応の都の提案を了承し、各地区ごとに収容施設等をつくりながら、この問題に対応しようです。これについては強力に対応していこうということで、話し合いを進めたところですので、よろしくご理解のほどをお願いいたします。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問・要望","question":"やってほしいと求めましたけど、そういう内容では解決できないんじゃないでしょうかというところなんですよ、何回も言いますように。例えば、２３区が共同で施設をつくって、施設入所をお願いする、それもやっておりますよ、でも入らないんですから、こういう方々は。","respondent":"濱野助役","answer":"一般的な対応しかできないわけでありますけれども、そういう不法行為に至らないような努力というのを区はとることが肝要だと考えています。いわゆる緊急シェルターをつくる予定ですけれども、３００名収容の施設でありますから、一番肝要なことだろうと考えています。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"最終的には個人の意思ですから、でも、その行為によってもたらされる結果に対しては責任をとってもらうしかないんじゃないでしょうか。施設をつくって、入ってくださいとお願いしてもだめなわけですから、そこら辺をもう一言、できれば区長から答弁いただければ、ありがたいんですが。","respondent":"高橋区長","answer":"品川区がどうも住みづらけば他区に行っていただけるでしょうし、やはりそういう方法も考えないと、ホームレスの問題は解決がつかないと思っています。人権の問題だけじゃなくて、やはり、公共の福祉というものも考えませんと、この問題は解決しないと考えております。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"意見","question":"今度、臨海線が開通をしてまいります。ところが、これからりんかい線が開通するその後の品川区の大井町に対する再開発の考え方をお聞かせください、お願いいたしますとの意見を述べました。","respondent":"南雲都市開発課長","answer":"そのターミナル性が高まるということで、その周辺部でも、これまで大井町になかったような機能を何とか導入できないかということです。駅の東側、西側の何カ所かで、今後の取り組みに向けて協議を行っている状況です。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"時間もあれですからまとめますけど、これから品川区はどういうふうにしていこうかという大きな絵がなかなか見えてこないというのは、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"金高委員","kind":"質問・要望","question":"トータルは、午前中出ておりましたけれども、２１６カ所ありますけれども、その辺のところの数をちょっと教えてほしいと求めました。総合トータルでなくて、それぞれの分野においての公園の数をお教え願いたいと思います。","respondent":"岩田管理工事課長","answer":"児童遊園が５６カ所、特定児童遊園が２５カ所、合計で２０８カ所です。それと、海上公園を含みますが、区内にあります都立公園が９カ所、総合計で２１７カ所の公園が区内に存在いたします。","id":"exchange-027"},{"speaker":"金高委員","kind":"質問・要望","question":"例えばつくったときから公園の改修に至る耐用年数といいますか、いろいろ器具があるわけですけれども、何年に１回ぐらいの割合で改良をしていくのか。例えば、５年なのか、１０年なのか、１５年なのか、その辺をお聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"押し並べて平均しますと、１５年から２０年ぐらいで全面改修というような、全面的につくり直すということを行ってまいりました。しかし、日々の日常管理をきちっと小まめに行うことによって、できるだけ寿命を伸ばしていくということを心がけているところです。","id":"exchange-028"},{"speaker":"金高委員","kind":"意見","question":"１５年ないし２０年ということで、非常に長期にわたっての改修ということであります。単に児童遊園としての改良なのか、ほかにもっと有効な活用をする方向も含めての改良なのか、その辺をお聞かせ願いたいと思いますとの意見を述べました。","respondent":"岩田管理工事課長","answer":"ご指摘の場所は、立会川児童遊園その２というところだろうと思うんですけれども、ちょっと細かいデータが手元にございませんが、昭和４９年２月２３日に開設しておりますので、ここから見ますと、途中で１回ぐらい、全面改修をしたんではなかろうかと思われます。","id":"exchange-029"},{"speaker":"金高委員","kind":"質問","question":"改良ということでそれぞれ出ておりますけれども、８月２日に、地元の方々に対して改良工事の内容等の説明会を行ったということを伺っております。８月２日になされた説明会について、どういう問題点があったのか、お聞かせ願いたいと思います。","respondent":"岩田管理工事課長","answer":"私ども、設計に先立ちまして、地域の方、町会の方を含めた沿道の地域の方に集まっていただきまして、委員、ご指摘のように説明会を行いました。小さなお子様が遊ぶ場所が限られてまいりますので、どこか１カ所に集めて、調整をしております。","id":"exchange-030"},{"speaker":"金高委員","kind":"質問・要望","question":"３カ所ですか、一般の民家が隣接しているということがありますので、近隣の隣接する方々のご意見も多々あると思います。できるならば、その点はどういうふうにお考えか、お聞かせ願いたいと思います。","respondent":"岩田管理工事課長","answer":"夏場、直接日光が当たらないようにということで、日除けを兼ねて使うものです。見通しをよくして、明るいオープン空間をつくってほしいという要望もありますので、地元の方との話し合いの中で調整をしてまいりたいと思います。","id":"exchange-031"},{"speaker":"金高委員","kind":"質問・要望","question":"公園というものは、確かに１年間ずっと使うわけでありますけれども、地元の方にも伺っております。これは希望でありますので、要望にとどめますけども、ぜひ、その辺のところも含めて検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"沢田委員","kind":"質問・要望","question":"議会が以前求めたものにこたえておりますし、環状高速がこれで一つのループになるわけで、そういう意味では交通の緩和が期待される面がある。時間の関係で、私は、ルートの問題と、排気問題の２点について質問したいと思います。","respondent":"伊佐都市計画課長","answer":"まだ事業費の詳細な検討はしていないですが、これまでのいろいろな検討の中で、今回の説明会でも。それを設定するのができるだけ少ないルートということで、目黒川の地下ルートを採用するに至ったという経緯があるという説明を受けております。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"少しでもゲートシティを南側に寄せてほしいという要求を出したときに、いや、寄せることは不可能だと言って拒否したんですよね。だから、なぜこのルートを通ったのかというのは、大変、私は心配するところですけれども、その辺はいかがか尋ねました。","respondent":"伊佐都市計画課長","answer":"新宿線の開通は平成１８年の予定をしておりますが、その段階で料金改定が１回、予定されている。支持層が地下約１８ｍから２０ｍのところにある、シールドのトンネルの上から３０ｍ下げて計画してございまして、ないという説明を受けてあります。","id":"exchange-034"},{"speaker":"沢田委員","kind":"質問・要望","question":"事業効果はある、採算ベースに乗るということですが、具体的なデータは出されているんでしょうか、もしあれば、示していただきたい。やらないというのはちょっと考えづらいところなんですけど、そこら辺についてもう一度お尋ねしたい。","respondent":"伊佐都市計画課長","answer":"過去に相当な集積がございまして、これを東京都の土木技術研究所というところが収集してございまして、これをもとに分析を行ったです。","id":"exchange-035"},{"speaker":"沢田委員","kind":"質問・要望","question":"それを排気するとなると、周辺に相当まとめて出すわけですから、大きな環境悪化が予想されるんです。前に私、建設委員会で、脱硫装置も含めて浄化装置を検討できないかと聞いたんですが、その後、いかがか尋ねました。","respondent":"伊佐都市計画課長","answer":"きちんと説明していくですので、区としては、その推移を見守ってまいりたいと考えています。２年ほど実験にかかるですので、今後の検討課題ですが、その時点の最新の装置を採用していただくように要望してまいりたいと考えています。","id":"exchange-036"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、目黒川の浄化計画についてお尋ねしたいんですが、浄化計画は持っているんでしょうか。そこを、説明願いたいと思います。","respondent":"北村下水道河川課長","answer":"目黒川に関しましては、日常の浄化対策といたしましては、浚渫を行うとかいった対応を行っております。今、特に計画に上がっているものはございませんが、今後ともいろいろ対策について検討していく必要はあろうかと考えているところです。","id":"exchange-037"},{"speaker":"沢田委員","kind":"質問","question":"縦断する格好で流れている目黒川ですから、何とか、これを少しでも清流化ができることを期待したいと思うんです。ちょっと話がありました落合の処理場のほうから３万ｔ余の処理水を持ってきて、ちょっとデータがそちらにあったら、教えていただけますか。","respondent":"北村下水道河川課長","answer":"具体的なデータについては、ちょっと手元にございませんので、後ほど回答させていただきたいと思います。","id":"exchange-038"},{"speaker":"沢田委員","kind":"質問","question":"どうやら荏原調整池のほうも２０万ｔ稼働しますし、これからはやっぱり清流化に向かって知恵を出し、進めるべきときなんじゃないかと思うんです。３万ｔプラスアルファを買うみたいな形でやることがかなり即効性があるんじゃないのかなと思うんですけれども、その辺の考え方はいかがか尋ねました。","respondent":"北村下水道河川課長","answer":"水質監視データの推移から補足してご説明いたします。そういうものとも調整をとりながら、具体的に導水できるようなチャンスがありましたら、積極的に連携して取り組んでいきたいと考えているところです。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その数字を見て、今まで気がつかなかったんですが、かなりの変化に驚いたんで、ちょっと確認させてもらいたいと思います。ここまで差が出てしまうということが、補助金とかの問題もあると思いますけど、もっと支払いの平準化ができないのかなという意味で質問をします。","respondent":"岩田管理工事課長、市岡企画財政課長","answer":"詳細な部分は、申しわけございませんが、ちょっと手元に資料がございません。どうしても４、５月に行われるということで、一般論的にはある得る話です。市街地再開発事業の東五反田二丁目第１地区の補助金の支出、３月３１日時点では、約５０％程度の支出しか行われていないという現状があります。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２点目に、６億円からを先に支払いして、ちょっとお聞きしたいんです。今言ったように、契約の関係で、もう既にどうしようもない部分かもしれないんですけど、そういう点は一緒に検討なさっていらっしゃったんか尋ねました。","respondent":"田村住宅課長","answer":"平成１５年２月に一緒に買取りということですが、６億１,０００万円の補助金を得るために、登記等を自前でやっております。できるできないというあれよりも、やはり話し合いの場を持って、意向を含めて相手方に伝えてみたいと考えております。","id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは固定資産税ですから、その辺を考えた場合に、その辺の民間的な考え方を取り入れてもらうことができないのかなと思いました。は今後の問題ということで、要望で結構です。","respondent":"宍戸ＩＳＯ担当課長","answer":"区がＩＳＯに取り組むことの発端となったものも、区がまず取り組んで、これからの課題になってくると思います。時間をかけ、丁寧にやっていきたいと思いますので、ご理解のほどをよろしくお願いいたします。","id":"exchange-042"},{"speaker":"鶴委員","kind":"質問・要望","question":"地域の皆さん方の長年の要望でもございましたし、平成５年の予算特別委員会、平成６年９月の建設委員会等々でお尋ねいたしました。今を含めてですが、今後はどういうふうなＰＲをされているのか、お聞かせほしいと求めました。","respondent":"松代道路公園課長、伊佐都市計画課長","answer":"その際には、１０年を記念してサメ水槽を設けるというようなことから、今まで以上にいろいろな形でＰＲを差し上げました。そこの中には区民割引といったものも付け加えまして、利用者の方々に… りんかい線のホームの工事が進んでおりまして、これが開通時点、平成１４年１２月に大崎駅に停車の予定と聞いてあります。","id":"exchange-043"},{"speaker":"鶴委員","kind":"提案","question":"９１基のコンテナについては、地域の皆さん方の住民参加型のフラワーロード化したらどうかという提案に対し、ご説明をしてほしいと求めました。あるいは予算特別委員会等でもそのことを要望してまいりましたが、ないか、お聞かせほしいと求めました。","respondent":"岩田管理工事課長、松代道路公園課長、伊佐都市計画課長","answer":"工夫をしながら、ツタ性の植物をはわせまして、目に見えるみどりを多くするように努力をしております。現在、今後も検討してまいりますので… デザインにつきましては、当時、いろいろと検討されて、今のような海をイメージ化した青いものに、イルカ等が走っているようなものです。そういったことで… 今後の動向を見ながら、引き続き、研究してまいりたいです。乗降客も増えてまいりますでしょうし、今後とも、ＪＲに強く要望してまいりたいと考えています。","id":"exchange-044"},{"speaker":"鶴委員","kind":"質問","question":"塗り変えるのは大変ですから、いそげ」というようなポスターがあるわけでしょ、そういうようなことをラッピングでやるべきではないかと。やれば、すばらしいが効果が生まれると思いますが、いかがですかね。","respondent":"松代道路公園課長","answer":"バスの件につきましては、いろいろと検討しなきゃならないと考えていますので、その中で検討します。","id":"exchange-045"},{"speaker":"本間委員","kind":"意見","question":"私は、１２５ページ、高潮護岸管理費と、１２８ページから１２９ページにかけまして、河川総務費の中から数点をお願いしたいと思います。その後の経過について、あるいは、これからの見通しについてお知らせくださいとの意見を述べました。","respondent":"松代道路公園課長","answer":"護岸そのものの構造が、そういったものに対応したものとしてつくっておりません。現在、港湾局のほうでも、これからのバリアフリー化に向けて、どういった形がとれるかということでいろいろ検討していると聞いてあります。","id":"exchange-046"},{"speaker":"本間委員","kind":"質問・要望","question":"あのままだと、何かつながるような感じに、今朝、受けとめてはみたんですが、間違いでしょうか。清掃作業と消毒作業も、東京都港湾局の部分の作業として含むものかどうか、お願いします。","respondent":"松代道路公園課長","answer":"私どものほうが港湾局のほうと協定を結びまして、日常の管理をしています。今、委員、ご質問の桜の剪定、また、害虫駆除、それと、一般区民に開放しています部分の清掃等、すべて区がやってあります。","id":"exchange-047"},{"speaker":"本間委員","kind":"質問・要望","question":"特に消毒作業につきましては、時期を外さない形の消毒作業に努めていただきたいということが要望です。","respondent":"松代道路公園課長","answer":"私どもが、日常、管理してございまして、主に目黒川沿い、また立会川沿いに、計１万数千袋配置しています。ただ、私どもは、とにかく緊急時に使えるように、減った分は必ず補充するといった対応をとってあります。","id":"exchange-048"},{"speaker":"本間委員","kind":"質問","question":"ブルーのシートにロープがかかっていて、どうなんですか、周りに置いておけばよろしいんですか。それから、防水板設置工事助成の中身について、簡単にひとつお願いします。","respondent":"北村下水道河川課長","answer":"防水板設置工事助成費の件につきまして、ご説明いたします。最高限度額１００万円ですが、個人の場合で４分の３の、設置費用の一部を助成しているという形のものです。","id":"exchange-049"},{"speaker":"本間委員","kind":"意見","question":"そういうふうな部分につきまして、費用がかかるという部分がどの程度伝わっているのか、これからご指導をきちっとお願いしたいと思います。路上にたくさん出ている場合がありますので、その辺の部分のご指導方について、お考えをお願いしますとの意見を述べました。","respondent":"中村交通安全担当課長","answer":"私どもも、区の周辺あたりで目につきましたら、その都度、撤去等をしているわけです。そこまですべて手が回らない部分もあると思いますので、その辺のところは、ご了解いただきたいと思います。","id":"exchange-050"},{"speaker":"本間委員","kind":"意見","question":"３番目は、新浜川橋の地下通路の安全整備対策についてお尋ねします。この部分をどのように把握されているのか、お知らせ願いたいと思いますとの意見を述べました。","respondent":"松代道路公園課長","answer":"数カ月も前にそういったことがございました。今、現状でどうなっているのか、ちょっと把握してございません。","id":"exchange-051"},{"speaker":"本間委員","kind":"質問","question":"これは私の全く個人的な見解ですけれども、何か防災用の備蓄的な倉庫にするとか、何か新しい試みができないものなんでしょうか。あそこはどうしても通路ということで、それ以外のものに使用してはいけないというふうに制約された条件なんかがあるんでしょうか、お答え願います。","respondent":"松代道路公園課長","answer":"あそこは、地下道を通ればもちろん安全ですけども、一般の方は上のほうを通っているという状況にあります。再度その旨をお伝えしまして、対応方、依頼をしたいと考えています。","id":"exchange-052"},{"speaker":"本間委員","kind":"質問・要望","question":"どうか、安全な通路として確保していただきたいということをお願いして、私の発言を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"本多委員","kind":"質問","question":"お伺いいたしますが、付帯設備というものは、時代とともに相当変わってきていると思うんです。これから、ケーブルですとか、ダストシュートですとか、そういった付帯設備について、どのような考え方をお持ちなのか、まずお聞きします。","respondent":"田村住宅課長","answer":"荏原市場跡地につきましては、現在、ＣＡＴＶ敷設を前提として考えております。ＣＡＴＶを中心とした敷設工事を、現在、検討を進めているところです。","id":"exchange-054"},{"speaker":"本多委員","kind":"質問","question":"国庫補助金が６億１,８００万円ということで、６億１,８００万円という部分の使途について、予算についてちょっとお聞きしたいと思うんです。それと、ちょっと話が飛躍しちゃうんですけれども、光ファイバーのこれからの考え方について、関連してお聞きしたいと思うんです。","respondent":"田村住宅課長、桑村政策担当課長、市岡企画財政課長","answer":"これは、あくまで、先ほど申し上げました公営住宅等の供給促進事業というような助成です。予定になかったものが入ったですが、一般財源として入りましたの… 民間のいわゆるＮＴＴとか、東京電力とか、いわゆる需要が非常に強いものです。もう一つは、賃貸住宅にそういった仕様を入れることが… １点だけですが、特定財源ですので、そのように充てします。","id":"exchange-055"},{"speaker":"本多委員","kind":"質問・要望","question":"もうわかっているつもりなんですけども、差し引いた費用の考え方というのを先ほどお聞きしたんですけども、そこを改めてお伺いしたい。その辺は当然、公と民との役割分担というものがありますけども、その辺についての考え方をお聞かせほしいと求めました。","respondent":"田村住宅課長、田平建築課長、市岡企画財政課長","answer":"今回、買取特公賃制度は引き続き活用して、ただ、土地費相当分を先行取得という形ですので、６億１,８００万円余は補助金として受け入れる。ですから… ご質問の光ファイバーにつきましては、今後の普及と、品川区としてどう取り組めばいいのかをやっぱり研究する必要があると思います。… 例えば家賃にその経費がどういうふうに跳ね返るか、そういうバランスをよく考えて、公的住宅の役割の中で検討をさせていただきたいと思います。","id":"exchange-056"},{"speaker":"北野委員","kind":"質問・要望","question":"基本計画に対しての要望を聞く場と、工事説明会の要望の場では、分けて設定すべきではないかと考えます。区の基本的な説明会の考え方を伺います。","respondent":"岩田管理工事課長","answer":"幅広い地域の方、区内全域の方の意見を網羅する形で、区のほうで最終的に決定をするという考え方です。地域の説明会も行って、最終的に区で基本的な考え方を定め、ご了承いただいたという経緯です。","id":"exchange-057"},{"speaker":"北野委員","kind":"質問・要望","question":"市民とかかわる場では、常に対話というスタンスを持っていただきたいと、これは要望しておきます。夏場には１時間に１００mmを超える大雨が降っていますので、公園の中で処理できるようになっているのでしょうか、お伺いしたいと思います。","respondent":"岩田管理工事課長","answer":"現在、詳細な部分につきましては、設計をさせていただいている最中ですが、当然のことながら、浸透対策というのは区の基本ですので、この公園も例外なく、浸水対策上、いろいろな配慮を行っていく予定です。","id":"exchange-058"},{"speaker":"北野委員","kind":"質問","question":"防災機能を持った公園ということですから、その点について、どうでしょうか。ちょっともう１回、お伺いします。","respondent":"岩田管理工事課長","answer":"委員のご要望は当然のことでございまして、私どもでも、いろいろな設備の中で、地中浸透ができるような施設整備を行ってまいります。５０mm程度の雨については、中央公園と住宅ともに、５０mmの雨には十分耐えられる対策をとっていく所存です。","id":"exchange-059"},{"speaker":"北野委員","kind":"質問・要望","question":"それから、放置自転車対策について伺います。収容台数は、今まで入れられていた台数よりも何台減ったのでしょうか、お伺いします。","respondent":"中村交通安全担当課長","answer":"ただ、実態としましては、今年の５月に調査した段階での池上通り高架下の駐輪台数をすべて合わせますと１,９３５台となっています。新しく整備しました駐輪場につきましては１,３００台ということで、現在のところ、ほぼ何とか収容できている状態ではないかと考えております。","id":"exchange-060"},{"speaker":"北野委員","kind":"質問","question":"これから、有料であっても、駐輪場の増設の考えというのはあるのでしょうか。広報「しながわ」などでは特集していますけれども、積極的なＰＲが必要ではないかなと考えますけれども、いかがか尋ねました。","respondent":"中村交通安全担当課長","answer":"東口のほうでも１００台、西口に１００台あるということで、ほぼ何とか収容できるのかなです。東京都とお話をして進めなきゃならないという部分はありますけども、もし確保できれば、そちらのほうにも増設ということも考えてあります。","id":"exchange-061"},{"speaker":"北野委員","kind":"質問","question":"４０台から５０台の待機の方がいらっしゃるというなんですけど、車いすが通れないなどの問題も、やはり現状では起こっているわけです。優しいまちづくり推進計画に向けてはどのように考えているのか、今後の区としてのお考えをお伺いしたいと思います。","respondent":"田平建築課長","answer":"今後の施設の新築、改築等の機会をとらえまして、その部分については、施設の管理者と協議してまいります。既存の施設を、これはなかなか難しい面もございまして、今後の改築等の機会をとらえて協議させていただきたいと思います。","id":"exchange-062"},{"speaker":"北野委員","kind":"質問","question":"そういうところで、区はどういうふうに考えているのかということを、ちょっとお伺いしたんです。交通安全対策について伺いますけれども、たしかヒヤリ地図を作成していると思うんですけれども、その状況についてお伺いしたいと思います。","respondent":"岩田管理工事課長、中村交通安全担当課長","answer":"歩道においては、車いす対応として２cm段差まで下げるという対策については、昭和６０年代で終わっております。したがいまして、駅からどこどこの施設までのバリアフリー対策を今やらなければいけないというようなものは、特段… 当区のほうとしまして、交通安全施設の整備の検討材料にもするというような考え方で、ヒヤリ地図を進めているところです。","id":"exchange-063"},{"speaker":"北野委員","kind":"質問・要望","question":"これは要望です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"藤田委員","kind":"質問","question":"２点目は、公園についての考え方、３点目が、旗の台駅舎の改修工事につきまして、以上、３点をお伺いいたします。そこで、当初の計画と何か変更があったのか、また、計画どおり話が進んでいるのか、どの辺まで話が進んでいるのか、その辺をお伺いしたいと思います。","respondent":"中村交通安全担当課長、岩田管理工事課長、伊佐都市計画課長","answer":"補助２６号線が開通しました際に、そちらのほうの秒数を取ったということで、区役所前交差点の信号のサイクルの秒数がちょっと長くなってあります。… 私どもも地域の説明会なんかに行きましても、子どもがいないんだから、遊具は要らないというような声が非常に強くなっていることは事実です。… 先般、９月２２日に地元で説明会を東急が開催したと聞いてあります。","id":"exchange-065"},{"speaker":"藤田委員","kind":"質問・要望","question":"区としてどのような要望をされているのか聞きますと、また時間がなくなってしまいますので、私がお話しします。これは取り引きじゃないんですけど、東急と、この際、解決しなければならない課題と思いますけれども、お考えをお聞かせほしいと求めました。","respondent":"伊佐都市計画課長、岩田管理工事課長","answer":"それから、駐輪場につきましては、当区といたしましても、旗の台の駐輪問題は認識しています。具体活動については、今後の調整になりますが、一定の対策を講じてまいりたいと考えています。 私ども、工夫しながら、ご提案の趣旨に沿っていろいろ公園づくりを進めてまいります。","id":"exchange-066"},{"speaker":"藤田委員","kind":"質問","question":"輸送量が当然アップするわけですから、周辺の区道は提供するは、いろいろ譲歩しているわけですね。ですから、駐輪場につきましても、この際、この機会を逃しますと。","respondent":"中谷まちづくり事業部長、岩田管理工事課長","answer":"今回、これがチャンスですので、私たちも、今現在、駐輪場設置に向けて強力に東急に働きかけておりますので、しばらく時間をいただきたい思います。よろしくお願いします。 トイレにつきましては、少し検討するお時間をいただきたいと思います。","id":"exchange-067"},{"speaker":"石田委員","kind":"質問・要望","question":"納得をいただきながら進めてほしいと求めましたので、その点、要望だけをしておきます。これについての財源はどこから出ているのかということも含めて、教えてほしいと求めました。","respondent":"岩田管理工事課長、市岡企画財政課長","answer":"公共基準点ですけれども、現在、区では実施計画に基づきまして、２級基準点については、平成３年度までに４０点設置済みです。全体計画が３１０点設置する予定ですけれども、今年の３月末現在で、１８７点設置が終了しております。 区が新たに道路を認定するというものについては、若干ですが、財調の中で算定をされております。財調の中の特別交付金で約４分の１程度が算定されておりまして、標準算定ではなくて、特別交付金で措置をするという状況になっております。","id":"exchange-068"},{"speaker":"石田委員","kind":"質問","question":"平成１２年度からずっと３年間に分けて、普通民間であると、土地の所有者が境界確定はやると思うんです。国から何らかの委託費でも何でも構いませんけど、そこら辺の考え方というのはないのかというのを、ちょっとお聞きしておきます。","respondent":"岩田管理工事課長","answer":"ご説明しますと、道路法に基づいて区市町村が管理をするということで、品川区が管理をしているわけです。平成１２年度から３カ年にわたって、法定国有地につきまして、区に無償譲渡を受ける作業を進めているものです。","id":"exchange-069"},{"speaker":"石田委員","kind":"質問","question":"どうして公簿売買にするんですか。この先の方向性をどのように考えていらっしゃるのかというところを、もう１点、お聞きします。","respondent":"岩田管理工事課長","answer":"Ｂからは、Ｂが持っている資料等を提出もらって判こを押してもらうという、いわゆる原因者負担の原則が通例になってあります。公共物と民地との境界確定も、都も区も同じですけれども、原因者の方が費用を負担して確定業務を進めるという通例に従って、今までやっております。","id":"exchange-070"},{"speaker":"石田委員","kind":"質問・要望","question":"私も、去年の８月１１日に区長会で要望されたという内容を読ませていただきましたけれども、やっぱり何かものをどんどん申していくとか。１００年もかかるような進捗状況にしかならないと私は思うんで、この辺のものの考え方を、どういうふうにとらえられているのかということをもう１回。","respondent":"岩田管理工事課長","answer":"私レベルにトーンダウンしてお答えしますと、当然、確定はいたしません。それを抜きに公簿売買はいろいろ問題があるから云々ということに、即にはならないのではないかと考えています。","id":"exchange-071"},{"speaker":"宮崎委員","kind":"質問","question":"私からは、区民住宅の家賃の問題と、区営住宅の問題の２点に絞って、お話をお伺いしたいと思います。２０年後の出口のところでは、どういうふうに負担が変わっていくのか、まずお伺いをしたいと思います。","respondent":"田村住宅課長","answer":"３.５％ずつ上昇していくという形です。今度３段階の部分が５段階になりまして、２０年間、家賃助成をもらっていくという制度です。","id":"exchange-072"},{"speaker":"宮崎委員","kind":"質問","question":"具体的にどういう変化になっていくのかというところで、運営費に占める割合のところで、ちょっともう１回お伺いしたいと思います。そこのところを心配されている声もありますので、ちょっとそこの考え方をお伺いしたいと思います。","respondent":"田村住宅課長","answer":"先ほど、ご質問の中にありました家賃の補助率ですが、基本的な考え方は、要は、当初２０年間の設定家賃を行います。すり着いた後の対応ですが、２０年まで若干あるんで、本来の家賃という形になるかと思います。","id":"exchange-073"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとここのところを、改めてお伺いしたい。ちょっと区のほうの基本的な考え方をお伺いしたいと思います。","respondent":"田村住宅課長","answer":"一気に１９年、２０年でどおんと上がるんじゃなくて、傾斜していくという形です。２０年後の家賃につきましては、それが２０年でもう打ち切りですので、当初の本来の家賃という形になるということです。","id":"exchange-074"},{"speaker":"宮崎委員","kind":"質問・要望","question":"実際にリストラにあってどうしようかという相談があって、ぜひ、今から対応を考えていただきたいということを要望しておきたいと思います。実際の時点で、どのぐらいの家賃を想定されているのかお伺いしたいと思います。","respondent":"山室住宅指導担当部長、田村住宅課長","answer":"ご指摘のとおり、率を５％から３.５％に変更したということで、早く到達してしまうということもあります。当然、入居者の方にご説明するんではなくて… 平成１１年度にフラットという制度ができました。３,０００円、３,５００円と幾つかのシミュレーションはしておりますが、これから決めていきたいと考えております。","id":"exchange-075"},{"speaker":"宮崎委員","kind":"質問","question":"この仕組みがどうなっているのか、補助がどういうふうに変わるのか、ちょっと教えてほしいと求めました。それから実際に払う側の家賃としては、どのぐらいのところを想定していくのかというところが、あったらお願いしたいと思います。","respondent":"田村住宅課長","answer":"では、フラット家賃のご説明をさせていただきたいと思います。６０m2が１２万円という形になりますので、メリット、デメリットを含めて決めていかなきゃならないと考えております。","id":"exchange-076"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっとお伺いしたいんですけども、今後の対応、区の考え方をお伺いをしたいと思います。もう一つは、それとあわせて、実際に建て替えの計画等があったらお伺いしたいと思います。","respondent":"田村住宅課長","answer":"後段の建て替えする予定は、区内に聞いておりません。都からの移管ですが、平成１２年４月の都区制度改革のときに、東京都から移管協議団地１０団地を協議してほしいという形の協議がございました。","id":"exchange-077"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、ちょっと後段のところがよくわからなかったんで、もう１回、説明いただきたいんです。そういうところも含めて、東京都の計画だけじゃなくて、区として何か考えているところがあるかどうかということを、一つお伺いしたいと思います。","respondent":"田村住宅課長","answer":"建え替え時移管という制度で、区が引き受けた後に建て替えるというような、西大井六丁目以外のそういう新たな協議は現在のところないです。まだそれほど年数が経ってない団地をもらっていますので、建て替えの計画も、区の中ではございません。","id":"exchange-078"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうですか。じゃあ、ここのところを要望して終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"藤原委員","kind":"質問","question":"建築行政費に係わることでお伺いしますが、今年、新宿のビルで火災が起きまして、４４名の方が亡くなるということがありました。品川区も、一斉に雑居ビル等の査察を、グループを組んで行っているということでありますが、まず、具体的に査察の内容についてお伺いします。","respondent":"田平建築課長","answer":"３階以上の階をキャバレー、大井町などで、きょう現在時点までで９６件の査察を終えております。消防署も、三消防署で１９班を編成しておりまして、私どもの部と合同で調査をしております。","id":"exchange-080"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、消防署というお話がありましたが、消防署と区がペアを組んでそのような事業をしたというのはあまりないと思うんですけれども、一緒に組んで査察等をしたことによっての利点というのがあれば、教えていただきたいんですけれども。","respondent":"田平建築課長","answer":"消防法に基づく設計書をまず点検をしてもらって、合意ならば、最終的に確認申請を下ろすという作業で、これまでも消防署とは連携を保っております。しかし、こういうふうに何班編成でもって職員が合同で査察に入るというのは、このたび新しい出来事だと考えています。","id":"exchange-081"},{"speaker":"藤原委員","kind":"質問","question":"実際に、査察を行った結果、違法性があったビルには、どのような指導をしているんか尋ねました。","respondent":"田平建築課長","answer":"こういうビルについては、まず、点検の要請書を出しますが、既に５０件ぐらいは出しております。区のほうから、１１月ごろから出すための準備を、今整えているところです。","id":"exchange-082"},{"speaker":"藤原委員","kind":"質問","question":"１１月ごろから出すということですが、現在、査察した中で、違法性があるところについての再査察といいますか、それはどのような形でするのか説明を求めました。","respondent":"田平建築課長","answer":"私どもの指導書、あるいは安全点検要請書に基づきましても、ビルの管理者が一向に改めないようでしたら、直接職員が出向いたり、また新たな指導書を送付したり、その次のステップとして、違反個所の目立つものについては対処してまいりたいと考えております。","id":"exchange-083"},{"speaker":"藤原委員","kind":"質問","question":"何回も直接指導をして、こういうふうに直してくださいと言っても、最終的に言うことを聞いていただけなかったら、行政指導しても聞いてくれないビルに関しては、法的には措置をとるんか尋ねました。","respondent":"田平建築課長","answer":"違反性のひどいものに関しては、建築基準法の第９条、違反建築物の取締りの条項があります。違反の著しくひどいものに関しては、そういう法的な措置も視野に入れながらやっていきたいと考えています。","id":"exchange-084"},{"speaker":"藤原委員","kind":"確認","question":"次は、建築確認申請のことについてお伺いします。建築確認申請は、そのことが言われてから２年経ちますが、その後の実態はどのようになっているんか尋ねました。","respondent":"田平建築課長","answer":"民間機関も、現在時点では１０社になっております。２,９９０件中１１２件で、率に直しますと３.７％なわけですけど、私どもとしては、まだ率が低いなと認識しております。","id":"exchange-085"},{"speaker":"藤原委員","kind":"質問・要望","question":"約４％が民間ということは、区が９６％ちょっとをしていると思うんですけれども、ほかの区の状況というのがもしわかれば教えていただきたいんですけれども。","respondent":"田平建築課長","answer":"課長会等で議論していると、木造の少ない区、２割近くが民間機関のほうに流れているということも聞き及んでおります。ただ、こういうデータはあまり区の名誉にはならないので、公表をしたがらないという現実もあります。","id":"exchange-086"},{"speaker":"藤原委員","kind":"質問","question":"ほかの区は２割ぐらい民間にもう流れているというお話でしたが、改めて、その中で、品川区は４％ぐらいしか流れておらず、９６％以上は区に来ているということで、課長が考える中で一番の原因を、何か思い当たることがあれば教えていただけますか。","respondent":"田平建築課長","answer":"私どもでは３.７％で、これは多分２３区中では一番少ないほうの比率じゃないかと思っています。別に手数料が、２３区中うちが一番安いというわけでもございませんで、やはり信頼度かなと考えています。","id":"exchange-087"},{"speaker":"藤原委員","kind":"質問","question":"続きまして、最後に１点、仮称品川中央公園のことについて、お伺いします。今まで品川区にある公園との違い、どんな特徴を持っているか、その１点についてお伺いします。","respondent":"岩田管理工事課長","answer":"先ほどもちょっとご説明いたしましたけども、防災時には、品川区役所を中心とした防災活動の拠点となるべき施設であるという位置づけです。","id":"exchange-088"},{"speaker":"松澤委員","kind":"質問・要望","question":"成果報告書の１３４ページ、１点目は公園管理費に関連して、戸越公園についてお伺いをしたいと思います。その経緯について、わかりましたら、お教えほしいと求めました。","respondent":"松代道路公園課長","answer":"当日、その破損部分をのぞきまして、当日中に復旧し、翌１７日からご利用いただいたという状況にあります。今も、引き続き荏原警察署のほうで、この犯人等の捜査に当たっていただいているところです。","id":"exchange-089"},{"speaker":"松澤委員","kind":"質問","question":"被害金額がどれぐらいなのか、あるいは、いつごろ直るのか、補正を組んでまででも直していただけるのかどうかということ。ちょっと書いてありましたけど、その辺の対策については、どのように考えているんか尋ねました。","respondent":"松代道路公園課長","answer":"近隣の方が１１０番し、警察が対応しまして、解散をさせたという事実があります。これは、今、復旧に向けて設計をしてございまして、私どもが年間持ってあります公園維持費の中で対応して、年内にはすべて完了させる予定です。","id":"exchange-090"},{"speaker":"松澤委員","kind":"提案","question":"もう１点は、これから暗くなるのと、冬になりますのでひなたぼっこということで、やっぱりお年寄りが憩うものですから、できればベンチをもう少しね。ベンチそのものは、公園に幾つという規格があるのかどうかわかりませんけど、簡単に増やせるものなんか尋ねました。","respondent":"松代道路公園課長","answer":"それと、ベンチですが、ここも、若干ですけども、ホームレスがいまして、そういったことから、今、ベンチの数も慎重に対応しています。今の委員のお話もありますので、もう一度現地をよく見まして、対応したいと考えています。","id":"exchange-091"},{"speaker":"松澤委員","kind":"質問・要望","question":"同じところが質問がありましたけど、カーブで曲がっているものですから、斜めについているものですから滑るんですね。踏切の安全対策について、どうしてあれが木の踏切になっているのか、その辺のことをもしわかりましたら、お願いします。","respondent":"中村交通安全担当課長","answer":"少ないを考えながら、コンクリート製にするか、木製にするかということでやっておられるということです。どうしてもコンクリート製の連結軌道というんだそうですけど、それについては検討していきたいという、軌道担当の助役の回答でございました。","id":"exchange-092"},{"speaker":"松澤委員","kind":"質問・要望","question":"それと、滑りどめのテープじゃなくて、要望が実際にありますので、私も要望をまとめて持って行きますので、ひとつよろしくします。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"高木委員","kind":"質問","question":"百反随道というのが何年ごろにできたんでしょうか、４０年そこそこでしょうか。放置はいかがなものかなと思っておるわけですが、その点、まずお尋ねをしたいと思います。","respondent":"岩田管理工事課長","answer":"再検討をしておりまして、自転車の動線も考えた場合に、出てまいりました。再開発に合わせて検討しようということで、今、先送りする方向で考えております。","id":"exchange-094"},{"speaker":"高木委員","kind":"質問・要望","question":"そういうこと伺う感じはあったんですが、今年度決算の、百反歩道橋調査診断等委託の５７０万円何がしのことを言っているわけですか。最近、環状６号線のニューシティの前から大崎警察署のほうへ渡る歩道の状況はどうなっているかということは、知る人はもうすぐに描けますね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、水をどういうふうに動かすかということの基本的な考え方から、どうするかということもお願いしたいと思います。風の動きをどうするか、こういったエネルギーをどういうふうに活用するのかという、いかがか尋ねました。","respondent":"中村交通安全担当課長、岩田管理工事課長","answer":"補助２６号線につきましては、重ねて、また要望をしてまいりたいと思います。やはり荏原署のほうを通じまして、実態を把握していただいて、検討いただくということにしたいと思います。これがいわゆる滝のような形で、そこから下に落ちて、区役所に向かってせせらぎが流れてくるという基本的な考え方です。","id":"exchange-096"},{"speaker":"三上委員","kind":"質問","question":"品川区の基本的な考え方として、どなたでも結構ですから、伺っておきたいんです。どうなのかなと思いますので、一言、お願いしたいと思います。","respondent":"金井環境課長","answer":"風力発電は、委員、ご指摘のとおり、化石燃料を使わない発電の方式ということで、温暖化の問題も含めまして、国も力を入れてあります。そういうところはやっていきたいですので、私どもも、そういった認識はしっかり持っていきたいと考えております。","id":"exchange-097"},{"speaker":"築舘委員","kind":"質問","question":"１３３ページの品川シーサイド駅周辺整備事業に絡んで、ご質問をしたいと思います。その辺の構想は、今、どう描いていらっしゃるのかを説明するよう求めました。","respondent":"南雲都市開発課長","answer":"その中で、道路側の街路樹、それから中にできます広場ですとか、サンクンガーデンについても、今後も協議していきたいと考えております。事業者のほうとも、どのような樹木、樹種を植えるのかについて協議を行っていきたいと考えております。","id":"exchange-098"},{"speaker":"築舘委員","kind":"質問・要望","question":"ですから、フォレストですから、水とみどりのネットワークの中心に据えていただきたいと考えています。枯れる原因はどういうのが一番でしょうか、どんなぐあいになっておりますか、ちょっと説明を求めました。","respondent":"松代道路公園課長","answer":"私ども、渇水対策というものをつくりまして、対応したわけです。私ども、そういったことにならないように、地下水等を使いながら、潅水等して対応したところです。","id":"exchange-099"},{"speaker":"築舘委員","kind":"質問","question":"根が地下に張って大きくなってくるわけですから、いろいろ大変なことになってくるんじゃないかなと思うんですよ。これで、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"菊地委員","kind":"意見","question":"１２７ページの私道整備の問題、１３４ページの建築指導の問題から中高層建築物の開発環境指導要綱について、若干お尋ねをしたいと思います。","respondent":"中村交通安全担当課長","answer":"鉄道事業者は駐輪場を設置する場合、鉄道事業者が駐輪場を設置しなければならないとまで踏み込んだ部分はございませんので、現在のところ。","id":"exchange-101"},{"speaker":"菊地委員","kind":"質問","question":"大崎と大井町のことについてお聞きしたというわけではなくて、区内全域で有料化されている総台数と、空き状況をお聞きしたんです。こうした鉄道がある程度利用料の負担をしていくとかいった交渉も、実際には成り立つんではないかと思うんですけど、この辺ではどうでしょう。","respondent":"中村交通安全担当課長","answer":"これ以外に、整備センターのほうとか、東急、京急とそれぞれ実施されているところがあります。それぞれ具体的な状況に対応してということで申し入れをしていく必要があるんじゃないだろうかと考えております。","id":"exchange-102"},{"speaker":"菊地委員","kind":"質問・要望","question":"例えば通学している子どもたちを２人ぐらい持っていて、ぜひ、鉄道事業者の協力も求めるという形をとってほしいと求めました。それと、その辺の対策を、ちょっとお聞かせを願えればと思います。","respondent":"中村交通安全担当課長","answer":"これがちょっと見にくいということで、これに反射テープを張ったほうが見やすいのかなということで、対応をとった個所が２カ所ということです。まだ回答をいただいておりませんので、またあれば、確認して対応をとっていきたいと考えております。","id":"exchange-103"},{"speaker":"菊地委員","kind":"意見","question":"行政として要請をしたり、あるいは、整備に必要な資金援助といったことができるのかどうか。この辺の制度面について、ちょっとお知らせを願えればと思いますとの意見を述べました。","respondent":"岩田管理工事課長","answer":"あくまで、私道を持っておられる管理者の方が責任を持って対応していく。そのための援助等のご要請があれば、この私道整備事業の中で対応できるものもありますので、その場合は、ご相談に乗らせていただくです。","id":"exchange-104"},{"speaker":"菊地委員","kind":"確認","question":"ほんとうにお伺いをするだけになるかもしれませんけれども、第２条からは、設計に当たって配慮をすべきものが規定をされています。事業主が事前に細部にわたる調査を行ったのかどうか、この辺の確認ですけれども、それでいいという形で受け付けているのかどうか。","respondent":"浜脇住環境整備課長","answer":"紛争の関係ですか。第２条で責務というがございまして、そういう周辺の環境も考えながら設計をしているということで、設計をしたと答えていただいております。","id":"exchange-105"},{"speaker":"菊地委員","kind":"意見","question":"こういう内容については、区の要綱の中にあるこういうことをこういうふうに設計の中に取り入れたというような話をなさることはあまりないんですよね。","respondent":"浜脇住環境整備課長","answer":"要綱上にあるものを建築基準法の中に織り込むというのは、現段階では、厳しい状況であると考えております。","id":"exchange-106"},{"speaker":"辻委員","kind":"質問・要望","question":"スクランブル交差点のことが話に出ましたが、うちの三上委員のほうからの質問に関連して、ちょっとお伺いしておきたいんです。車が左折するときには、お互いに青同士ですか、左折する車というのはどうして歩行者を巻き込んじゃいけないことになる。","respondent":"中村交通安全担当課長","answer":"全国で１００カ所ばかり、歩行者と車の分離の歩車分離信号を設置して、検討するということを言われておりました。それぞれ現場を見ながら、こういうものが導入できるということであれば、導入の方向でそれぞれ警察のほうにも要請していきたいと考えております。","id":"exchange-107"},{"speaker":"辻委員","kind":"質問・要望","question":"障害者等、北品川の住民の方から要望を寄せていただいて、いろいろご意見もお伺いしたわけです。環境アセスのほうにも区長の意見が２回ほど求められるようになっているんですが、まずスケジュールをちょっと教えていただきたい、端的に。","respondent":"伊佐都市計画課長","answer":"今般、８月に開催されたものは都市計画素案の説明会です。その後、都市計画案ですが、これは来年５月ごろを目途に、説明会をまず持ちたいと、東京都から聞いてあります。","id":"exchange-108"},{"speaker":"辻委員","kind":"質問・要望","question":"区長として述べられる意見は、どこでまとめられるんですか。どこでまとめて区長の意見として取るのか、ちょっとお伺いします。","respondent":"伊佐都市計画課長","answer":"都市計画案に対する意見につきましては、意見照会がまいりましたら、区の都市計画審議会でご審議いただいて、まとめてまいります。それから、環境アセスメントのほうの手続につきましては、環境課のほうで取りまとめすると聞いてあります。","id":"exchange-109"},{"speaker":"辻委員","kind":"質問・要望","question":"ですから、住民の声、そしてまた、区としてもきちっとした声をくんでいただいて、東京都にぜひ反映させていただきたい。そのことを、きょうのところうは要望で終わりたいと思うんですが、今後またその中でいろいろ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"須藤委員","kind":"質問","question":"林和也委員が質問された、管理工事課長のほうで人工芝というお話をされたように記憶しているんですも、人工芝になさることなんでしょうか。その点だけ、まず１点、お願いします。","respondent":"岩田管理工事課長","answer":"議会にもご説明しましたし、広報「しながわ」でもお知らせしましたように、２００ｍトラックの中の部分につきましては、多目的に１年中使えるようにということで、天然芝ではなく人工芝で、現在、考えてあります。","id":"exchange-111"},{"speaker":"須藤委員","kind":"質問","question":"ほんとうの芝に触れるというところはなかなかないんで、そういう方向性で、ぜひ検討してもらいたいところなんです。シルバーセンターを２８度にし、ちょっと違うと思うんですけど、その辺はどうか尋ねました。","respondent":"岩田管理工事課長","answer":"これは自然芝を管理するためには、あそこの場合はできだけ開放していますが、冬の１２月から２月いっぱい一般開放を中止して、芝の養生をいたします。","id":"exchange-112"},{"speaker":"須藤委員","kind":"質問・要望","question":"あるいは前の青陵高校が使うというんですから、その辺は少し考慮をしていただきたいと、改めて要望します。それを足し算してみると、委託料と工事請負費というのはどういうふうな分け方があるのか、教えてほしいと求めました。","respondent":"松代道路公園課長","answer":"端的にお答えできるかどうかわかりませんが、工事費、もしくは委託費ということで記載をしています。例えば、私どもが清掃委託だとかをする場合には、路面維持の中で、路面清掃委託等々の内容で記載をさせていただいているものです。","id":"exchange-113"},{"speaker":"須藤委員","kind":"質問","question":"成果報告書の１２８ページ、大井町駅東口ペデストリアンデッキの補修工事が３,６００万円ですか。それは何か線引きがあるのか、そのときの状況によるものなのかを教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"成果報告書の１２８ページの書き方ですけれども、例えば大井町東口ペデストリアンデッキ補修工事は工事請負費です。最終的には、決算書の中にあるような各予算科目ごとに分けますと、こういう書き方になるです。","id":"exchange-114"},{"speaker":"須藤委員","kind":"意見","question":"それがね、足し算をしていくと、ペデストリアンデッキ補修工事が三千六百幾らで、工事請負費が３,７００万円と成果報告書ではなっていますよね。","respondent":"岩田管理工事課長","answer":"申しわけございません。明細書のほうの委託料の支出済額で見ていただきますと３,８６４万円となっていますが、この部分が、ちょうどこの金額になるです。","id":"exchange-115"},{"speaker":"須藤委員","kind":"質問","question":"理解しました。大井町線の駅の廃止もあるんじゃないかというようなことが、まちの人が言われているんですけども、そういうことは考えられているんか尋ねました。","respondent":"伊佐都市計画課長","answer":"大井町駅の改修ということですか。","id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/321088?Template=document&Id=1188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":108382,"voices":291}},{"id":"h13-20011010-4","meetingId":"h13-c-settlement","date":"2001年10月10日","dateIso":"2001-10-10","committee":"決算特別委員会","time":"午前１０時０７分～午後５時４９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を156件整理しています。","topics":[{"id":"topic-01","title":"◯横山委員長 おはようございます。ただいまより決算特別委員会を開きます。 平成１２年度品川区一般会計歳入歳出決算","agenda":"◯横山委員長 おはようございます。ただいまより決算特別委員会を開きます。 平成１２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"教職員の方が品川区に９０％という、その辺も変わりないんか尋ねました。","respondent":"鷹倉庶務課長","answer":"ただ、他区に異動なされた場合に、猶予期間というのは２カ月程度あります。ほぼ１００％に近いような形での９０％というような形でご理解いただきたいと思います。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"確認","question":"文教委員会の中での９０％というのは、その期間中ということだったという答えでいいわけですね。もう一度確認なんですが、どういう身分というふうに考えていいのか、その基本的なところをもう一度説明を求めました。","respondent":"鷹倉庶務課長","answer":"今ご指摘のとおり、東京都の職員、県費負担職員という形の位置づけですけれども、東京都が原則的には福利厚生をやるという位置づけの職員です。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"意見","question":"教職員住宅の管理自体をなぜ品川区がやっているのか、その根本的なところがわからない状況があります。その点についてまずお答えをお願いいたしますとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"昭和４８年にやっていたものですけれども、これは実は建てるに際して、教職員関係の融資を受けるような形でやってあります。優秀な職員を導き入れる政策的な観点から、こういう福利的なものも品川区としてやっている、こういうようにご理解いただければと思います。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先生は品川区で選ぶことができないから、この施設でカバーするというふうに聞こえてしまうんですけれども、そういう感覚なんか尋ねました。","respondent":"鷹倉庶務課長","answer":"少なくとも一般的な水準の者は用意しておきたいです。これですべてが解決するものではないですけれども、一般的に必要な教職員住宅というものは完備しておきたいなと、こういうことです。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"平成１３年度予算で8,５００万円近くの予算がついていましたけれども、この辺の財源というのは、東京都から財調とかで補助が出てくる分でしょうか。それとも区の分の独自の負担なんか尋ねました。","respondent":"市岡企画財政課長","answer":"こういう大規模改修については、特段財調でも、あるいは補助金のような特定財源でもありません。それ以外のものについては負担の根拠は明確でありませんで、人材確保の観点から一般財源を投入して教職員住宅の整備を図っているです。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"検診を受けていないというのは、特別な理由があるのでしょうか。どのくらいの方が実際検診を受けていないのか、その辺の数字が分かりますか尋ねました。","respondent":"鷹倉庶務課長","answer":"そういうことを改善していければ受診率が上がっていくのかなというふうに考えてあります。平成１２年度で６０％そこそこというような話ですし、１００％を目指しているわけですけれども、９０％を切るような形になってあります。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ことに結核が９０％を切っているとおっしゃっていましたけれども、感染性のあるものを考えていったときに、なぜ先生方が検査を受けないんでしょうか。万が一結核という状況までいくかどうかわかりませんけれども、学校の中に菌をまいてしまったら大変な問題になってくるのではないか尋ねました。","respondent":"鷹倉庶務課長","answer":"この方を入れますと、パーセンテージ的には９6.８％、それが人数的には４０名そこそこの方が受けておられないという方がいらっしゃいます。きちっとしておくことが基本的な考え方ですので、我々としては１００％を目指して頑張りたいと、このように考えてあります。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"生徒の健康を考えたら、当然１００％であるべきだと思いますので、今後も１００％を目指して努力をしてほしいと求めました。この中学生の主張大会に対して、教育委員会としては特別な何か指導とか、要請をしているのか尋ねました。","respondent":"青木指導課長","answer":"地域と家庭の連携の上で成り立つというようなことがよく言われておりますけれども、中学生の主張大会を進めているところです。教育委員会といたしましては、審査員の中に指導主事を派遣するというような形での支援はしていますが、この所管は教育委員会ではないので。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そういう方の力を利用するのに、なぜ学校側が協力していかないのか。その辺を考えた場合、教育委員会として、もう一度お答えをお願いしたいと思いますとの意見を述べました。","respondent":"指田教育次長","answer":"お話がございまして、校長会の席に地区委員会の会長がお見えになりまして、全面的な協力をしようというふうな形で校長会としても考えてあります。どの辺までができれば目に見えるのかどうかわかりませんけれども、積極的に対応をしていきたい、このように考えてあります。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後に要望しておきますけれども、教育委員会が事業部ととっていいのかどうかわからないですけれども、各事業部間での縦割りのためにできていないんだということがないようなことをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"その点をお伺いしたいと思います。それから、自然体験教室ですが、参加者は４０人だったですが、これはどういう形で行われたのか、ご報告をほしいと求めました。","respondent":"青木指導課長、南生涯学習課長","answer":"学校現場のほうからは特段このことにつきましてどのような対応をしたらいいかというような問い合わせはきてございません。学校のほうは冷静にそれぞれ対応をしているという現状です。 自然体験教室につきましての実施方法ですが、４泊５日の実施でございまして、４０名で実施いたしました。実施した場所は山梨県早川町でございまして、グループ活動、遊びといったことをやってまいりました。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"こういうふうになっておりますが、さて、昭和５６年から始まりましたハルビン市との教育交流は現在はどのようになっているのでしょうか。コストがかかり過ぎるというふうな評価になっておりますが、これはどういうことか尋ねました。","respondent":"青木指導課長、南生涯学習課長","answer":"そうした活動を通して、子どもたちに政治に対する関心とか、平和に対する関心を高めるというような教育活動を進めているところです。２点目の、ハルビン市についてですが、何度もこうした委員会でもご説明しておりますが… 事務事業評価の中での「コストがかかり過ぎる」という点についての考え方ですけれども、この事業自体は、非常に貴重な事業だとは思っております。","id":"exchange-012"},{"speaker":"鶴委員","kind":"質問・要望","question":"なぜ途絶えたのですか。こういうことの検討も必要じゃないかというふうに思いますが、いかがか尋ねました。","respondent":"青木指導課長、南生涯学習課長","answer":"１点目の、教育委員会としてどういう対応を具体的にするのかというご質問ですけれども、このあたりの整理をしていきたいというふうに考えております。２点目の、こうした事情がございましたので、ご理解いただければと思います。 自然体験教室につきましては、現在実施している方法にこだわらず、さまざまな自然体験の場というのがあります。そういった情報をとりながら、委員ご提案の内容も含めて検討をしていきたいと考えています。","id":"exchange-013"},{"speaker":"鶴委員","kind":"質問・要望","question":"そしてまた向こうの事情がよくなれば、こちらにも来てもらう。模索は続けていただきたい、打診していただきたい、いかがか尋ねました。","respondent":"青木指導課長","answer":"実はこの作品交流も、こちらから何度も向こうに連絡をとり、作品を送っていたんですが、残念ながらお返事がいただけなかったという経緯もあります。よろしくご理解いただきたいと思います。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは１３７ページから、教育指導費について伺います。品川区の不登校の実態を教えていただきたいのと、お知らせいただきたいのと、スクールカウンセラーの配置の状況を説明するよう求めました。","respondent":"青木指導課長","answer":"中学校３年生の場合が多いんですけれども、成果があるかなというふうに考えております。スクールカウンセラーの件ですが、現在中学校に７校配置しております。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"マイスクール八潮と、スクールカウンセラーのお話があったんですが、そのほかに対策をとお伺いしたので、ありましたら。資格があるのか、ないのか、その辺の内容もお願いします。","respondent":"青木指導課長","answer":"現在スクールカウンセラーは７校に配置していますが、１校につき年間３５週で、週８時間勤務というような形で取り組んです。資格ですけれども、臨床心理士という資格を持っている者がスクールカウンセラーで入ってあります。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここで質問なんですけれども、出会いの場所としてマイスクール八潮のようなところがもっとほかにはできないのかという、増設の要望です。常駐をしてほしいなと求めますけれども、いかがか尋ねました。","respondent":"青木指導課長","answer":"いろいろな予約制をしたり、そうしたことも含めまして、スクールカウンセラーの活用方法をさらに工夫してまいりたいというふうに考えております。民間の施設に通っているお子さんも数名おりますが、また具体的な連携も今後考えていきたいというふうに思っております。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"支援の問題、信頼関係をつくる意味での相談体制をより充実していっていただきたいと、これは要望しておきます。１０月２日の新聞に、昨年校内で学級崩壊があったかどうかという問いに対して、校長先生が２6.０％あった。","respondent":"青木指導課長","answer":"これはマスコミのつくった言葉でありまして、昨年度の場合は五つのクラスでそれに近い形で学級経営に行き詰まっているという報告がございました。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区にも求めていきたいと思いますけれども、来年度から小学校の１、２年生を対象として２５人学級を実現する。県知事に編成に向けての財政の負担も求めているわけですけれども、私は、誠意を持った取り組みをしていただきたいなと求めるわけですけれども。","respondent":"青木指導課長","answer":"小学校の１、２年の全学級が２０人から２９人程度になるような教員配置を県に要望したです。チーム・ティーチングと少人数過配という、さまざまな過配制度を使って、今教育を充実させる方向で取り組んでいるところです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜできないのかなというところの障害を伺いたいなと思うんですが、２１世紀を担う子どもたちに学力も、区民すべての願いだと思っています。私はこう思っていますので、そういった立場で、最優先すべき施策、子どもにお金をかけていただきたいなと思うんですが、区長、いかがか尋ねました。","respondent":"若月教育長","answer":"しかし、品川区はその趣旨に従って、今さまざまな施策を打っているところです。そういう意味で、個別指導の場所を今人的配置をしてつくっていると、こういうふうにご理解をいただければと思います。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は多くを語りませんけれども、未来の投資、きっと生かされることと思います。そういった意味では、ぜひ４０人から３０人に、一歩でも二歩でも広げていただけるように、心から要望いたしまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"辻委員","kind":"確認","question":"ちょっと確認しておきたいんですが、授業が成り立たないクラスが５件あったと聞いたんですが、そのクラスは何人いたんでしょうか。人数が分かれば教えてほしいと求めました。","respondent":"青木指導課長","answer":"それぞれ五つの学級とも３０人前後です。","id":"exchange-022"},{"speaker":"辻委員","kind":"質問・要望","question":"ですから、授業によっては大きかったり、小さくというのはいいと思うんです。関連ですから、ちょっとお聞きしたかったんです。","respondent":"青木指導課長","answer":"委員ご指摘のように、学級の人数と、授業が成り立たない状況とか、いじめとかというのは相関関係はございません。","id":"exchange-023"},{"speaker":"辻委員","kind":"質問・要望","question":"ずっと先ほど質問を聞いていたら、あれっという話になったものですから、どういう実態になっているんだろうなということを聞いたわけです。その部分と、今後やっていく論議の中では、教員の配置、講師の配置ということについては柔軟に対応していただきたいということを申し述べておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"１点目は、学校現場における様子を私たちがときたまお伺いしてみますのに、その努力の姿は本当に感激をいたしております。辞令を迎えたときに参考に聞くんですが、記録というのは、今までそういうのが残っているかどうか質問いたします。","respondent":"青木指導課長","answer":"そうしたことを学校に指導し、そして、その処理経過をスムーズに行えるような具体的なアドバイスを現在教育委員会としてはしています。記録につきましては、それぞれの学校で記録をとっているところです。","id":"exchange-025"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、この２点については要望として、ぜひお願いをしておきたいと思います。これは教育委員会の施設ですから、サービスも含めてお考えなのか、先に基本的な姿勢について伺いたいと思います。","respondent":"久保田学務課長","answer":"基本的な考え方ですけれども、基本的な考え方としては、児童・生徒が有効に使っていただく。それ以外については一般の方の利用に充てたいと、こういう考え方です。","id":"exchange-026"},{"speaker":"川西委員","kind":"質問","question":"一般の区民の方が利用するに当たりまして、どんなことに心掛けていらっしゃるか、伺います。","respondent":"久保田学務課長","answer":"一般の方のご利用ですけれども、ほかの保養所と同様に、私どもの光林荘も民間の経営をフルに活用しまして、普通のホテルに負けないサービスを追求しようということで、いろいろなところで工夫しているというのが基本です。","id":"exchange-027"},{"speaker":"川西委員","kind":"質問・要望","question":"というのは、かなり以前においては箱根林間学園や品川荘には葉書を置いて、ご要望を承りたいというようなものがありました。それから、この間ちょっと聞いたんですが、１０月の末に高齢者クラブ連合会というところに日光林間学園のＰＲに伺うんだということを聞いたんです。","respondent":"久保田学務課長","answer":"２点目のカラオケですけれども、やはり教育施設ということでありますので、これからもそういった点では改善を図っていきたいとは思っております。","id":"exchange-028"},{"speaker":"川西委員","kind":"質問","question":"ですから、予算を持っている区民課のところでいかがでしょうか。ですから、よくわかりませんが、みんな1,０００円ずつカンパしたらいかがだろうと、この間バス１台の旅行で、そんな話になりました。","respondent":"指田教育次長","answer":"そういった面では、今言ったようなカラオケ施設もやはり必要ではないかというふうに考えてあります。そういった方法もとりながら改善してまいりたい、このように考えてあります。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問","question":"この二つをお伺いします。平成７年度ぐらいに私どもの会派のほうから、それが実を結んできたと考えていますので、その二つの質問に対する答弁をお願いいたします。","respondent":"富田教育改革担当課長","answer":"いわゆる学習活動に関する指導員が２名ほど、今年度モデル実施ですので、学生アルバイトのような形で入れてあります。現在お願いしております学習支援ボランティア、地域の方々、地域で支えられるすまいるスクールとなるように心がけてまいりたいと考えています。","id":"exchange-030"},{"speaker":"伊藤委員","kind":"質問","question":"これからこの事業をどういうふうに拡大していくかということをお伺いしたかったので、その答弁を改めてお願いいたします。たしか品川区は別な仕組みでボランティアの登録システムを持っているはずですから、でも、結果的になっていない方々がたくさんおられるはずですから。","respondent":"指田教育次長","answer":"そういった点で、今モデル実施ですけれども、今後の方向としましては、やはりこれは拡大すべき事業であるというふうに現時点では思ってあります。","id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、これから発展して拡大していくということからしますと、既存の学校にある施設、それから、空き教室を有効利用していく。この事業を展開していく可能性があるわけですから、なぜあそこの場合には、二つ説明を求めました。","respondent":"指田教育次長","answer":"たまたま第二延山小学校で出てきたというふうにご理解いただければと思ってあります。今後の展望に当たりましては、当然のことながら、学校の空き教室というものは視野に入れて考えていかなければいけない問題だろうと考えております。","id":"exchange-032"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、既存の空き教室の有効活用とか、既存の学校施設の有効活用を進めていっていただきますように要望しておきます。簡単にお伺いしますのは、プロジェクトの進捗状況と、文部科学省の保健体育審議会の答申のこともたしか質問をさせていただいた記憶があるんです。","respondent":"鷹倉庶務課長","answer":"２１世紀に向けた学校づくりという形で、平成１３年度からいろいろ検討を進めてあります。学校改築検討委員会という形で、大きな学校全体、学校そのものはどうあるべきかというモデルプラン的な形で今議論を進めてあります。","id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問","question":"地域の声のところで、計画とか、具体的な改築をする段階から地域の声を生かしてみたらどうですかということをずっと言い続けてきたわけですので。ＰＦＩということについても検討をしてみてはいかがかと思うんですが、その答弁を改めてお願いいたします。","respondent":"鷹倉庶務課長","answer":"できるだけ実施計画上の予定よりは早めに前倒しにしながら進めていきたいなというふうに考えてありますけれども。確かに基金も今年度末で８６億円ですので、いろいろな手法を検討していかなければいけないなと考えています。","id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問・要望","question":"品川区はプラン２１、目に見える形で、だれの目に見ても明らかになる形で出てくるのはこれだと思っているわけです。ですから、誇れる学校づくりを進めていっていただきますように要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"中島委員","kind":"質問","question":"もう１点は、学校給食費のところですが、調理室のドライ方式というのが今進められていると思うんですが、どのぐらい進んでいるでしょうか。３点目に、家庭教育支援ネット講習というのがあるんですが、これはどういうものか説明を求めました。","respondent":"青木指導課長、久保田学務課長、南生涯学習課長","answer":"ボランティア活動のご質問にお答えいたします。実際にそれを使うとか、実際に点字のほうの学習をするとか、こうしたボランティア活動などがあります。学校給食室のドライシステム化の現在の状況ですけれども、小・中合わせて１１校がドライシステム化になっております。家庭教育支援の中でのネットワーク交流研修ですが、さまざま支援をしてきているわけですけれども、お互いにお母さんたちが子どもを育てていく。","id":"exchange-036"},{"speaker":"中島委員","kind":"質問","question":"１点目のボランティアですが、今お伺いしたら、高齢者施設でということで、あと手話、これは事業で取り入れているものなんですね。それ以外のボランティア活動をしているのはどうか尋ねました。","respondent":"青木指導課長","answer":"学校周辺の清掃とか、書き損じた葉書を収集するとか、共同募金に参加するとか、こうしたボランティア活動が、委員のご質問に対するお答えになるかと思います。","id":"exchange-037"},{"speaker":"中島委員","kind":"質問","question":"私も荏原第三中学校などもクリーンデーということで清掃をやっているのを存じております。それから、こうした生徒たちのボランティア活動をどういう形でまちの人にＰＲしているか尋ねました。","respondent":"青木指導課長","answer":"それから、地域の方たちと懇談するような会もありますし、学校の掲示板などに学校で行っているような内容を示すというような場もあります。","id":"exchange-038"},{"speaker":"中島委員","kind":"質問","question":"私は前に保育園を回らせていただいて、そこで園長先生とお話をしたときに、中学生のボランティアが欲しいんですと、こういうお話も伺いました。こういう意識改革というんですか、そういうものがとても大事ではないかなと思うんですが、いかがか尋ねました。","respondent":"青木指導課長","answer":"地域の方たちに分かっていただけるような掲示板で紹介したりと、今後もさらに、そうした工夫を重ねてまいります。善行部門でもそうした子どもたちの活動を取り上げていきたいというふうに考えております。","id":"exchange-039"},{"speaker":"中島委員","kind":"質問・要望","question":"これはきっと実行していただけるかなと期待して、要望にとどめておきます。それから、調理室のドライ方式が１１校ということですが、今後どのぐらいのスピードで改修されるのか、説明を求めました。","respondent":"久保田学務課長","answer":"ドライシステム化の今後の計画ですけれども、実施計画上は年間３校ずつ改修していくということになってあります。","id":"exchange-040"},{"speaker":"中島委員","kind":"質問・要望","question":"そうした意味で、これもできるだけスピードを上げて改修事業に当たっていただきたいということで、これは要望しておきます。先ほどの家庭教育支援ネットワーク講習ですか、幼稚園児のお母さんでしょうか、それとも各学年か尋ねました。","respondent":"南生涯学習課長","answer":"今回のお母さんたちがグループ化をして交流を進めていくための講座ということで言えば、お母さんたちはＰＴＡを通じて交流ができてくるということもありますので、未就学の子どもさんたちを持っている親御さんを対象にして実施していきたいというふうに考えております。","id":"exchange-041"},{"speaker":"中島委員","kind":"提案","question":"一つ提案をさせていただきたいんですが、今、異世代の交流がなかなかうまくいかない部分ではないかなと思うんです。いろいろな情報が得られて、自信を持って子育てができるのではないかなと思うんですが、いかがか尋ねました。","respondent":"南生涯学習課長","answer":"委員おっしゃるとおり、本当に先輩ママからの助言が欲しいというような声は確かに伺っておりまして、そういうプログラムをつくっていく中で、先輩ママの応援、あるいは助言、そういったことが受けられるようなプログラムを考えていきたいとは思っております。","id":"exchange-042"},{"speaker":"中島委員","kind":"質問・要望","question":"これは私だけではなくて、今、子育て中、また、もう少しで子育てが終わるというお母さんたちがしみじみと実感していることなんですね。中学校の単独ＰＴＡで行うとなると難しい部分がありますので、ぜひ行政のほうでその辺の力添えをいただきたいと要望して、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"本間委員","kind":"意見","question":"私は１３９ページの国際理解教育のところと、学校管理費の中の教材教具費に関連して、お願いしたいと思います。最初に、教材教具費の中の交通安全等副読本についてお尋ねをしたいと思いますとの意見を述べました。","respondent":"青木指導課長","answer":"その中で交通安全のみならず、地震の対応とか、そうしたことも含めて安全を取り扱っております。自転車の乗り方、そうした年間計画に応じて指導をしています。","id":"exchange-044"},{"speaker":"本間委員","kind":"質問","question":"交通安全対策副読本というのはどういうものかなということで尋ねてみたわけですけれども、これは学校の先生が行うのでしょうか。それとも、場合によっては、実際に所轄の警察署の署員が来て説明するのか尋ねました。","respondent":"青木指導課長","answer":"基本的には担任の教師が指導しますが、時には所轄の警察官の指導のもとで実際に実地訓練等も含めて指導をしています。","id":"exchange-045"},{"speaker":"本間委員","kind":"質問","question":"したがいまして、そのような部分で、時には専門家も入りながらやるということでございましたので、承知いたしました。これからの教育のあり方について、ある本でされておりましたものですから、環境問題についての部分は何かありますか尋ねました。","respondent":"青木指導課長","answer":"環境問題も現在教育の大きな課題であるというふうに認識しております。総合的な学習も含めまして、それぞれの学校でまず環境に対して自分たちはどんなことができるのだろうかというようなことも含めて学習をしています。","id":"exchange-046"},{"speaker":"本間委員","kind":"質問","question":"もしあれでしたら、別の部分にしたいと思いますが、大丈夫ですか。言語の障害をどのようにして乗り越えているのかということについてお尋ねしたいと思います。","respondent":"太川総務課長","answer":"たしか１８名だったと思いますが、区民の方にお願いして、お受け入れしたところです。ただし、ご自宅におきましてはすべて日本語と、英語と、フランス語を織り交ぜてお願いしております。","id":"exchange-047"},{"speaker":"本間委員","kind":"質問・要望","question":"ボディランゲージですか、実はそういう方は事前に日本語を何カ月間か研修されて来るわけですので、日常会話等はかなりやりとりができます。分散演奏会というのがありますが、この件について、学校との係わりはどのようになっているのか教えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"本間委員","kind":"質問・要望","question":"その機会をいかようにして与えてやるかということは大事だと思ったものですから、あえてそれを承知で質問をさせていただいたことをお許しください。長くなりましたけれども、そのようなことがございましたものですから、あえて質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、ほかの授業ですが、まちの人々から学ぶ授業ですとか、そうした、まちの人々との係わりについてお聞きしたいと思います。マイスクール八潮についてお聞きしたいんですが、平成１２年度の卒業式が初めてとり行われて、まずお聞きしたいと思います。","respondent":"青木指導課長","answer":"そうした意味で、まちの人々からの支援を受けて英語教育を充実させるように努めているです。しかし、保護者の方も大変喜んでいただきましたので、今後もさらに卒業式を充実させていく方向で進めていきたいというふうに考えております。","id":"exchange-050"},{"speaker":"本多委員","kind":"質問・要望","question":"中学校１年生になられて、中１から英語を学ぶわけですけれども、もしつかんでいたら教えてほしいと求めました。中１の英語の件は後でお答えいただきたいと思うんですが、１３９ページの、その辺の内容と対策などあればお聞かせほしいと求めました。","respondent":"青木指導課長、南生涯学習課長","answer":"やはり外国語に慣れ親しんでいるだけありまして、英語の導入がスムーズにいっていると、そうした報告があります。できるだけ学校と連絡をとり合って、本来の卒業式に出席できるような… 小・中学校で実施しましたＩＴ講習会ですが、特段大きな問題なく、大勢の方に喜んでいただいて実施しているという状況です。","id":"exchange-051"},{"speaker":"本多委員","kind":"質問・要望","question":"その辺対応がどうかなと思ってお聞きしたところですけれども、もしそのような対応がありましたら、後日でもお聞かせほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問","question":"私は１３８ページの、まちの人々から学ぶ授業についてお伺いします。私の前のご答弁の中でいろいろ出てきたんですが、その中で、ほかのまだ出ていない事業を具体的に何個か挙げていただけますか。","respondent":"青木指導課長","answer":"まだまだいろいろありますが、豆腐づくりを地域の方に家庭科で学ぶとか、そういうような事例があります。","id":"exchange-053"},{"speaker":"藤原委員","kind":"質問","question":"たくさんの事業があると思いますが、その中でどんな授業が今一番人気があるんでしょうか。生徒の方々からはどんな授業が期待されているんか尋ねました。","respondent":"青木指導課長","answer":"地域の高齢者の方に昔の話を聞くとか、なかなか学校の先生では教えられないような、そうした授業に子どもたちも大変関心を寄せているところです。","id":"exchange-054"},{"speaker":"藤原委員","kind":"質問","question":"今後ですけれども、学校がこれを地域の方から勉強しなさいというのではなくして、生徒のほうから、このようなことを学びたいんですがというふうにリクエストを得てやっていかれたらいいんじゃないかと思うんですが、その辺についてはいかがか尋ねました。","respondent":"青木指導課長","answer":"その中で子どもたちの関心を高めるような内容がどういうものなのかという、そうした学校の研究や、学校の方針に沿って子どもたちの関心の高いものを取り入れていくというような方法でさらに進めていきたいというふうに考えております。","id":"exchange-055"},{"speaker":"藤原委員","kind":"質問","question":"次に、三宅島の、り災児童についてお伺いしたいと思うんですが、品川区には、り災児童というのは現在いらっしゃるんか尋ねました。","respondent":"久保田学務課長","answer":"三宅島の、り災生徒の状況ですけれども、小学校に３名、中学校に３名、合計６名の方がいらっしゃいます。","id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"そのような子どもたちに対して、たしか東京都から区にお金をいただいて、そのお金で区自体が学用品を購入して、児童たちに差し上げて、とても喜ばれたということを伺ったんですけれども、その辺についてお伺いしたいと思います。","respondent":"久保田学務課長","answer":"中学生の方につきましては、上限が１万7,０００円、小学校の方については１万5,０００円です。残りの２名の方は、今回は外れられたものでございまして、総計４名の方が受けてあります。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"小・中学校の音楽室と保健室、この１年間で新たにクーラー設置されたところがあれば、教えてほしいと求めました。校長会とか、ＰＴＡなどから、クーラー設置について要望が出されているかどうか、このことについても説明を求めました。","respondent":"鷹倉庶務課長、久保田学務課長","answer":"小学校につきましては、ご案内のとおり、平成１２年度で共用便所等の間仕切りの改修は終わってあります。小学校も順次系統立ててやっていきたいなです。 合計で３７校、７７台設置しています。そのほかに、会議室、これは地域の方も使っていただくような会議室ということですけれども、そこにも２９校、５5台を新たに設置したという状況です。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"トイレ改修については、年４校ぐらいのペースてこれからも改修していくということでよろしいんでしょうか。気持ちが悪くなって、こういう子どもたちの環境がこんな状況になっていることに対して、教育委員会としてはどう考えているのかを説明するよう求めました。","respondent":"鷹倉庶務課長","answer":"私どもも今後クーラーについては、大きな研究テーマだというふうに認識はしています。しかし、これをどういうふうにしていくかというのは、十分議論を煮詰めてから答えを出していきたいなと、このように考えてあります。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"洗濯機、冷蔵庫、テレビが９８％ですから、これに匹敵するぐらいの普及率になっているというのが今の実態という状況です。ぜひ子どもたちが学ぶ環境、プラン２１の中にも快適な教育環境の整備というふうなこともうたわれていますし、ぜひ区長のご見解をお願いします。","respondent":"高橋区長","answer":"荒川区は荒川区、品川区は品川区です。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"図書館の問題を質問させていただきたいと思うんですが、児童サービスに対して、どの分野がどういう形でボランティアになっていくのか。そして、こういうふうになっていく経過というか、論議はどういうふうにされたのかについて説明を求めました。","respondent":"榎本行財政改革担当課長","answer":"自己評価Ｂ、一次評価Ｂということで、二次評価がＣという形になりました。直営の部分をある程度見直しをかけていかなければいけないという視点で、こういう視点でも努力していただくという形での判断となっております。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"具体的にどういうふうなことになるのか、どの分野がどういう形でボランティアになっていくのかということについて質問したので、お願いいたします。","respondent":"指田教育次長","answer":"私のほうからご説明申し上げます。さまざまな手法を取り入れていくという、そういったことでもって今回、平成１３年度ボランティアのそういった養成講座も考えているところです。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ボランティアということで、読み聞かせなどということですけれども、読み聞かせだけということなんでしょうか。待遇がどうなるのかということと、ボランティアと職員がどう係わるのか、このことについて説明を求めました。","respondent":"指田教育次長","answer":"その点については、これからの話という段階です。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この読み聞かせというところにはボランティアにしていただくというふうなことになって、職員はそこから手を引くというふうな形になるんか尋ねました。","respondent":"指田教育次長","answer":"先般のこういう事務事業評価が出たわけですので、これから検討に入っていくですので、今お話でもって、ここでこの方向先をこうするんだという形はこれからの話というふうに受け止めていただければと思います。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これからの検討ということですけれども、ここでちょっと学校の図書の充実のために、司書という役割がどういうふうな位置づけになっているのかということを説明するよう求めました。","respondent":"青木指導課長","answer":"司書の役割ですけれども、現在は幾つかの具体的な職務内容がありますけれども、学校図書館の利用の指導とか、実際に子どもたちの読書指導とか、そうした指導をするような形になってあります。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本の好きな子どもになるようにということで、そういう中で、図書館のサービスの充実というふうなところが求められていると思うんです。そこら辺のところは、他課との調整も含めて、そこら辺のところでは具体的にどういうふうに考えられているのか説明を求めました。","respondent":"志村品川図書館長","answer":"行革委員会の提言を踏まえまして、私どものほうでもいろいろ検討を重ねてまいりました。効率的な運営のあり方ということが基本でありますので、他課との調整も図りながら、これを進めていきたいというふうに考えてあります。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっと効率的な運営のあり方というのがよくわからないんですが、そこら辺のところをちょっと説明を求めました。","respondent":"志村品川図書館長","answer":"ただし、児童センターを含めまして、区役所全体というんですか、その中でもいろいろ事業があります。児童に対しての事業は、私ども図書館が担うべき部分がどこにあるんだろうかという視点を置きまして、それぞれ検討をしています。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"幼児期から豊かに育つというふうなことが求められているときですから、ぜひＣという形じゃなくて、充実をさせていただきたいというふうに思います。これは要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"塚本委員","kind":"質問","question":"関連した２点をお伺いします。どうして１２校、１８校、どうしてこういう様態ができてきたのかというようなことをまずお聞かせ願いたいと思います。","respondent":"鷹倉庶務課長","answer":"その経過期間が切れましたので、平成３年度からは有償措置になってきているということがあります。これはなかなか難しゅうございまして、今のところもう少し調べたいなというふうに思ってあります。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは一品川区の問題ではないわけですから、全国でこういうことが起きておるわけですから、ある部署でこういうことは国。課題の提示をどこでできるのかということを教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"上限５％という枠がありますけれども、上がってきているところもあります。相手方は、旧大蔵省、現在の財務省です。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問・要望","question":"ここで改めてどういうものを指摘されているのかということを、受けられたほうの課題として受け止めていることをお知らせいただきたい。この２点について、最初の、どれが課題だというふうに認識されているかということと併せてお聞かせ願いたいと思います。","respondent":"指田教育次長","answer":"監査から出た内容について、私どものほうの考え方をきちんと述べて、対応するようにという形をとっております。このことを踏まえまして、今度は反対に、学校側でもって一つプロジェクトみたいなものを組んでもらって、そこで対応策をきちんと考えてほしい。","id":"exchange-071"},{"speaker":"塚本委員","kind":"意見","question":"教育委員会のほうで監査の指摘を受けて、それが、どういった指摘かどうかということを議論することが大事なんですね。教育委員会でどのレベルの議論をして、監査の言ったことは、ここはそうだよという過程がどうなっているかということが一つ知りたいということですとの意見を述べました。","respondent":"指田教育次長","answer":"監査を受け止めますと、いろいろとその内容等について事前の打ち合わせというものを庶務課長が中心となりながら、各課長で打ち合わせをします。","id":"exchange-072"},{"speaker":"塚本委員","kind":"意見","question":"教育委員会がどういう議論をしているかということを伝えてほしいということの意見を述べました。","respondent":"指田教育次長","answer":"申し訳ありません。そういう中において、教育委員として、特に薬品等についてはいろいろとご指摘等があったように、たしか私、先般の委員会でも記憶しています。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問","question":"期日を指定して見に行くわけですから、かなりの準備をしているはずです。そこのところはどう思いますか。","respondent":"指田教育次長","answer":"ただ、今、監査の話が出まして、帳簿の管理、分割発注、薬品管理、ちょうど明日校長会があります。きちんと対応をしてまいりたい、このように考えておりますので、ぜひともご理解のほどよろしくお願い申し上げます。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問","question":"花を飾ったら、それをどうこうする者かいたら、それは違うんだよということだと思います。そのことによって、教育などというのは２年や３年でできることではないんですから、そういう懸命な指導が必要であると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"三上委員","kind":"質問・要望","question":"これは私の口を借りて、何とかしゃべってくれと私に目で叫んでいるような気がしたものですから、この課題についてちょっと伺いたいと思います。とりあえずその２点だけ先にお伺いしたいと思います。","respondent":"久保田学務課長","answer":"ガードレール設置については、これも先ほどの通学路の時間延長の部分も含めてなんですけれども、大変難しいというような声を聞いている状況です。残る八潮小学校についても、近々クーラーを設置することで動いております。","id":"exchange-076"},{"speaker":"三上委員","kind":"質問・要望","question":"時間がなくなりましたので、図書館の問題については、長くは伺いませんけれども、一つだけ今日は確認だけさせてください。これだけちょっとお伺いしておきたいと思います。","respondent":"志村品川図書館長","answer":"駅前ということで、それぞれ図書館が抱えている地域といいますか、それぞれ特色があるというふうに私は考えてあります。その辺を総合的に判断しまして、これからも皆さんに喜ばれる図書館ということで運営していきたいと、このように思ってあります。","id":"exchange-077"},{"speaker":"三上委員","kind":"質問・要望","question":"要望しておきます。そこのところについては本日のところは時間がありませんので、また改めて次の機会にさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"金高委員","kind":"質問","question":"私は、教育指導費の中の教職員の方々の研修ならびに社会体育総務費の内容について質問をします。どのように行われているのか、まずそれをお聞かせ願いたいと思います。","respondent":"青木指導課長","answer":"新任研修では、初任者にふさわしい、２０回の講座を設けて進めています。それぞれの立場で年間計画を組んで進めているところです。","id":"exchange-079"},{"speaker":"金高委員","kind":"意見","question":"逆に、生徒が先生に暴力を振るっても、当然これは問題になると思います。この問題点が学校側としてこの件に関しましてどういう原因でこのようになってしまったのか、また、これをお聞かせ願いたいと思いますとの意見を述べました。","respondent":"青木指導課長","answer":"研修の中にもありますが、生活指導主任会の研修の折にでもこういう問題につきましては常々早期対応の姿勢で取り組んできたわけですけれども。","id":"exchange-080"},{"speaker":"金高委員","kind":"質問・要望","question":"なぜかと言いますと、ずっと過去をひきずって今日きて、私たちは身の周りのいろいろなものに大体執着して生きているものであります。それぞれあると思いますけれども、どのように考えているか、お聞かせ願いたいと思います。","respondent":"青木指導課長","answer":"学校の立場、保護者の立場から、こうした問題がなぜ起きたのか。そして、教育委員会も含めて研究してまいりたいというふうに考えております。","id":"exchange-081"},{"speaker":"金高委員","kind":"質問・要望","question":"私が参加しております人生のあり方の勉強会の先輩が荏原第六中学校の２期生でありまして、その恩師がこの先生というわけであります。この点を踏まえて、何か一言ありましたら、最後にお聞かせ願いたいと思います。","respondent":"青木指導課長","answer":"子どもたちの可能性を引き出す場であるということは間違いのないことでありまして、私どももそうした姿勢で教育委員会としても取り組んでまいります。","id":"exchange-082"},{"speaker":"金高委員","kind":"質問","question":"続きまして、社会体育の総務費の中において、学校施設のことについてちょっとお伺いします。これはどこの学校に設置したかをまずお聞かせ願いたいと思います。","respondent":"南生涯学習課長","answer":"夜間開放用照明設備の整備をいたしましたのは荏原第一中学校です。","id":"exchange-083"},{"speaker":"金高委員","kind":"質問・要望","question":"これはもちろん昼間の人数でありますけれども、ちょうど区民まつりでありましたので、伺ったところ、提灯だけでありました。もし計画があればお聞かせほしいと求めました。","respondent":"南生涯学習課長","answer":"各地域、スポーツ・レクリエーション推進委員会というのを設置していただいて、各ブロックに１校ずつ夜間照明の設置というのをしています。ただ、夜間使用ができるような照明設備を設置しておりますので、夜間のスポーツ利用をしていただければありがたいと考えているところです。","id":"exchange-084"},{"speaker":"金高委員","kind":"質問・要望","question":"ただ、八潮のこの地域において、夜間に入って来れないはずのオートバイが広場でもって暴走族が騒いでいたり、そういう苦情も承っております。当然９時頃、あるいは９時半頃でもっておしまいになると思いますけれども、あったほうがいいのではないかという形の要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"北野委員","kind":"質問","question":"私は１３７ページの教育委員会教職員研修費、１３８ページのスクールカウンセラー活用調査研究費と、１３９ページの学校管理費について伺います。安全の確保に努める必要性があると思いますので、ぜひご検討願いたいと思いますけれども、考えをお伺いします。","respondent":"鷹倉庶務課長","answer":"私どもとしてもできるだけ万全の体制をとりたいなと思ってあります。学校で濃度を測ったらどうかですけれども、専門的な要素もありますので、私どもの技術者が赴いていったほうがいいかなと、このように考えてあります。","id":"exchange-086"},{"speaker":"北野委員","kind":"質問・要望","question":"厚生労働省の基準では１１品目が使ってはいけないという指針が出ています。１回の調査で６万円ぐらいかかるということですけれども、ぜひ検討をしていただきたいなと思いますけれども、もう一度お伺いします。","respondent":"鷹倉庶務課長","answer":"したがいまして、委員ご指摘のとおり、４０品目云々という機器があれば、そういうことができるかと思います。我々のほうの技術陣がまず学校に赴いて、そういうものを調べるという体制で万全を期していきたいなと、このように考えてあります。","id":"exchange-087"},{"speaker":"北野委員","kind":"提案","question":"事故というか、発生する前の事前の対策としてぜひ調べておいていただきたいということを提案しているので、ぜひご検討をしてほしいと求めました。１人当たり６４４件ということですけれども、そういう面があってこの違いが出ているのでしょうか、お伺いしますとの意見を述べました。","respondent":"青木指導課長","answer":"人数の違いはそういうところからも出てまいります。スクールカウンセラーと相談内容等も若干違うということも含めて、そうした人数の違いが出てくるというふうにお考えいただければと思います。","id":"exchange-088"},{"speaker":"北野委員","kind":"質問","question":"４人でも５００人という人数になるので、いろいろな場所が設置されているんですけれども、心の教室相談の方は場所が設置されているのでしょうか。内容についてもお伺いします。","respondent":"青木指導課長","answer":"相談の内容ですが、不登校問題とか、家庭の問題などがありますが、子どもたちの日常の悩みというのが一番多いかと思います。例えば進学の問題、家族の問題、教員の指導、友人関係、こうした内容が多くなっているかというふうにこちらのほうでは把握しています。","id":"exchange-089"},{"speaker":"北野委員","kind":"質問","question":"区は、学校関係も例外ではなく、教職員の研修ではセクシュアルハラスメントの防止の研修は行われているのでしょうか。今、研修の中ではプラン２１とかを含めた年次計画で進められているということでしたけれども、そのことについてはいかがでしょうか、お伺いします。","respondent":"青木指導課長","answer":"それから、現在「セクシュアルハラスメントの防止について」というリーフレットを全教員に配布しています。研修会の折に、男女平等教育という研修の中で、セクシュアルハラスメントの防止についても触れているところです。","id":"exchange-090"},{"speaker":"北野委員","kind":"質問・要望","question":"どこに、どのように相談に行けばよいのか、いろいろな問題があると思うんです。速やかな心のケアを含めた対応が求められていると思いますが、教育委員会としてはどのように考えますか、伺います。","respondent":"青木指導課長","answer":"教育センターにあります教育相談のセクションなど、さまざまな形で相談体制がありますので、そうした中で子どものそうした悩みを聞き取っていきたいというふうに考えております。","id":"exchange-091"},{"speaker":"北野委員","kind":"質問・要望","question":"子どもの立場に立って、そういうことが起こらないことと、相談体制をしっかりつくっていただきたいなと思います。今後はスクールカウンセラーの質も問われると思うんですけれども、現状のスクールカウンセラーの選任の仕方についてお伺いしたいと思います。","respondent":"青木指導課長","answer":"現在は７校ですが、今委員ご指摘のように、平成１７年までには３学期以上の全中学校に配置するというような計画で進んでおります。東京都のほうに申請して、東京都のほうでスクールカウンセラーが決まって、配置されるという流れになります。","id":"exchange-092"},{"speaker":"北野委員","kind":"質問・要望","question":"スクールカウンセラーの設置に向けては、選任の仕方にも要望が出せるようなことでぜひ働きかけていっていただきたいなと思います。教育委員会についてちょっとお伺いしたいんですが、傍聴が多いときには部屋を変えるとか、その点についてお伺いします。","respondent":"鷹倉庶務課長","answer":"私どもも柔軟な対応をしないわけでございませんで、プラン２１のときなどは部屋を変えてあります。ただ、こちらからかなり積極的に打って出るというようなことで、例外的な対応ということで柔軟に対応いたしました。","id":"exchange-093"},{"speaker":"北野委員","kind":"質問","question":"プラン２１は積極的ということで、教科書採択のほうも伺ったときには、積極性がないという判断になるんでしょうか。傍聴の人数に向けても、やはり開かれたものにしていくべきではないかなと思いますけれども、いかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"したがいまして、今回の教科書採択につきましては、１０名でいけるだろうということでございました。ただ、教科書採択そのものにつきましては１０名でいけるだろうと、このように私どものほうは考えてございました。","id":"exchange-094"},{"speaker":"北野委員","kind":"質問・要望","question":"でも、そういうときに臨機応変に、規則ということにこだわるのではなく、開かれた学校として進めていってほしいと求めました。そういういろいろな対応ができると思いますので、ぜひこれから前向きな教育委員会、開かれた教育委員会を強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"石田委員","kind":"質問・要望","question":"来年の４月にあるのかどうかとまず一つお伺いをしたいのと、教育長のおっしゃっているとおり、私も同感であります。ですから、そこら辺のことを１点お伺いをしたい。","respondent":"若月教育長、青木指導課長","answer":"各学校長に対しましては、いわゆる学校評議員制度という制度は現在のところ実施をする考えはないということは明確に申し上げているところです。都も、文部科学省も考えているようでありますけれども… もう１点の、子どもに対する教育的な面で負担が多くなるということで、二重登録は基本的には好ましいというふうには見ていないんです。","id":"exchange-096"},{"speaker":"石田委員","kind":"質問・要望","question":"ですから、そういう意味の中で、そういう子どもも必要なわけですから、ぜひ品川版のそういう形の、統一テストみたいなものをやっていただきたい。そういう意味合いで、もしお考えであれば、今検討中の中にそういうことを入れていただけるかどうか、お考えをいただきたい。","respondent":"若月教育長、青木指導課長","answer":"ただ、今品川区が考えている学力検査というのは、いわゆる受験学力といったようなものを前提にしたものではないということであります。その辺、学校の努力というものをご理解いただければありがたいと思います。 高等学校、大学、すべての登録者のチェックを入れるということなんです。今後サッカー協会と中体連の関係とか、野球と中体連の関係とか、それぞれのセクションにさらに強く申し入れていきたいというふうに考えております。","id":"exchange-097"},{"speaker":"南委員","kind":"質問・要望","question":"学級崩壊の質問がありまして、今のところ思い当たる表現がありませんので、一般的に言っている表現として使わせていただきますことをご了解ください。五学級あるということですが、３０人程度というふうなご答弁でしたけれども、具体的な数字をまず教えてほしいと求めました。","respondent":"青木指導課長","answer":"五つあります。２８人、２８人、３０人、２３人、２２人の学級です。","id":"exchange-098"},{"speaker":"南委員","kind":"質問","question":"教育委員会がこういう子どもたちの状況に心を痛めていらっしゃり、さらによくするための質問ですから、どうぞよろしくお願いしたいと思います。一般論でもいいんですけれども、これは個別のところですから、その辺も含めてお話しいただくよう求めました。","respondent":"青木指導課長","answer":"ＰＴＡの参加を得て、来週以降具体的な活動が始まるということで、現在進めているところです。現在は緊急措置ということで、この会を、問題の解決に向けてまず一歩を踏み出すという会にしたいというふうに考えております。","id":"exchange-099"},{"speaker":"南委員","kind":"質問","question":"直接尋ねる機会があって、尋ねるけれども、なかなか概要を教えてもらえない。ですから、行かない以前にきちんとしていくことが大事だと思うので、その辺の考え方を伺います。","respondent":"青木指導課長","answer":"日頃の保護者会活動でも必要であるというふうに私どもは認識しておりますし、そのように指導をしております。悪いことは悪いという、今後これを教訓にいたしまして、その他の学校にも指導をしていきたいというふうに考えております。","id":"exchange-100"},{"speaker":"南委員","kind":"質問・要望","question":"いろんな条件が重なって起きてくるということというのはあるわけですから、一つには、１人の人の見方というのはどうしても一面的になりがちですから。ですから、そういう判断をする基準というのは、教育委員会としてどういうところにあるのかというのを伺いたいんです。","respondent":"青木指導課長、南生涯学習課長","answer":"少年センター、さまざまな関係機関と連携をとって、そして子どもたちの健全育成にさらに力を入れてまいりたいというふうに考えております。今回の件につきましても、さまざまな教員が… それぞれ事業をなさるたびごとに後援名義の使用申請が出てまいりましたら、内容を見させていただいて判断をして、後援をしています。したがいまして、雑誌の発行そのものに対して後援をしているというようなことはございません。","id":"exchange-101"},{"speaker":"南委員","kind":"質問","question":"ですから、そこのところをちょっと聞いたんです。後援をするということの基準がどういうところにあって後援をされるのか、そこを聞いたので、お願いします。","respondent":"青木指導課長、南生涯学習課長","answer":"委員ご指摘のように、学校ではそうした力がなくてもできるようなということで、力を入れております。しかし、それがだめなときには、そうした関係機関の協力を求めて問題の解決に当たっていきたいと、そういうふうに考えてあります。 使用申請が出てまいりますと、官公庁、学校等々という規定をしています。文化等々、そういった教育に寄与するものであるという判断に基づいて、後援名義の使用を許可しています。","id":"exchange-102"},{"speaker":"南委員","kind":"質問・要望","question":"教育のほうの関係ですけれども、ひどい場合はあり得るということは私も否定しないと思います。自分たちの力も含めて、地域と学校と両方一体となってできるようにしていただきたいということを強く要望しておきたいと思いますけれども。","respondent":"青木指導課長","answer":"私どももそのように進めたいというふうに考えておりますが、地域の力、家庭の力、そして関係機関の力をいただいて学校教育が進められることが一番基本になるかというふうに考えております。","id":"exchange-103"},{"speaker":"田中委員","kind":"質問","question":"私は学校教育においての地域社会との連携につきましてまずお伺いをしたいと思います。地域に出向いての活動、地域交流というものが具体的にどういうことがなされているのか、まずお伺いしたいと思います。","respondent":"青木指導課長","answer":"地域社会との連携というのはこれから大きな教育の課題になっていくかというふうに考えております。職場体験なども取り入れながら、子どもたちにはそうしたまちの人たちから学べるそういう機会を多くつくっていきたいというふうに考えております。","id":"exchange-104"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひその方向で事業を進めていただきたいと思うんですが、学校週５日制になってまいりますと、学校にいる時間が今よりは少なくなってくる。そういったボランティア、週５日制を踏まえた上での今後の対応といいますか、考え方についてお伺いしたいと思います。","respondent":"青木指導課長","answer":"学校週５日制の趣旨は、今委員のお話にもありました、そうした体験活動というのは非常に重視されることになると思います。実際に防災訓練なども、子どもたちが参加して行うような防災訓練もすでに実施されておりますし、教育委員会としても考えておるところです。","id":"exchange-105"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひそういう方向で来年４月以降取り組んでほしいと求めました。そういった学校週５日制を踏まえた上での学習体制というものを来年４月以降どう考えていらっしゃるのかをちょっと確認したいということと、併せて。","respondent":"青木指導課長","answer":"学校週５日制になりますと授業時数が当然減ります。子どもたちにとって精神的なゆとりを持って基礎・基本を定着させる、そうした学習活動を進めていきたいというふうに考えております。","id":"exchange-106"},{"speaker":"田中委員","kind":"質問・要望","question":"プラン２１推進の中で生まれてきているという先ほどお話がございましたが、応用の面も学力アップに向けて取り組んでほしいと求めました。これは要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"松澤委員","kind":"質問","question":"簡単にお聞きしたいと思います。運動会にご招待を受けましたけれども、学校教育に占める運動会の位置づけというものについてお伺いしたいと思います。","respondent":"青木指導課長","answer":"子どもたちが日々さまざまな学習をしておりますが、この運動会も子どもたちの生活の中で一つの節目になる。１年間の節目になるような、そうした行事として位置づけられております。","id":"exchange-108"},{"speaker":"松澤委員","kind":"質問","question":"どうしても入学した４月から５月、６月ではなくて、秋にやっているのか。そしてまた、なぜ春に行う学校があるのかという、その理由についてお教え願います。","respondent":"青木指導課長","answer":"２学期が学校行事が大変集中するというようなことも含めまして、心、春に運動会をやるというふうに決められるという学校が多くなってきている。そんな現実です。","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問","question":"校長が決めるということなのかどうかわかりませんけれども、どちらが好ましいとかというような形の指導みたいなものはなされているのか。そしてまた、その日付ですね、日曜日にやっているのか、あるいは平日にやっている学校があるのか、その辺についてもお聞きしたいと思います。","respondent":"青木指導課長","answer":"特段そういう指導はしてございませんが、やはり体育の日が秋にあるというようなことで、秋のほうが望ましいかなというような考えがあります。それから、平日か、日曜日かというご質問ですが、これは圧倒的に日曜日が多くなってあります。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問・要望","question":"なぜ秋にやるんだという見解が出ないのが不思議ですけれども、プラン２１というすばらしい施策を考えてやっているんですから、一つ述べておきます。今までの学校内のＰＴＡとか、先生方の学校管理の警備状況が変わるのかどうか、現在の状況をお聞かせほしいと求めました。","respondent":"青木指導課長","answer":"あの事件の後、学校安全対策委員会というものをそれぞれ設置しまして、この安全対策委員会の中でさまざまな話し合いがなされております。そうした報告をもとに学校と連絡をとり合って、さらに安全に対しては万全を尽くしていきたいというふうに考えております。","id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"今はどうかわかりませんけれども、「しばらく」というような形容詞が上についたと思うんですけれども、それがどこまで続いていくのか。今度の学校１１０番の整備について変わるのかどうか、あるいは２年、３年ずっと続くのかというところをお聞きしたいんです。","respondent":"青木指導課長","answer":"一律には申し上げられませんけれども、新たにＰＴＡの活動としてパトロールを始めたとか、さまざまな変化は出てきております。１１０番等の通報装置の問題なども今度は入ってきまして、そうした体制も含めて、新たな安全対策に切り替えていきたいというふうに考えております。","id":"exchange-112"},{"speaker":"松澤委員","kind":"質問・要望","question":"当然そういうこともシミュレーションの中には入っていると思いますけれども、子どもたちのケアの問題というのはどのように考えているのか、ひとつそこをお聞かせほしいと求めました。","respondent":"青木指導課長","answer":"そうした問題については、すでにそれぞれの学校で教員のほうから子どもの精神的な問題については指導をしています。先生たちがこうやって守るんだよというような、そうした指導はそれぞれの学校でできているかというふうに考えております。","id":"exchange-113"},{"speaker":"松澤委員","kind":"質問・要望","question":"とにかく４カ月過ぎて、ちょうど気の緩みが出る時期ですので、大変でしょうけれども、その辺の管理体制をしっかりしてほしいと求めました。いろいろ問題点もありますので、しっかりとしていきたいということを述べまして、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"辻委員","kind":"質問","question":"ここで延べ2,７６８人、お聞きしたいのは、現状としてどういう配置状態になっているのかということを改めてお聞きしたい。独立した専門の部屋があるのかどうか、そこには備品として電話などが備えられているのか、どうなっているのか、簡単に説明を求めました。","respondent":"青木指導課長","answer":"３校増えている状態です。電話は入ってございませんが、相談しやすいような、そうした部屋にしています。","id":"exchange-115"},{"speaker":"辻委員","kind":"質問・要望","question":"それから第一次、第二次と書いてあるんですが、どういうところに発行の対象を置いているのか。課長のほうの自己評価について詳しくお知らせほしいと求めました。","respondent":"鷹倉庶務課長","answer":"我々もできるだけ良いものを出したいということをやっておるわけです。ただ、教育広報のあり方も見直していかなければいけないのではないかと、こういう受け止め方をしています。","id":"exchange-116"},{"speaker":"辻委員","kind":"意見","question":"もう承知していると思いますけれども、第二次評価のほうで、多分担当が、ここで言うと、発行部数、回数の見直しや、区広報との調整ということになっているんですが、この辺についてどのように評価されていますかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"そのような見直しもかけられないかということでの視点から、このような「調整できないか」ということでの、部をまたがった形での評価の判断となっております。","id":"exchange-117"},{"speaker":"辻委員","kind":"質問・要望","question":"ですから、区長の経営会議のほうで、区の広報紙とかという、ペーパーだけという問題とまるっきり違うわけです。「教育のひろば」というのは年３回ではもったいなかったなというのを、これを大いに発展させていただきたいということで、いかがか尋ねました。","respondent":"高橋区長","answer":"そういうものに吸収、統合いたしまして、より教育の内容について区民に知っていただける、これは今の広報が１６万部発行しております。そういうものを一工夫していただきたいと、こういう意味でＣにさせていただきました。","id":"exchange-118"},{"speaker":"辻委員","kind":"質問","question":"これはまさしく学校週休２日なり、地域の学校という形でいったときに、大きな共通の、つなぐ媒体としてなっていくべきだと思うんです。こういう形で講師というんですか、あと半年後にスタートするでしょうけれども、準備の状況というのはどうなっているんか尋ねました。","respondent":"青木指導課長","answer":"委員ご指摘のように、いよいよ来年度から新学習指導要領ということで、音楽では和楽器を１種類以上ということになってきております。そうした方々の協力を得て、こうした事業を充実していく、そうした方向で考えていきたいというふうに考えております。","id":"exchange-119"},{"speaker":"辻委員","kind":"質問","question":"これは基本的に学校の教材としてそろえるんですか。この辺が、どういう準備状況なのか。","respondent":"青木指導課長","answer":"こうした事業をどういうふうに展開していくのか、そして、この和楽器をどのように整備するのかというようなことにつきましては、校長会等と連絡調整をとり、具体化させていきたいというふうに考えております。","id":"exchange-120"},{"speaker":"辻委員","kind":"質問・要望","question":"私も具体的にこうしろという知識がないものですから、どうなるのかなということでお伺いしましたので、ひとつよろしくお願いしたいと思います。自然に入る朝の１０分間の読書、そういう形をぜひ大きくもう一回焦点を当てていただきたいと思うんですが、いかがか尋ねました。","respondent":"青木指導課長","answer":"朝の全校一斉読書運動ですけれども、現在、小学校では２０校、中学校では４校、朝の読書運動に取り組んでいる状況です。","id":"exchange-121"},{"speaker":"辻委員","kind":"質問・要望","question":"スポーツ協会に所属している一連の中で、大きな記録というのはどうなんでしょう、今の状況。その記録が出たときに、どういう記録が出たというか、そういうのを、スポーツ協会のほうとしてつかんでいるところをお教えほしいと求めました。","respondent":"山岡総務部副参事","answer":"区民の方どなたも参加できるということで実施している大会でございまして、例えば日本記録が出たとか、そういうことは今のところはございません。そういうことで、広く、こういう大記録が出たということは、ちょっとご報告できないのが残念ですが、状況としてはそういうことです。","id":"exchange-122"},{"speaker":"辻委員","kind":"提案","question":"私も開会式に出席させていただいて、やっぱりスポーツである以上はある部分記録を目指したり、あるいはそれに対して壁に挑戦する。ですから、そういう振興策もあってもいいんじゃないかということを提案して、終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"},{"speaker":"土井委員","kind":"質問・要望","question":"なぜでしょうか。そのためにはどうしたらいいんか尋ねました。","respondent":"青木指導課長、久保田学務課長","answer":"一方、中学校は、ここ３年間１校というような状況です。小学校においても、中学校においても男女混合名簿がさらに広がっていくように、教育委員会としても指導をしていきたいというふうに考えております。 基本的な考え方ですが、そういう点では、設置できるところには大体設置してきたという経過があります。今後の考え方ですが、例えば清掃リサイクル課でやっている部分の活用も検討すべきだろうということで、できるだけ長持ちさせて。","id":"exchange-124"},{"speaker":"土井委員","kind":"質問・要望","question":"ぜひそういう形で進めていただきたいという要望も含めて、後から若干のお答えをいただきたい。しかし、学校ではコストというようなものも教えていかなければならないわけですから、トータルとしてどう考えたらいいのかということをお話をする。","respondent":"青木指導課長","answer":"名簿のほうですが、教育現場の声を十分に聞いて、さらに指導をしていきたいというふうに考えております。今委員ご指摘のように、学校とよく相談して参加するような方向をとっているところです。","id":"exchange-125"},{"speaker":"土井委員","kind":"質問・要望","question":"コンピュータを使えば、あっという間に分かれるんですから、便利さはどうとでもなる話なんでね。ただ、先生が参加とか何かというのはきついですけれども、要望というか、意見を申し上げて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"事項別明細書でちょっと教えてもらいたいんですけれども、報酬と報償費、役務費、賃金、共済費、こういう項目がありますけれども、これはどういうことで分けられているんか尋ねました。","respondent":"市岡企画財政課長","answer":"それから、テープの反訳のような業務に対する対価、あと電話代等です。","id":"exchange-127"},{"speaker":"須藤委員","kind":"質問","question":"それから、成果報告書では、研修とスポーツ協会、児童・生徒の体力低下についてお聞かせ願いたいと思います。先生方が品川区に配置されたときの辞令を出すのはどなたが出すんか尋ねました。","respondent":"青木指導課長","answer":"教員の場合は東京都教育委員会になっております。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"教育委員会でくるわけですか。東京都の教育長の名前でなくて。","respondent":"青木指導課長","answer":"教員がこちらに参りまして、教育長のほうから辞令伝達という形で、本区の教育長が辞令伝達として東京都教育委員会の辞令をお渡ししているという現実です。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"区長が部長の研修であるとか、課長の研修であるとか、あるいは係長の研修であるとかという形でお話になられている。そのときに区長からまた教員の方に、あるいは校長先生に、こういう状況でどうだよというような連携はどこかないんか尋ねました。","respondent":"指田教育次長","answer":"例えば一つの研修をとったとしても、東京都教育委員会主催の研修、これが主体になってくる。どうしてもそこのところに隘路があるというふうところで指示がなかなか流れないというふうなところがあるのかなと痛切に感じているところです。","id":"exchange-130"},{"speaker":"須藤委員","kind":"質問","question":"その辺はどうですか、プラン２１をやり出したことに対して、外から品川区のためにやるぞというような気合が入って来ている方々はどのぐらいいらっしゃるんか尋ねました。","respondent":"青木指導課長","answer":"今委員ご指摘のように、プラン２１に対して大変関心を持ち、自分も品川区に行ってこのプラン２１の推進に当たりたいという教員は現在確かにおります。ぜひそうした教員を品川区に配置できるように私たちは東京都教育委員会にも働きかけていきたいというふうに考えております。","id":"exchange-131"},{"speaker":"須藤委員","kind":"質問","question":"教員側で３7.何％、校長でも３１％、３割近い人たちが問題児のあるお子さんはさわりたくないんだよというような考え方を持っています。問題児を排除するよというふうな数字が出ているようなことが現実に教育委員会のほうでは、あるいは教育関係者ではお感じになっていますか尋ねました。","respondent":"青木指導課長","answer":"そのようなことは教育委員会としては考えてございませんし、現在の品川区教育委員会では考えておりませんし、３割方がそういうふうに考えているという現実はないというふうに考えております。","id":"exchange-132"},{"speaker":"須藤委員","kind":"質問","question":"この前も一般質問でやりましたけれども、逆に、子どもたちが大きく伸びていってくれるんじゃないかな。各学校との位置関係というのか、連携が非常にとりにくいような場所にあるんじゃないかなと思うんだけれども、その辺はいかがか尋ねました。","respondent":"青木指導課長","answer":"確かに教育委員会からは離れておりますが、全体的なバランスからいけば、教員が集まりやすい場所ではないかなというふうな考え方もあります。ただ、教育委員会から離れているというような問題点は確かにあるというふうに認識しております。","id":"exchange-133"},{"speaker":"須藤委員","kind":"質問","question":"２０年、３０年前の、いわゆる親御さんと同じぐらいの体力になっちゃっているんだと。体力はないよというので出ていましたけれども、その辺について、そういうものと教育委員会とはドッキングみたいな考え方はあるんか尋ねました。","respondent":"青木指導課長","answer":"体を動かさない生活というものが子どもたちにも定着しておりまして、子どもたちの体力が落ちているという現状は私どもも大変心配しております。","id":"exchange-134"},{"speaker":"須藤委員","kind":"質問・要望","question":"そうすると、柔道などは３人で道場対抗をチームで、それでも９人分と同じぐらいな参加費を取られてしまう。ですから、各団体の状況を見て、そういった対応をしてほしいと求めましたが、いかがか尋ねました。","respondent":"山岡総務部副参事","answer":"まず考えなければならないのは、できるだけ経費の節減を図るということがまず第一で、人件費を初めとして各種経費を区の支援を受けているところです。なおかつ競技間でバランスがとれない部分もありますので、その部分は検討をしていきたいというふうに考えております。","id":"exchange-135"},{"speaker":"船波委員","kind":"質問","question":"難聴学級医、精神科医という医師の方々に校医になっていただいていますが、これらの医師の方にどのように学校に係わっていただいているんでしょうか。１校にお一人お願いしているようですけれども、それぞれどのように学校に係わっていただいているのか、その職務内容をお伺いしたいと思います。","respondent":"久保田学務課長","answer":"そういったことに対して的確に相談に乗るというような指導、助言をする役割もあります。これは緊急時の対応ということで、例えば保護者会の説明会に出席していただくとか、そういう仕事も含まれているところです。","id":"exchange-136"},{"speaker":"船波委員","kind":"質問","question":"特殊学級、難聴学級、精神科医というのは、今ご説明にあったものとは別の特殊な役割があるのではないかと思いますが、そういった特殊な分野の医師の方にはどういったことをしていただいているんか尋ねました。","respondent":"久保田学務課長","answer":"ここの中で出ている特殊学級というのは、心障学級のほうの子どもたちの健康診断とか、あるいは健康相談に従事している医師に対する報酬です。それから、難聴医は、例えば台場小学校のほうに難聴教室というのを設けてありますので、同じような従事の仕方です。","id":"exchange-137"},{"speaker":"船波委員","kind":"質問","question":"精神科医の医師はどういったお仕事をしていただいているんか尋ねました。","respondent":"久保田学務課長","answer":"荏原両医師会から１名ずつ配置されているんですけれども、呼んでいただきまして、そちらに従事していただいている方の報酬です。月に、多いところでは一、二回ということがありますけれども、学校を順に回って、そういう相談に乗っているというようなイメージです。","id":"exchange-138"},{"speaker":"船波委員","kind":"質問","question":"それぞれ報酬額を設定されているわけですが、報酬の額はどのような要素を検討して決まっているのでしょうか。それから、何年かに１回ずつ改定がなされてきていると思いますが、どのように改定されてきているのか、お伺いしたいと思います。","respondent":"久保田学務課長","answer":"三者協議会のほうで決められているというのが、財調単価等でも反映されておりまして、それを参考に品川区の場合においても決めているものです。見直しですけれども、平成１１年度に改正して以来、現在のところそのままになっているというような状況です。","id":"exchange-139"},{"speaker":"船波委員","kind":"質問","question":"それを決めるときにどういうふうな要素を鑑みた上で決めているのかということをちょっと疑問に思ったので、お伺いしたいと思っていました。あるいはそうやって学校の規模が違うことは、校医の報酬設定に反映されていないのかというのが疑問なんですが、その点はどうなんか尋ねました。","respondent":"久保田学務課長","answer":"先ほどご説明したように、校医の仕事というのは大変幅広く、なかなか報酬単価についての見合った評価というのが難しい面があります。","id":"exchange-140"},{"speaker":"船波委員","kind":"質問・要望","question":"医師の働いていただく労力や時間が違うんですから、職務の内容に違いがないというのは、今後はぜひ検討をしてほしいと求めました。以前、いろいろな場面で活躍していただくというような制度があるということをお伺いしましたけれども、その現状をお伺いしたいと思います。","respondent":"南生涯学習課長","answer":"学校支援ボランティアの登録者数ですが、今年の９月の時点で２８２名の方が登録していらっしゃいます。あるいはご自分の特技、職歴等を生かしてというようなことで、非常に多岐にわたっているところです。","id":"exchange-141"},{"speaker":"船波委員","kind":"質問","question":"それだけの方がいろいろな分野で登録されているということは、今のご説明ですけれども、その登録していただいた方に実際どれくらい学校の現場へ出て活動していただいているのか、お伺いしたいと思います。","respondent":"南生涯学習課長","answer":"学校支援ボランティア自体は、動き始めたのが今年度になってからですので、まだ十分に活用されるというところまでいっておりません。あるいはこういう制度はもっと充実させていくべきだという、大変前向きな反応を得ているところです。","id":"exchange-142"},{"speaker":"船波委員","kind":"質問・要望","question":"地域の大人にとっても、地域と学校とのつながりを深めるということになると思いますので、ぜひこれから活用していってほしいと求めました。楽しみにしております。","respondent":"横山委員長","answer":"しかし、今手元には、今後時間当たりの降水量は当面減少に向かう見込みと、このような報告をいただいておりますので、ご報告をします。続きまして、宮崎委員。","id":"exchange-143"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これを２点目にお伺いしたい。そこのところはどうか尋ねました。","respondent":"南生涯学習課長","answer":"それから、もう１点、１億1,０００万円余りのスポーツ協会助成金につきましては、主にスポーツ協会の事務局の職員の人件費の助成です。そのほか若干の事業費を含んでいるものですが、内容としてはそのようになっております。","id":"exchange-144"},{"speaker":"宮崎委員","kind":"質問","question":"１億1,１００万円ほどですけれども、これはそんなに減らすと、ここでは「区の助成を減らしていく」ということになっているんですけれども、この１億1,１００万円が本当に減らさなければいけないほど重いというふうに見ているんですかということを聞いたんです。","respondent":"榎本行財政改革担当課長","answer":"減らせれば一番いいんですけれども、官民の役割分担の中で自主的な運営が使える部分は有効に使っていきたいということで、使えない部分についての補助は区がやらざるを得ないという形の立場の評価です。","id":"exchange-145"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところをお伺いしたいと思います。ここのところはどうか尋ねました。","respondent":"高橋区長","answer":"むしろその基金を安全に管理できるか、できないかが今大変問われているところですから、金利でものをやろうなんていう考え方は毛頭持っておりません。内部的な問題もあります、外の料金を上げろというわけでなくて、内部的な努力ができないだろうか。","id":"exchange-146"},{"speaker":"宮崎委員","kind":"確認","question":"今の区長のお話ですと、当面これは助成金とか、そういうところを区のほうは減らすというふうに考えているのではないんだということでいいんですか。そこのところをどういうふうに考えているのかお伺いしたいと思います。","respondent":"高橋区長","answer":"これもやはり運営の改善を図る意味の中で検討をされる問題だろうというふうに考えております。こういう趣旨が含まれているということをご理解のほどお願い申し上げます。","id":"exchange-147"},{"speaker":"宮崎委員","kind":"確認","question":"では、確認しますけれども、戸越台中学校のプールの件だけで今考えているんだということか尋ねました。","respondent":"高橋区長","answer":"派遣職員を引き揚げまして、スポーツ協会で雇用した職員でできないだろうか。もう少しスポーツ協会で考えていただけませんかということで、「自主的な運営を支援する」と、こういう言葉になっております。","id":"exchange-148"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ここら辺のところでまた伺いたいんですけれども、スポーツ協会と区の係わり、これによって事務事業評価の考え方によって変わっていくのかどうなのか。何かそういうのがありましたらお聞かせほしいと求めました。","respondent":"高橋区長","answer":"したがいまして、改修をしなければならない。それと同時に、あそこの一体の開発の問題をにらみまして、どうしたらいいだろうかということが一つの案です。","id":"exchange-149"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今は教育費ですから、私は、区のほうが今までのスポーツ協会との関係のところでかなり見直しをしていくんじゃないかというふうに読める。今までの区長の答弁では、スポーツ協会は寄りかかり過ぎだということですけれども、これをつっかえ棒を外していくということになるわけか尋ねました。","respondent":"高橋区長","answer":"そういうふうにスポーツの振興を図りつつ、スポーツ協会の自主的な運営ができるような方策も考えてきたわけです。だからスポーツ協会の中で効率的な運営ができるような方法もあなた方考えてくだいよと、こういうわけです。","id":"exchange-150"},{"speaker":"宮崎委員","kind":"提案","question":"見直すということであれば、例えば私も以前提案しましたけれども、日頃スポーツに来られない方々をどういうふうに参加させるのか。ですから、こういうところも見直す必要があると思うんですけれども、お考えをとの意見を述べました。","respondent":"指田教育次長","answer":"利用料との関係かと思いますけれども、これは何もスポーツに限ったことではないというふうに私は思ってあります。これは無料という考え方も出てくるわけですけれども、当然受益者負担というものは浸透させていきたい、このように考えてあります。","id":"exchange-151"},{"speaker":"宮崎委員","kind":"提案","question":"次長のほうから受益者負担だというお考えが出ましたけれども、スポーツに親しんでいない方をいかに広げるか、この視点が大事だと思うんです。日頃スポーツに参加できていない方々への要望をどう反映させるかというところでもひと工夫もふた工夫もよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-152"},{"speaker":"築舘委員","kind":"質問・要望","question":"４0.２％ということですが、実際はもっと少なかったよということで、そういう意味の現状はどうなっているかというのをちょっとお話しいただきたい。その２点をお願いします。","respondent":"南生涯学習課長、久保田学務課長","answer":"お客様にたくさん入っていただいて、使用料も徴収しという形での努力をしている成果というふうに私どもは見ているところです。もう１点の、そういう意味での問題で… 保健所の指導等も受けて適正な衛生管理に努めておるわけですが、濾過装置で現状の水を必ず循環させてきれいな水にして流しておくというのが一つです。","id":"exchange-153"},{"speaker":"築舘委員","kind":"質問・要望","question":"これは教室はもちろんいいんですけれども、そこのところをもう少し研究をしていただきたいというふうに思っております。そこのところをちょっとお願いします。","respondent":"山岡総務部副参事","answer":"現在は一般開放中の中を１コース歩くレーンをというお話でしたけれども、ほかの方のいろいろな状況から、そういうレーンは設けてございません。ただし、今後の検討課題にしていきたいというふうに考えておりますので、ご理解をお願いいたしたいと思います。","id":"exchange-154"},{"speaker":"築舘委員","kind":"質問・要望","question":"そこまであれですから、中学校、小学校、これが基本だと思うんです。そのことに関して一言お願いします。","respondent":"青木指導課長","answer":"委員が今本当に堂々と言い切っていただいた、そうした気概を教育委員会も持って、いいことはいい、悪いことは悪いと中学生に言える、そうした指導体制を確立していきたいというふうに考えております。","id":"exchange-155"},{"speaker":"築舘委員","kind":"質問","question":"大事なこと、安全と水はただだというようなことが日本ではありますけれども、ただではないんです。危ない戦争状態ですから、我々もしっかり頑張っていきたいと思いますので、理事者の皆さんも頑張っていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-156"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/321088?Template=document&Id=1190#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":107713,"voices":343}},{"id":"h13-20011012-4","meetingId":"h13-c-settlement","date":"2001年10月12日","dateIso":"2001-10-12","committee":"決算特別委員会","time":"午前１０時０５分～午後６時０８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を97件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"本年４月より事業部制を導入いたしました。職員の意識改革を図っていこうとされているのか、今後の計画または考え方、それを教えてほしいと求めました。","respondent":"中尾根企画部長","answer":"委員のまずお尋ねの事業部制の実施の実感ですけれども、柔軟かつ機動的な対応、組織の自立と責任を高めていくということで導入いたしました。考え方ですけれども、いわゆる事業部編成枠方式、こういったことを実施することにいたしました。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"自分たちのチームの経費となるわけですから、そういう意識づけができてきて、全部ただのものを探してくるというようなものになってきた。チェック機能をどのように整備をしていくか、ここら辺が一番ポイントになってくると思うんですが、ここら辺の考え方を教えていただきたい。","respondent":"中尾根企画部長","answer":"ないしは区民の感覚、こういうものを持って仕事に当たらなければならない、こういう認識でずっと改革を進めてきてあります。成熟度、こういうことを総合的に勘案しながら具体的に考えていきたい、このように受けとめてあります。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"今度の場合は、税金で皆さん発注なり、物を買っていくわけですから、その意識づけということは、必ず浸透させていただきたい。透明性を拡大していくとか、そういう意味が非常に大切になってくると思うんですが、そこら辺のところの考え方をちょっとお聞かせいただきたい。","respondent":"高橋区長","answer":"これが実施に入りますと、係長が今度各職員の自己管理に任せると、こういう手法が順次浸透していくものと考えています。もうしばらくひとつ長い目で、品川区の事業部制を見ていただきたい、これはお願いです。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問・要望","question":"この理由は、どうであったかということを考えているのか、それを教えていただきたい。物品購入ももちろんあると思いますが、工事もあると思いますが、それぞれの比率を教えてほしいと求めました。","respondent":"本間総務部長","answer":"２点目の、予算と予定価格と契約価格がイコールのような、区内の共通商品券を購入するような場合にこういうケースが見られます。非常に予定価格に比べまして安く落ちた理由として考えられますことは、これは制限つき一般競争入札で行いました。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"いろいろお考えになっていくと思うんですが、やっぱり指名競争というよりも、一般競争入札を増やしていく時期ではないのかなと私は思っております。見積もり合わせの比率を考えていくということが私は必要だと思いますが、ここら辺の点について、お考えを教えていただきたい。","respondent":"本間総務部長","answer":"当面来年度から1,０００万円以上の工事につきましては、この制限つき一般競争入札を拡大するよう現在検討を進めているところです。こういう適用につきまして、検討をしてまいりたいと、このように考えているところです。","id":"exchange-005"},{"speaker":"石田委員","kind":"質問・要望","question":"ここでもう一点、最終的に確認をしたいんですが、必ずできるところというのはあるはずなんですね。これに対するご見解をひとつお願いいたします。","respondent":"高橋区長","answer":"それから、予定価格の事前公表も２３区初めてやりました。品川区も損をしない、そういうことにつきましても鋭意検討してまいりたいと思いますので、よろしくお願いいたします。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問・要望","question":"続きまして、私の持ち時間は２０分で、あと１０分ぐらいですので、教育のほうに入らせてほしいと求めました。最初にまず教えていただきたいのは、この子どもたちも公教育の中に入ると思いますが、その点の確認をお願いしたいと思います。","respondent":"指田教育次長","answer":"この進学率の状況というのは、ここ数年大体２０％前後でもって推移していると、こういうような状況にあります。それから、私立が公教育かどうかですが、やはり、私立も公教育です。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"約２割の子どもが区立小学校から私立中学校へ行くということでありまして、多種多様の中でそういう選択肢も生まれてきているということであります。私立中学校へ行くわけでありますから、その理由とかいうものを教育委員会のほうでは把握をしているのかどうか、教えていただきたい。","respondent":"指田教育次長","answer":"一般的なお答えになるかとも思いますけれども、あるいはお子さんが私立中学というものを選択しているのではないかと、このように受けとめているところです。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"その理由の把握というのは、その小学校で学んでいるわけでありまして、そこら辺の把握もしていただきたい。していないとか、そこら辺の学ぶことはあるのか、そこら辺のことをちょっとお聞きをしたい。","respondent":"指田教育次長","answer":"前後するかもわかりませんけれども、私どももご承知のとおり教育改革プラン２１を進めてきてあります。交流の機会というのはそう多くはありませんけれども、品川区教育委員会で年１回ですが、情報の交換は持ってあります。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問・要望","question":"年１回校長の代表の人が交流をする、今のお話の中で、来る者は拒まずという形が区立中学校と私立高校の場合にはある程度できていたんじゃないのかな。それは教育委員会としては、ぜひ推し進めていただきたいというような気があるんですが、そこら辺についてのお考えを。","respondent":"若月教育長","answer":"私は私立の先生より、とりわけ公立の先生が劣っているとかなんとかということは全くないだろうと、こんなふうに考えているところです。","id":"exchange-010"},{"speaker":"石田委員","kind":"確認","question":"そのためにも交流を深めてほしいというのと、もう一点聞きたいのは、都の教育委員会もありますよね。結構そこの二つのところとか、そういうところが何かいろいろ注文をつけてくるのかどうか、そこら辺のちょっと確認をしたい。","respondent":"若月教育長","answer":"そこで、品川の実践といったようなものをどうとらえているかという記事は何回か触れました。私たちに何かを言うというよりも、私学自身も頑張ろうというような意気込みの込められた文章のほうが多いというのが現状です。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問","question":"そういう子に対する、逆に、学校でずっといるわけですから、それは区立小学校にいるわけですから。試験も適当にやっておけばいいやと、その子どもたちにはあると思うんですが、そこら辺はどうお考えになっているか。","respondent":"指田教育次長","answer":"ご承知のとおり国においても、例えば指導要領については最低基準であると、こういう考え方も最近では示してきております。すなわち、底上げもやらなければいけないでしょうし、同時に発展もしていかなければいけないだろうと、このように受けとめてあります。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"ですから、その子たちの３年間なり、そういうものはどうするんだ。そこら辺のところもよくお考えになっていただきたい。","respondent":"若月教育長","answer":"お答え申し上げます。当然、これからさまざまな子どもたちのニーズに応えられるような教育活動を展開してまいりたいと、こんなふうに考えているところです。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"初めに、仮称保育園ＰＴＡのことについてお伺いします。お伺いしたいのは、ここに至って、区長のまず感想を説明するよう求めました。","respondent":"小沼福祉事業部長","answer":"２点目の今後の進め方の問題とも関係してくるわけですけれども、今私のほうも各園で実施状況について、それぞれヒアリング。これが率直なところですので、自信を持って今後この事業の拡大に努めてまいりたいと、このように考えてあります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"そこで改めて、いわゆる公的住宅の目的をお伺いいたします。具体的には、お伺いするのは、まず収入超過の具体例をプライバシーに配慮しながら教えてくださいということが一つ。","respondent":"山室住宅指導担当部長","answer":"区の対応はどうかですが、さまざまな取り組みが提案されておりますが、有効利用を打ち出しております。都と連携するとともに、区としてのあり方について検討し、環境を整えたものから改革をしていきたいというふうに考えております。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、確かに２件なんでしょうけれども、この数字はもっと増えていく可能性が十分あると私たちは思っております。さまざまなルートでこの現状を把握しているわけですから、再度答弁、これからの考え方を改めて説明を求めました。","respondent":"山室住宅指導担当部長","answer":"その中で、特に家賃滞納者、それから収入超過者等への対応を今進めているところです。その中での対応をしていかなければいけないということと２点あるわけですが、都のほうにも強く働きかけていきたいというふうに考えております。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"どう考えても新しく建設するよりは、ほんとうに入りたい人が入れない現状があるわけですから、ここでは要望しておきます。お伺いしたいのは、清掃一部事務組合の目的、そして、東京２３区清掃一部事務組合規約附則２、２番目の公式な解釈をお伺いいたします。","respondent":"野本環境清掃事業部長","answer":"それの工事のあれが終わるまでは、２３区共同でやりましょうよということで設立されたのが、この一部共同組合である。こういうふうに二つあって、それらをあわせて、一部事務組合という形の中でやっていこうというふうになったものであるというふうに理解をしています。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問","question":"今の部長の答弁をお伺いしながら、区長が言い続けてきた内容と若干温度差を感じます。区長、答弁ありましたら、お願いいたします。","respondent":"高橋区長","answer":"だけど、それを即各区が実施するには、初めは困難だろう。２３区が共同処理しようということについては、清掃の問題については１７年度で終わるんだと、そういう考えでやっております。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"これは解散すべきだと言い続けてきておりますし、それから清掃工場を持っているわけですから、区長の答弁を聞いて安心したです。五つぐらい質問しましたでしょうか、それをあわせて、答えるよう求めました。","respondent":"市岡企画財政課長","answer":"ここまでで約５０５億円、あと９７８億円程度予定をしているということで、総額あわせますと1,４８３億円余という大きな金額になります。それから、共同処理廃止後は、現時点で計算をするということはちょっとできないということでご理解をいただきたいと思います。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"平成１２年度で品川区は１５億4,６００円余の負担金を今しているわけですから、財調算定されるということですからあれなんでしょうけど。お願いいたします。","respondent":"市岡企画財政課長","answer":"その際大事なのは、起債には制度上、その対象施設を持たない自治体がこの起債をするということはできないということになっています。これは共同処理後、これは都区間の財源配分を変更する問題として協議をしましょうと、こういうことを都知事も出た都区協議会で確認をしています。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"この工場のさまざまな現状をお伺いすると、実際私たちが工場を見させていただいた中での工場のいわゆる稼働率というんですか、６割前後だったです。ですから、これを果たして一部事務組合で抱えていくことが正しいことなんだろうか。","respondent":"野本環境清掃事業部長","answer":"これは考え方で、業務内容を変更したり拡大するというような道があり得るならば、当然そういうものを民間のほうから知恵を絞って。そういうような認識は持っております。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"安定した身分保障制度をすることによって、いわゆる全体の奉仕者としての仕事をしていただきたいというふうなことが求められていると考えています。このことに対する区長の考え方をお伺いするのと、職員採用、給与表等を独自に作成して立派な地方自治をやっているわけであります。","respondent":"高橋区長","answer":"その発言をしたとき、脱退もできないんだ。すぐできるとは思いませんが、一つ一つ、そういう気持ちで改革をしていきたいと考えています。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、それから世田谷区は７０万人ですか、ある意味東京都が２３区をコントロールするために置いているのではないかということ。ですから、一緒にやろうよというふうな働きかけをしていくほうがいいかなと思うんですが、答弁をお願いいたします。","respondent":"高橋区長","answer":"だから、２３区で私と同じような考えを持っている区長はかなりいると思います。だけどやはり、それなりにひとつ、一緒にばかになってやろうじゃないかというようなことをこれからも呼びかけていきたいと考えています。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、できれば、これをそれぞれの区、区長が、特に区長が各区の区民のために取り組んでいただきますようにお願いしておきます。改めて区長の決意をお伺いいたします。","respondent":"高橋区長","answer":"しばしば申し上げておりますが、区の施策を進めていく基本は財政と人です。したがいまして、その基本は忘れずにひとつこれからもやってまいりたいと考えています。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"政調会を通しての質問の勉強会、なるべく多くの区民の政策要望を質問させていただきましたし、それから政策要望も提出をさせていただきました。どうぞ、平成１４年度予算に生かしていただきますように、大きな要望をお願いいたしまして総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"山路委員","kind":"質問","question":"質問の内容は、水と緑の市町村交流事業について、高齢者の居住の安定確保に関する法律に関連してお伺いいたします。品川区において、当初計画されたとおりに推進しているかどうか、お伺いいたします。","respondent":"中尾根企画部長","answer":"ところが、結果的には2,９９７人ということで、ここのところの参加が８０％ちょっとということで、見込みとちょっと違っているです。再び2,３１０人の予定のところ、夏の見込みの分はありますけれども、このように受けとめてあります。","id":"exchange-026"},{"speaker":"山路委員","kind":"質問・要望","question":"何とかして１万1,０００人は達成していってもらいたいと思うんですが、今まで受講した人の意見とか要望とか、あるいはアンケート等はどのように掌握されているかについて教えてほしいと求めました。","respondent":"中尾根企画部長","answer":"最後の冬の分が残ってありますけれども、冬の予定は2,４００人をやはり予定しています。この見込みですけれども、過去３回やった中での2,０００人台の予定ということでしたら、このように受けとめてあります。","id":"exchange-027"},{"speaker":"山路委員","kind":"質問","question":"何とか１万1,０００人をクリアする見込みということなんですが、万が一定員を割ったときに、２回目の受講をしたいという人がいらっしゃった場合、そういうときに私は２回目でもいいんじゃないかという考えを持っているんですが、その辺はどういうふうにお考えか尋ねました。","respondent":"中尾根企画部長","answer":"それは、１回きりで、２回はだめという、こういう条件が実はついていたんです。現在では２回目もあいていたら受けたいという方については、品川区におきましても、既にそういう体制で取り組んでいるところです。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問・要望","question":"当然として次のクラスを求めているということは、１３時間以降の講習を希望したいという人も、私たちのもとには意見をいただいているわけです。仮称パソコンお助けマン制度を設置したらどうかと思うものでありますが、どのようにお考えでしょうか、お伺いいたします。","respondent":"指田教育次長","answer":"例えば先般の本会議でもお話し申し上げましたけれども、親子パソコン教室だとか、そういうものも各学校では考えて今取り組んでおります。地域の方々がいらっしゃったらば、ぜひともボランティアとしてここには参加をしていただきたいというふうに考えているところです。","id":"exchange-029"},{"speaker":"山路委員","kind":"提案","question":"３点目は、身障者でＩＴ講習会を受講し、パソコン購入の希望者にパソコン代を補助する制度の導入についてお伺いいたします。受講後、私はパソコン代をこういう方に補助してもよいのじゃないかと提案するものですが、ご見解をお伺いいたしますとの意見を述べました。","respondent":"中尾根企画部長","answer":"こうした背景から、国におきましても、積極的に何らかの対策をしていきたいというようなことで、支援策の動きもあります。したがいまして、これら国・都などの動向も十分見極めながら、具体的な検討を今後進めてまいりたいと、このように考えているところです。","id":"exchange-030"},{"speaker":"山路委員","kind":"質問","question":"次に、文化芸術についてお伺いいたします。質問の第１点目は、どんな公的支援策を想定されているのか、お伺いしたいと思います。","respondent":"中尾根企画部長","answer":"お尋ねの区における方針といたしましては、多様な文化活動への支援をしていくということで、支援策ですね。一番目の多様な文化の支援といたしましては、青少年の文化活動への支援策、これが総合実施計画上に乗ってありますし。","id":"exchange-031"},{"speaker":"山路委員","kind":"提案","question":"質問の第２点目に当たりまして、「仮称全員集まれ、若手芸術家品川まつり」の開催の提案をさせてほしいと求めました。激励など、公的支援の一環としてはどうかと考えるものですが、ご所見をお聞かせほしいと求めました。","respondent":"中尾根企画部長","answer":"考え方は同じようなところに根ざしました事業を幾つか行ってございまして、例えば、一つには文化フェスティバルというものを毎年実施しております。","id":"exchange-032"},{"speaker":"山路委員","kind":"提案","question":"今回は文化芸術の振興という中において、インターネット接続のホームページに文化財の作品を公開し発信することを提案するものであります。大きな役割を果たすものと考えますが、どのようにお考えでしょうか、ご意見を賜りたいと思いますとの意見を述べました。","respondent":"指田教育次長","answer":"約２万8,０００余の資料があるわけですけれども、ちょうど幸いなことに、ホームページを今各事業部ごとにつくってあります。私どものほうも、１１月を目途にいたしまして、今教育委員会としてのホームページを開設する予定でおります。","id":"exchange-033"},{"speaker":"山路委員","kind":"質問","question":"平成１３年度、改めてお尋ねしたい点は、交流事業を継続発展させていくためのどんな自助努力を双方に期待しているのかということであります。ご所見をお伺いいたします。","respondent":"小栗区民生活事業部長","answer":"早川町につきましては、親子で田植え、稲刈り体験や渓流釣り、ホタルを鑑賞する会など、たくさんの交流事業を実施しております。そのバスを活用するなどいたしまして、魅力ある事業に交流事業を発展させ、経費の節減を図ってまいりたいと考えている所存です。","id":"exchange-034"},{"speaker":"山路委員","kind":"提案","question":"提案の２点目は、野生体験など、都会では味わえない貴重な体験をしてもらうようにしてはどうか。提案の第３点目は、ゲートボールのみならず高齢者の作品の交流を図り、相互の交流が図られるようにしてはどうかということでありますとの意見を述べました。","respondent":"小栗区民生活事業部長、新美保健高齢事業部長、指田教育次長","answer":"次に、早川町の北小学校を利用した短期サマースクールの実施ですが、来年度から全国の小・中学生を対象に山村留学の受け付けを始めるとのことです。… 私からは、３点目と４点目のご提案についてお答えいたします。私どもとしては、今後とも区民を対象にした行事… 自然体験教室は、自然の豊かな場所で遊びとか、あるいは体験を通して子どもたちの心身の健全育成を目指すという形でもって実施してきてあります。","id":"exchange-035"},{"speaker":"山路委員","kind":"提案","question":"島倉千代子さんが見えるんで、その点も加えて要望しておきますので、どうぞよろしくお願い申し上げます。水と緑の交流についても、財団法人文化振興事業団に所管を移して推進していくお考えはないか、区長のご見解をお伺いいたしますとの意見を述べました。","respondent":"高橋区長","answer":"それとも、そういうふうなところと一緒にやったほうがいいのか、これは一つの検討課題じゃないのかなというふうに思っています。方法論につきましては、十分検討させていただきたいと思っています。","id":"exchange-036"},{"speaker":"山路委員","kind":"質問","question":"次に、今月施行された高齢者の居住の安定確保に関する法律に関連してお伺いいたします。そこで、なぜ板橋区と大田区だけで、そのほかの区は加入していないのか、また、品川区が加入しない理由についてお伺いいたします。","respondent":"新美保健高齢事業部長","answer":"第１に家賃滞納時の賠償に対する金銭保証であり、死亡時に対応する身元引受的な仕組みになっていないこと、第２に高齢者の生活支援や見守りがなく。","id":"exchange-037"},{"speaker":"山路委員","kind":"質問","question":"９月２１日の本会議で我が党の辻委員が質問して、そこでお尋ねしたいことは、自信があると受けとめてよいのかどうか。この問題については、一番ニーズが高いと思うんですが、どのようにお考えか尋ねました。","respondent":"新美保健高齢事業部長","answer":"そういったときにどう対応するべきかというのは、これまでも家主の方からのご相談、支援センターにつなげる等々のことを対応に努めてまいりました。","id":"exchange-038"},{"speaker":"山路委員","kind":"意見","question":"ここのところについて、たくさん現場では部屋が借りれないという方がいらっしゃいますので、もう一度ご答弁をお願いしたい。住民の方、生活者を満足させることについて、もう一度ご答弁を願いたいと思いますとの意見を述べました。","respondent":"新美保健高齢事業部長","answer":"１０月から家賃保証制度も実施されるということで、私どもも具体的に東京都でどのような制度運営をするかは、先々月に示された段階です。その活用については十分検討し、整合性を見直しつつ、活用について検討してまいりたいというふうに考えております。","id":"exchange-039"},{"speaker":"山路委員","kind":"質問・要望","question":"現場で高齢者が安心して民間住宅に住み、品川区に長く住み続けるようにしていただきたいことを要望して、私の総括質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"桜井委員","kind":"質問・要望","question":"特に今回示された２１２の事務事業評価について明らかになった点は、事業の縮小、受益を受ける者は応分の負担を求めていく姿勢が色濃く出ております。改めて区の行政評価、事務事業評価についての総論的な考えを伺います。","respondent":"中尾根企画部長","answer":"そういう取り組みの結果といたしましては、実施方向が明確になってきたということが挙げられますし、首脳部のこの分析や考え方をご提示いたしました。","id":"exchange-041"},{"speaker":"桜井委員","kind":"提案","question":"区民の福祉、暮らしの充実を図ることと考えているというふうに答弁しておりますけども、そうではないんでしょうか。３点目には、すべての事業について評価すべきという提案を申し上げたわけですけども、そのことについて改めてお尋ねしますとの意見を述べました。","respondent":"中尾根企画部長","answer":"継続する事業、それぞれがどういう視点でどういうレベルでそういう評価をしているのか、そこのところを十分見ていただきたい。住民の参加のほうにつきましては、先ほど言いました今後の外部評価委員会等の、そういう中でご活躍いただければと、このように考えてあります。","id":"exchange-042"},{"speaker":"桜井委員","kind":"質問","question":"あるいは青年たちは２人に１人が就職難という、例えば場合によれば費用がかかったにしても、この考え方についてお尋ねします。係わっている住民の皆さんがどういう希望を持っているのか、やはり入れるべきだというふうに考えますけど、いかがか尋ねました。","respondent":"中尾根企画部長","answer":"このことに意を費やしてずっと行政改革も進め、こういう評価を得ている結果だ、私はこのように自信を持っております。こういうふうに考えて、そこのところは十分ご理解していただきたい、こう思っております。","id":"exchange-043"},{"speaker":"桜井委員","kind":"質問","question":"さまざまな、今民主主義の世の中ですから、いろんな価値観があり、いろんな多様な意見がある。そして、その現状と対策を改めて伺いたいというふうに思います。","respondent":"小沼福祉事業部長","answer":"東京都と２３区での大きな区分といたしましては就労関係、産業労働経済局と、就業就労対策についての一つの検討に入っているという状況です。","id":"exchange-044"},{"speaker":"桜井委員","kind":"質問・要望","question":"８割の方が職を求めているという事態で、今品川で７０名というお話なんですけども、その傾向は私は同じではないかと思うんですね。今後の生活保護の行政の改善、これについてもあわせてどういう考え方があるのかをお尋ねしたいと思います。","respondent":"高橋区長、小沼福祉事業部長","answer":"２３区では、ブロック別に役割を決めているわけでございまして、一番多くのホームレスを抱えている区が自立支援センターを設置していく。… それから私どものほうの考え方も同じですけれども、一般的な保護開始の要件なり、こういうような形になってくるということでご理解いただければと思います。","id":"exchange-045"},{"speaker":"桜井委員","kind":"質問","question":"ですから、私はやはり、この職を失った理由が不況の影響、これが大きいということは、政府自身も認めているわけなんですよ。二つ改善策が出されております、国のほうのケースワーカーの説明会で、その二つの改善策を改めてお尋ねします。","respondent":"小沼福祉事業部長","answer":"先ほど申し上げましたような基本的な考え方は、自立支援センターであるとか、こういう中身のものです。それにのっとっての運営なり、運用なりを図っていくと、こういうふうにご理解いただければと思います。","id":"exchange-046"},{"speaker":"桜井委員","kind":"質問","question":"ですから、いてほしくないというのを暗に区民ではあってほしくないみたいな、そういうニュアンスが強く出るわけですよ。改めて見解をお願いします。","respondent":"高橋区長","answer":"その人たちの自立を促していこうということが、そこから始まったわけでして、それぞれの東京都と２３区が共同してそれをやっていこう。したがって、他区に行っていただくと、これは当然のことだと思いますよ。","id":"exchange-047"},{"speaker":"桜井委員","kind":"意見","question":"大変今の政治の貧困さをどう見るかと同時に、そこにやっぱり住んでいる人たちに対しての生活保障をどうするかという大変複雑な問題もはらんでいます。それで、今お話が出ました生活保護の５年間の実績をまずお尋ねしますとの意見を述べました。","respondent":"小沼福祉事業部長","answer":"それから平成８年度ですが、1,８４３世帯というような、今申し上げた数字です。８年度が7.０パーミルと、こういうような５年間の数値は、今申し上げたようなところです。","id":"exchange-048"},{"speaker":"桜井委員","kind":"意見","question":"法律をそのかわりにどうやって社会保障、保障制度のセーフティーネットをやるのかということがないままに、その保護率をどんどん下げる。これはどういうところから来ているのか、ご説明くださいとの意見を述べました。","respondent":"小沼福祉事業部長","answer":"いわゆる、品川区のフェースといいますか、場面で考えますと、当然自治体としてできることとできないこと、これはあります。やはりハローワークとの連携、基本的には今申し上げたようなところが品川区の福祉事務所として取り組むべき、まず一番大きな課題だろうと思います。","id":"exchange-049"},{"speaker":"桜井委員","kind":"質問","question":"それが８０枚になって、７０枚になって、今は何枚ですか、７０枚でしょうか、あるいは５６枚でしょうか。ここのところにメスを入れるというのはどういうことなんか尋ねました。","respondent":"小沼福祉事業部長","answer":"今年がちょうど２年目というようなたしかところだったと思いますけれども、基本的な考え方というのは、やはり基本的に相当違うところに来ているです。今後の状況等を考えますと、自立の支援であるとか、こういうことでご理解いただければと思います。","id":"exchange-050"},{"speaker":"桜井委員","kind":"質問","question":"ですから、きちっとしてもとの１週間の２回に戻して、よっぽど自立支援じゃないですか。これは部長のほうにお聞きしたいところなんですけれども、６５歳以上の介護保険の保険料を見たときの所得の現状というのをちょっと示すよう求めました。","respondent":"高橋区長、小沼福祉事業部長、新美保健高齢事業部長","answer":"高齢者は金持ちだと私言いません。言われていると、たしか言ったと思いました。あるいは時代的な背景というのを考えて、東京都２３区ですけど、それが法外援護と称されているものです。これは本来あるべき生活保護の考え方であろうと… 現在のところ、介護保険が導入されまして、保険料が所得に応じた５段階になっております。","id":"exchange-051"},{"speaker":"桜井委員","kind":"質問","question":"ご承知のように生活保護は国の制度ですから、あるいは大都市、いろんなやっぱりそれぞれの実態があるわけですよね。ですから、品川区は品川区だという、品川区にふさわしい保護制度をやるべきだというふうに思うわけです。","respondent":"中谷まちづくり事業部長","answer":"そういうことで、公園もないというような地域で、都市基盤が非常に脆弱ですので、土地の有効利用ができないというような状況にもあります。","id":"exchange-052"},{"speaker":"桜井委員","kind":"質問","question":"総事業費とかいろいろと聞いたんですけど、それも説明を求めました。","respondent":"中谷まちづくり事業部長","answer":"今後動いていくということが考えられますが、総事業費は概ね６００億円前後を予定しておりまして、概ね１００億円前後を見込んでいるところです。","id":"exchange-053"},{"speaker":"桜井委員","kind":"質問","question":"そこで入れるのはやっぱり１００億円ですよ。私は、なぜこんなに民間の大規模開発に湯水のようにお金をつぎ込むのかと、改めてお聞きしたいと思います。","respondent":"中谷まちづくり事業部長","answer":"この大崎駅第３地区につきましては、ここは駅前に極めて近いところでございまして、品川区の大井町とともに顔とも言える部分です。住宅を誘致すると、こういうことにつきましては、定住化の促進ということで、力を入れているところですので、ご理解いただきたいと思います。","id":"exchange-054"},{"speaker":"桜井委員","kind":"質問・要望","question":"次に、住民参加、情報提供についてお尋ねします。それからもう一つは、どのようにその方々に情報提供をされているのか示すよう求めました。","respondent":"新美保健高齢事業部長","answer":"区内の居宅介護支援事業者数ですが、事業者指定をしている区内に住所を有する事業者数につきましては、現在４９です。うち、区の在宅介護支援センターが１７、それ以外が３２ということになります。","id":"exchange-055"},{"speaker":"桜井委員","kind":"意見","question":"ごめんね。在宅者の連絡情報提供はどうなのかと聞いたんですとの意見を述べました。","respondent":"新美保健高齢事業部長","answer":"居宅介護支援事業者のうち、在宅介護支援センターについては、あるいは区の方針等を通知し。質疑応答等でいろいろ理解を深めていただき、また、区の方針等について説明する必要があるものは説明をしています。","id":"exchange-056"},{"speaker":"桜井委員","kind":"質問","question":"去年４月から実施されて、かなり１年の間でも、東京都の今度は介護制度の利用者への軽減の問題がありますよね。その都度、かなり改善され、あるいは変更されてきた、その都度というのは、変更されてきたときに３２の事業者に連絡をしているんか尋ねました。","respondent":"新美保健高齢事業部長","answer":"私どもは区民の方がサービスを利用しやすいように、中心になって担っている方と区の方針等にご協力いただく方々を中心に情報提供しております。十分個別にご説明、対応しておりますので、そういったところでぜひ情報収集をよろしくお願いしたいと呼びかけているところです。","id":"exchange-057"},{"speaker":"桜井委員","kind":"質問","question":"宮崎委員のほうで課長との質問の中で、私は第一義的に情報収集ではなくて、情報提供があると思うんです。在宅介護支援センター以外の皆さんは、先ほどちょっと部長が言いかけたんですけども、何名いらっしゃいますか尋ねました。","respondent":"新美保健高齢事業部長","answer":"ご質問は在宅介護支援センター以外で、ケアプランを作成している方が何人いるかと、そういうご質問でしょうか。８月審査分の介護報酬請求から見ますと、８１事業者、３０９件の介護報酬請求が支援センター以外から来ております。","id":"exchange-058"},{"speaker":"桜井委員","kind":"質問・要望","question":"私は、これは情報提供の責任としてぜひ改善を求めたいと思うんですよ。ですから、そうした在宅介護支援センターの事業者への情報提供をぜひこの場でお約束をいただきたいというふうに思いますけど、いかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"どこでお聞きになっても、それだけでしたら、区があえて説明しなくても同じです。これにはご協力いただく方には十分ご説明をしたいと思いますし、その辺についてはそういう関係の中で情報提供をきちんとしていくです。","id":"exchange-059"},{"speaker":"桜井委員","kind":"質問・要望","question":"これはおかしな話ですから、これは強く改善を求めたいと思います。これは毎回ここ１０年余の間で５回、６回ほど指摘しておりますけども、その後改善されたというふうに区長はお考えになっているか尋ねました。","respondent":"中尾根企画部長","answer":"一つ一つ丁寧に区政への反映ということを考えてありますけれども、それからどのように反映したのか、こういうことを丁寧にお答えをする。これを検討いたしましたけど、この方法を続けさせていただきたい、このように考えてあります。","id":"exchange-060"},{"speaker":"桜井委員","kind":"質問","question":"「その後どうですか、「もう既に今年８月２４日から４回にわたって課長に会談を要請してきたんですけども、まだ会えない」と。そのルールはどうも学童の課長との間では、ルールが確立していないようですけど、ルールを確立する意思があるんか尋ねました。","respondent":"小沼福祉事業部長","answer":"私のほうからお答え申し上げますけれども、この場、それに基づいて私どもは基本的には取り組むということで対応しているつもりです。聞くというものについては、区長がご答弁申し上げたようなところでの仕切りになっていると、こういうふうにご理解いただけばと思います。","id":"exchange-061"},{"speaker":"桜井委員","kind":"質問・要望","question":"じゃあ、課長がルール違反しているんでしょうか。それについて、聞く耳を持たないということなんか尋ねました。","respondent":"高橋区長","answer":"お願いですよ。それじゃなければ、また会うことができなくなりますので、それだけは申し添えておきます。","id":"exchange-062"},{"speaker":"桜井委員","kind":"質問","question":"昨年３月に話し合いを持ったようですけども、そのときの話し合いというのはどうだったんでしょうか。紳士的だったんでしょうか、お尋ねします。","respondent":"小沼福祉事業部長","answer":"昨年の３月２３日の話の状況が紳士的だったかなんか、ちょっと私それについて、今詳しい経過が思い出せないんで、何とも言えないという状況です。両当事者で会う場面があったということであればですね、そういうふうに考えてあります。","id":"exchange-063"},{"speaker":"桜井委員","kind":"質問","question":"ですから、私はそういう点で今部長がきちっと対応するということでありますから、それを了として見守っていきたいと思います。そして、概要についても、権利者の関係も示すよう求めました。","respondent":"中谷まちづくり事業部長","answer":"この説明会等の概要ですが、ご存じのとおり８月３０日の説明会以降、商店街の理事会延べ６回、１１０名を超える皆様方とお話をしてまいりました。","id":"exchange-064"},{"speaker":"桜井委員","kind":"質問","question":"一般質問の答弁で、区の認識としてこの問題、一本橋商店街の理解が得られなければ、本事業の進展はあり得ないと。ですから、あるいはそこに仮の住宅あるいは店舗ということも含めてやっていくということについての考え方をお聞きします。","respondent":"中谷まちづくり事業部長","answer":"これは個々の皆様のまず意見をお聞きして、そして、それぞれ一人ひとりの対応をしていくということが私どもは肝心だと考えています。","id":"exchange-065"},{"speaker":"桜井委員","kind":"質問・要望","question":"同時に区長がマイクを用意されているようですから、区長の決意があれば、お聞きしたいというふうに思います。区がある面では独自の施策をとっていくということも必要ですし、その点では商店街振興のところももう一つあわせて最後のお尋ねをしたいと思います。","respondent":"小栗区民生活事業部長、中谷まちづくり事業部長","answer":"それで意見を聞いてありますが、今商店街のほうでも、具体的にどういうような対応策をするかということで検討を始めてあります。こういうお申し出を受けておりますので、具体的な対応策が出てきました段階で支援などを検討してまいりた… 先ほどもご説明しましたとおり、今まちづくりについての動き、これについて区は最大限支援をしていくということで先ほど申しました。","id":"exchange-066"},{"speaker":"桜井委員","kind":"意見","question":"商売していてよかったと言えるような、そういう点ではやっていきたいといふうに思いますし、区のほうもご努力を一層お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"川西委員","kind":"質問・要望","question":"２番目は、小・中学校における環境教育について内容を伺います。３番目は、そしてあっせんできるシステムづくりについて、どのようにお考えであるか伺います。","respondent":"野本環境清掃事業部長","answer":"太陽光発電の有効活用に関し、そういうようなものを通じて積極的に区民へのＰＲについて実施をしていきたいと、かように考えてあります。そういうものを常に証拠となる書類を常に押さえながら進めていくというのが環境ＩＳＯであるというように認識しています。","id":"exchange-068"},{"speaker":"川西委員","kind":"質問・要望","question":"私は今６５歳ですから、これからいわゆる高齢期を迎えるといいますか、もうそうなんですけれども、人たちにやはり責任があると思う。ですから、地域センターということになりまして、出前相談みたいなものをしていただけることはできないんだろうかということが一つの質問です。","respondent":"新美保健高齢事業部長","answer":"まさに健康づくりプラン２１の検討テーマそのものですので、ご質問の趣旨も踏まえまして充実できる方向で検討してまいりたいというふうに思います。","id":"exchange-069"},{"speaker":"川西委員","kind":"質問・要望","question":"プラン２１にこれらのことをぜひ盛り込んでいただきたいと要望いたします。しかし、その後、設置の要望があるのかどうか伺います。","respondent":"中谷まちづくり事業部長","answer":"今具体的な検討を行っておりますので、近々、徐々にまちから花壇が増えていく日が来るんではないかということで考えております。平成６年の調査で１0.９％でございまして、これが平成１１年度の調査で１２％ということで、1.１％の増を見ているです。","id":"exchange-070"},{"speaker":"川西委員","kind":"質問・要望","question":"小さい子を連れていますから、どうしてもトイレということになって、その地域の事情を見ながら検討をお願いしたいというふうに思います。ですから、公共的な区であっても、そのことが必要だというふうにお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"土井委員","kind":"質問","question":"私どもが２０分という少ない時間なものですから、ご協力をいただいたことにまずもって感謝を申し上げておきたいというふうに思います。どのようにお考えになっているか、そういうものについてどのようにお考えになっているのか、まずもってお伺いをしたいと思います。","respondent":"中尾根企画部長","answer":"今委員ご説明ありましたように、戦後の昭和２７年の自治法の改正、幾多の運動がありました。今後どのように２３区で考えていくのかという中で、また新たに決まっていくのではないかと、このように受けとめてあります。","id":"exchange-072"},{"speaker":"土井委員","kind":"質問・要望","question":"本来でいけば、品川の独自性を持ちながらどう進めていくのか、この辺についての考え方をぜひ後から聞かせていただきたいと思っているわけです。きちっと決めて、それ以外は絶対に譲らないという態度をしっかりしていかなきゃいけないと考えていますので、その辺の考え方についてお伺いします。","respondent":"高橋区長","answer":"２３区と東京都で財調の問題についての取り組みを今後進めていかなくちゃならないわけでございまして、この２３区と東京都の関連がなくなれば。したがいまして、２３区の物の考え方に私はよっていくものと、そういうふうに考えております。","id":"exchange-073"},{"speaker":"土井委員","kind":"質問","question":"そうすると、逆にそれはいつごろどのように決めるのかということが大変重要だと思いますので、お伺いをしているわけです。みんなも努力もする、もうそろそろ方向性を打ち出していかなければならないと思いますのでお伺いしていますので、その点を説明するよう求めました。","respondent":"高橋区長","answer":"これは法的な問題でございませんで、２３区の中でどういう方法がいいだろうかということを検討し合えばいいわけです。まだ２回しかやっておりませんけど、そういう問題を平成１７年度までに鋭意具体的な問題を出していくと、これが２３区の取り組みの一応予定です。","id":"exchange-074"},{"speaker":"土井委員","kind":"質問・要望","question":"第２段階に入っていこう、さらにこれからどのようにしていくのか、この辺について若干のご説明をいただきたいというふうに思います。これが、これを何としても入れようということなもんですから、これらとの関連も含めて若干お聞かせをほしいと求めました。","respondent":"中尾根企画部長","answer":"それと、操作をするのは職員ですから、職員がきちんとそういう能力を持たなきゃいけない、こういうようなことを同時にあわせて今対応しています。","id":"exchange-075"},{"speaker":"土井委員","kind":"質問・要望","question":"これからやっぱりせっかく組んでいくわけですから、将来を見据えた格好で、ぜひよろしく進めていただきたいというふうに思います。必要なものを出していくと、こういうことにならなきゃならんと思いますが、その辺の考え方についてお伺いをしたいと思います。","respondent":"中尾根企画部長","answer":"できるだけホームページの中で情報を提供していきたいというふうに今考えておりまして、それぞれ事業部が競いまして、今内容を検討しています。１１月からスタートさせる予定でおりますので、そのことについてはご期待願えればというふうに思ってあります。","id":"exchange-076"},{"speaker":"土井委員","kind":"質問","question":"それから、民間にお願いをして、その辺がどうなっているかということが一つ。そして、優秀なところを確保しておくということが必要になってくるんじゃないかと思っているものですから、この辺をお伺いをしておきたいと思います。","respondent":"中尾根企画部長、指田教育次長、小栗区民生活事業部長","answer":"そういう意味では、先ほどちょっと参考に出ましたＩＴ講習につきましても、好評であった。じゃあ、その後どうしていくのか… 当然のことながら、一般的に拡大していくとなりますと、その分の対応というのが必要になってまいります。したがいまして… 平成１５年度に竣工予定ですこの開発ビルの中の保留床を使いまして、ベンチャー企業の操業支援を展開していこうと、こういうふうに考えております。","id":"exchange-077"},{"speaker":"土井委員","kind":"提案","question":"ここに提案されてきたのかというその経過について、若干お聞かせをいただきたいと思うんです。私たちが駅前やどこかで人に聞かれても、そういうことで安全が確保されるんですよと、こういうふうに説明ができるようにしたいと思って質問をしますとの意見を述べました。","respondent":"小栗区民生活事業部長","answer":"防犯についての啓発活動や防犯活動団体への活動支援といった施策を実施するとともに、活動内容を区が調整してまいりたいというようなことです。教員の参加等いただいて、各方面から広い意見を聞き、犯罪防止に努めて明るいまちづくりを推進していく予定です。","id":"exchange-078"},{"speaker":"土井委員","kind":"質問・要望","question":"だから、単なる訴えっこみたいな形になっては困りますので、ぜひそこら辺の運用等をきちんとやるように心がけていただきたいのが一つ。この辺と同じようにならないように、よろしくお願いをしたいと考えていますので、お答えを聞いて終わります。","respondent":"小栗区民生活事業部長","answer":"お話のとおり、協議会では設置目的が犯罪の防止であること、協議内容が青少年委員と重複しないよう十分注意して運営してまいります。防犯関係団体と協議し、お互いが意見交換できるまで区の施策に協力を要請していく場でもありますので、十分配慮してまいりたいと思います。","id":"exchange-079"},{"speaker":"田中委員","kind":"質問・要望","question":"第１点目は、行政評価につきまして、お伺いをいたします。そういった公の立場で評価をますます受ける環境の中においての事務事業評価の基本的な考え方についてからまずお伺いをしたいと思います。","respondent":"中尾根企画部長","answer":"区政総合業績評価システムというように幅広い観点から取り組んでいくということで、２番目には行政評価、今委員のご案内のとおりです。これを区民の皆さんに明らかにするために、自らの点検をした、こういう仕組みのねらいを持っているものです。","id":"exchange-080"},{"speaker":"田中委員","kind":"質問・要望","question":"予算編成につきましての対応ということでお伺いしたいと思いますが、次の年度の評価になる、その評価のあらわれとして予算編成があろうかと思います。予算編成のあり方とか考え方、方法などの変化があるのか、お伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"１４年度予算については、各事業部の事業部編成枠方式、こういう新しい方式をとるというご説明を申し上げました。このあたりが、新しい予算編成における事務事業評価の活用の一番のポイントになろうかと考えています。","id":"exchange-081"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった観点からも、この事務事業評価の制度を十分活用ほしいと求めました。そこにいらっしゃる職員の方々の意識というんでしょうか、その職員の方にとっての意識改革にとって、その点をお伺いしたいと思います。","respondent":"中尾根企画部長","answer":"どういう影響かですけれども、仕事一つ一つについて区民に対する説明責任、これをどうしていくかという手法の一つとして始めたものです。職員自らがどのように考えていくのかということを公表するわけですから、職員の意識が変わっていくと、このように受けとめてあります。","id":"exchange-082"},{"speaker":"田中委員","kind":"質問・要望","question":"組織、また職員の方々を含めたさまざまな意味での質的向上がこの活用によって図られると思いますので、ぜひ活用ほしいと求めました。おおよそのことと、あと、今後の導入についての予定についてお伺いをしたいと思います。","respondent":"中尾根企画部長","answer":"大きい意味での経営の方針、それから実績がどこまで到達したのか、このことを区民に明らかにするという目的です。この委員会を設置し、具体的に進めていきたい、このように考えてあります。","id":"exchange-083"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ議会の係わりというものもその仕組みの中に組み込んだほうがより質の高いものが、評価がなされるのではないかなというふうな思いを一部しておりますが、その点につきましてのお考えをお聞かせほしいと求めました。","respondent":"中尾根企画部長","answer":"政策評価のほうは、先ほど言いましたのは目的ですから、これは平たく言った言い方ですと、区長に対する諮問機関的な意味合いがあります。したがいまして、ここのけじめはきちんとつけていかなくちゃいけない、このように考えているところです。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問・要望","question":"続きまして、２番目は職員の方々の育成についてお伺いをしたいと思います。まずは品川区におきましての職員の育成についての現状の認識とか基本的な考え方をまずお伺いしたいと思います。","respondent":"本間総務部長","answer":"創意あふれる行政展開を図るには、その職員が持っている力を最大限に発揮していくということが不可欠であると、このように認識をしております。反映されるような、こういう人事給与制度に移行していくということが必要であると、このように考えているところです。","id":"exchange-085"},{"speaker":"田中委員","kind":"質問","question":"それから意識を高めるための業績評価というお話かございましたが、まず、先に研修のことについて若干お伺いしたいと思います。いわゆる人事配属の管理というんでしょうか、新しい品川区を目指していく上での新しい研修に対する取り組みということをまずお伺いしたいと思います。","respondent":"本間総務部長","answer":"事業部制が４月からスタートいたしまして、この事業部制に対応いたしまして、新しい研修をスタートさせてあります。これも事業部制に対応いたしまして、こういう事業部制に対応して、新しい研修形態を二つ取り入れてあります。","id":"exchange-086"},{"speaker":"田中委員","kind":"質問・要望","question":"それを達成感を味わえるのかどうかだとか、例えば、また意欲が生まれるのかどうなのかというところに結びついてくると思います。これは款別審査で伺った際、そういった部分も含めまして、現状または今後に向けてのその辺のお考えをお聞かせほしいと求めました。","respondent":"本間総務部長","answer":"給与制度で統一基準という２３区のそういう基準がありますが、人事委員会の委任を受けまして、任命権者の判断によって実施しています。","id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"続きまして、３番目はペイオフの問題についてお伺いをしたいと思います。地方自治体も、ものすごく神経を使いながらの対応だったと思いますが、さらに自己責任が今まで以上に求められる環境になってまいりました。","respondent":"相川収入役","answer":"地方公共団体におきますペイオフ解禁への対応策の検討を進めてまいりまして、公金預金の保護策の２本の柱からなる報告書が発表されてあります。当初予定の報告書は取りやめ、検討素材として還元をして解散したという記事が載ってございまして、現在これについて調査中です。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問","question":"品川区においての対応としてもう少し細かくお伺いをしたいんですが、やはり、基金が大変多いということが考えられます。そしてまた、制度融資が区の事業としてもなされておりますけれども、こういった制度融資の預託等に関する対応につきましてお伺いをいたします。","respondent":"相川収入役","answer":"その中で２年なり、５年の中期の視点で運用可能なものについては元本保証のものにしていきたいと、このように考えているところです。現在区内にある３０の金融機関に預託をして、防護策をどのように感性を研いで運用できるかと、これを検討しています。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問","question":"それぞれディスクローズされる資料等も分析をされていらっしゃると思いますけれども、この見極めに対する改めてお考えをお伺いしたいと思います。","respondent":"相川収入役","answer":"私どもとしても分析を進めておりますけれども、こういうところで現在私どもが期待するような分析ができるのかどうか、事前の予備調査に入っているところです。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問","question":"なかなか気が休まる日がない日が続くと思いますが、ぜひ引き続きご尽力を賜りますことをお願いいたしまして、質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"築舘委員","kind":"質問・要望","question":"変革に対応できる柔軟な発想と感性を磨き、行政評価システムの導入により、不断の努力で行政改革をさらに進めていただきますよう要望いたします。区長へ提出しました我が会派の政策要望書の各項目の内容を平成１４年度の予算編成に生かしていただきますことを付言いたしまして、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"堺委員","kind":"提案","question":"款別審査の際に、我が党委員から提案いたしました中央環状品川線都市計画素案に係る区民要望への対応、十分検討されるよう切望いたします。破綻の危険率の低い大手都市銀行へ公金を移動させるなど、公金の安全性の確保は重要な課題でありますので、一層の研究を要望いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"沢田委員","kind":"質問・要望","question":"千代田生命は全体面積の８０％を所有、ここに補助金５０億円近くも投入する理由はどこにあるのでしょうか。区民の暮らし、福祉を守る視点を貫くことなど、見直しを求めるものであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"本田委員","kind":"質問・要望","question":"見直すべきところは見直して、より充実した制度として推進され、高齢者福祉の向上を図ることを要望いたします。今後とも、出るを減らし、入りを増やす精神で堅実な財政運営に努め、財政力向上のために一層努力されますことを要望して意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"本間委員","kind":"質問・要望","question":"全般にわたり、高齢者の声を十分に聞いて、不平や不満が起きないよう努めてほしいと求めました。最後に、十分に生かしていただきますことを強く要望いたしまして、平成１２年度品川区各会計歳入歳出決算を認定することに賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"田中委員","kind":"質問・要望","question":"さらに、全国的にも注目されている教育改革プラン２１の推進、新時代に求められている品川区独自の施策であると高く評価いたします。以上により、平成１２年度一般会計決算各特別会計決算を認定することに賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/321088?Template=document&Id=1192#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":119133,"voices":221}},{"id":"h13-20011101-8","meetingId":"h13-cm11","date":"2001年11月1日","dateIso":"2001-11-01","committee":"建設委員会","time":"午前１０時０７分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問","question":"最初にその３工事まで契約されて、あるいはその３工事の引っ張る管ができないと実際は稼働できないのか、その辺をお尋ねしたいのが一つ。その３工事をやる中、どうなのかなというのがあるので、そのところをお願いしたいんですが。","respondent":"北村下水道河川課長","answer":"稼働予定時期ですが、今のところその３工事も年度内竣工ということで予定していますので、道路下の工事でいろいろな障害物等の可能性がありますが。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"それを今の第二立会川幹線だとか幾つかの幹線でポンプ所に持っていって、勝島運河に放流しようということですね。勝島運河はそれをやっちゃうと、相当汚濁が出ちゃうんじゃないかなと思うんですが、その辺はどうなんか尋ねました。","respondent":"北村下水道河川課長","answer":"今日の説明の中で割愛させていただきましたけれども、それには一時的に汚水を貯留する貯留池をつくってまいります。閉鎖性水域である勝島運河ではなくて、多少流れのある京浜運河に放流先を変更していくことで自然の浄化作用も働いてまいりますので。","id":"exchange-002"},{"speaker":"築舘委員","kind":"意見","question":"これはデータイムの１０時から１６時台ということですが、朝とか夜とか通勤のときが一番ある意味では乗り降りが多くて、利用者は望んでいるんじゃないかなと思うんですが、その点、何で１０時から１６時台ということで限られているのかとの意見を述べました。","respondent":"伊佐都市計画課長","answer":"その辺の関係で朝晩に本数を増やすことは厳しいということで、ただ全体として増やす方向では検討している。地元対応にいろいろ問題がある。","id":"exchange-003"},{"speaker":"横山副委員長","kind":"意見","question":"逆に知っている人は、閉まると２分開かないよということでくぐる人が出てくるんじゃないかなと思うんだけれども、何とかなるのか。","respondent":"伊佐都市計画課長","answer":"ただ、その辺の時間が短くできないかという話は、今後ＪＲとも検討したいと思います。昼間の時間帯には遮断時間がどの程度ということをよく踏まえて、保安状況もあり、またいろいろ提案をさせていただきたいと考えております。","id":"exchange-004"},{"speaker":"上山委員","kind":"質問・要望","question":"７月号かなんかの募集で応募して、当選というんですか、１年ちょっと経っていますよね。何か裏付けみたいなものか根拠というのでしょうか、どういうようなことがあるのか、もしわかれば教えていただきたいと思いまして。","respondent":"田村住宅課長","answer":"それをある程度見込んで、大体管理戸数が幾らなので発生戸数が大体このぐらいだということで見込んでいます。そういうことについても、うちのほうで一応東京都と相談して、若干時期がずれても登録した方については責任を持ってあっせんしていくです。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"とにかくあき家募集に当たれば、多少遅れても必ず当たるというふうに説明していいのかどうなのかというのが一つ。自殺があったりいろいろな事故住宅が、今度は載せるんだというような話を聞いたんですけれども、その辺の情報がもしわかったら教えていただけますか。","respondent":"田村住宅課長","answer":"それと２点目の事故住宅ですが、当初は二、三年前ぐらいは事故住宅については常時受付というのをやっていました。ただ、具体的にいつの時期にやるかということは、まだ現在の段階では決まっておりません。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"今の件なんですけれども、フォーマットだとか、あるいは提出するのはフロッピーみたいなものでもいいのかとか、何かそういうのがあれば、それから大体どれぐらいの分量。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、紙に手書きでもいいし、ワープロでもいいし、場合によったらフロッピーみたいなもので、何でもいいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/428096?Template=document&Id=3704#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":12778,"voices":43}},{"id":"h13-20011105-5","meetingId":"h13-cm11","date":"2001年11月5日","dateIso":"2001-11-05","committee":"総務委員会","time":"午後１時０４分～午後４時４６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"この委員会で聞いていいかどうかわからないんだけれども。たまたま田中課長もいらっしゃるからとの意見を述べました。","respondent":"田中情報システム課長","answer":"申請の部分については、その人の区民の方の名前をかたって、例えば住民票を請求するとかということを今の時点ですとチェックできないんですね。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"もう一つは、それはそれで結構なことなんですけれども、このカウントが入っているところと入っていないところがあるんですよね。どういうふうにお考えになっているのかを聞かせていただきたいのと、大きいごみだ何だと、民間とのリンクというのはどういうふうにとらえられますか。","respondent":"山田広報広聴課長","answer":"ご自分たちとしてどうしていくかを検討していただくという部分もございましたので、検証し合って、それについては何とかお伝えしたいと考えています。今一義的には、それをそれぞれ見させていただきながら十分検討していく段階だという判断で、ご理解いただきたいと思います。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"１点、いわゆるこういう言い方はどうかわからないけれども、そんなこともできるような検討をしてもよいと思う。要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中島委員","kind":"質問","question":"何かの検索のページで、５０音別ででてきたんですけれども、あれがそのまま残るんですか。中には例えば厚生労働省とか、ああいうところの検索のところには、文字を入れるとぱっと出てくるものがあるんですけど、そういうのもつきますか。","respondent":"山田広報広聴課長","answer":"一文字だけでは検索できない場合は追加の文字を入れていただいて、検索をしていく。ご自分が知りたいというところの文字という意味では、今回の検索エンジンのほうが機能はすぐれているかなというふうに思っております。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"データの更新のことについてちょっとお伺いいたしますが、ちょっと確認の意味も含めまして、その後に出てきた最新情報が各事業部のホームページのデータも更新されるのかどうか。","respondent":"山田広報広聴課長","answer":"考え方といたしまして、優先順位が出てしまうものについては同時掲載をしていくという約束にしてあります。例えば保養所の空き情報を１１月末ぐらいから所管とすれば入れていきたいということで、リンクされているという考え方にはならないかと思います。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"１０月までは所得制限の緩和はなかったわけで、１０月以降、いろいろなサービスがどんどん追加されます。最新情報を見れば１０月以降変わったということはわかるんですが、今後はそういうことも更新されていくのかどうかということでちょっとお聞きします。","respondent":"山田広報広聴課長","answer":"一つ更新すると、それが自動的に更新できるというシステムがあるんですが、それの導入までにはちょっと至らなかったんですね。予算の関係ではなくて、あくまでも考え方としてまだそこまでいっておりませんので、ご理解いただきたいと思います。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"リンクのことでちょっとお伺いしたいんですが、逆に横のリンクというんですか、横のリンクが行けるのかどうか。利便性を考えると行けたほうが便利だと思うんですが、どうなんか尋ねました。","respondent":"山田広報広聴課長","answer":"それを６日にそれぞれ事業部ごとにチェックを入れていただいておりますので、張れるものについては張っていくということで、考えております。そこからまた事業部、張り方の問題ですので、業者等を含めて検討をしていきたいというふうに考えてあります。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう部分をどういうふうに立て分けて、逆に職員の残業手当等、どういうふうにホームページの作成について考えていったらいいのか。そこらあたりをちょっと教えていただきたい。","respondent":"山田広報広聴課長","answer":"やはり業者の支援なくしてはできないだろうというところで、５０万円ベースにして６部ということで、３００万円設けてあります。なかなか異動というのは、同じ事業部の中の異動ということが考えられますので、ご理解いただきたいと思います。","id":"exchange-008"},{"speaker":"土井副委員長","kind":"質問・要望","question":"それから、この辺のつくり上げといいますか、構築をどうしていくのかというのはこれからの一つの大きな課題じゃないかなと思うんですね。その辺の研修も含めたものをどのようにしていくのかというところでは、ちょっと思いがありましたら説明するよう求めました。","respondent":"山田広報広聴課長","answer":"最初のメンテに関しては、明日からスタートだというふうな認識を持っております。やはり一定のレベルというものは私どもも保持してまいりたいというふうに考えてありますし、ある意味では研修の一環として取り組めるものであれば。","id":"exchange-009"},{"speaker":"土井副委員長","kind":"意見","question":"均一化が保てない、あるいは同時性が保てないということになりますので、ぜひそこのところはよろしくお願いをしたいというふうに思います。これはしたがって、情報の話でもあり、人事の話でもありということになりますので、よろしくお願いをしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"この比較の方法というのは、ずっと変わらないんか尋ねました。","respondent":"古川人事課長","answer":"これは人事院、それから全国の人事委員会、すべて同じ基準で実施しています。それから、その前提となる各種別あるいは責任度合いの調査、これも基本的には同じ考え方で実施して、こういうようになっております。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"変わらないというのは、地域でなく全国レベルということと、時間的に１０年置きに比較の仕方を変えようとか、そういうことはやっていないんか尋ねました。","respondent":"古川人事課長","answer":"人事委員会は５３年にご案内のとおり特別区が設置したと思うんですが、そのときからこのやり方は変わってございませんで、全国的に一定の仕事の方法である、こういうふうに理解しております。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"雇用の安定性、すべてを比較して、もう民間のほうから公務員はどういう状況になっているんだという怨嗟の声が相当上がってきている。それから、今言ったようないろんなものを比較しなきゃいけないんじゃないかということについて、いろいろどういう考え方を持つべきか尋ねました。","respondent":"古川人事課長","answer":"給料表自体の考え方、市町村も含めて同じ基準でやるということについては一定の今後検討する余地があるのかなと、時代的には少し合わなくなってくる。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"助役に伺いたいんですけれども、年収として比較するべき、何しろ高齢者の雇用の安定性が非常に悪くなっていますね。ワークシェアリングで、あるいは会社が存続しないという状況もかなりあるわけですから、そういうことから比べると。","respondent":"濱野助役","answer":"その認識については同じ認識を持っています。もちろん最善ではありませんけれども、現時点でのとり得べき方式ではないかという、そういう認識です。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"これをどうやって、どういう手順で、どうしたら変えられるのかということをもう考える時期です。どうしたらいいんか尋ねました。","respondent":"濱野助役","answer":"システムになっているかということをやはり早急に検討する必要がありますし、こちら側の公務員の制度というものも緊急に検討していかなきゃいけない。そういう認識は持っております。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"これは政治の責任だと言われればそのとおりなんだけれども、現実日本でやっている政治を行うというのは半ば官僚ですかね。１０年も前からわかっている話なんだから、こういう手順でやるんじゃないか、仕組みはここが急所なんだよという話があってしかるべきだと思うんです。","respondent":"濱野助役","answer":"これは給与の決定制度とは別ですけれども、これはこれとして前提として置きつつ、そのほかのところでどうやって人件費を削減していくことができるか。認識としては先ほど申し上げたような認識を持っていますし、今申し上げたようなことがとれるのかなというふうに考えてあります。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"タイトじゃないですから、社会が変わっていることに対応できないという、雇用の場合はミスマッチが行き過ぎちゃってここまで来た。その辺はどうか尋ねました。","respondent":"濱野助役","answer":"そこのところへの認識が足りないか、あるいはそれへの対応策を怠っていたために、非常に老舗の大きな企業が倒れてしまう。日々変化のあり様というのをしっかり見ていかないと、足元からぐらついてくるということは、一応認識しています。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"品川の場合はそうじゃないと言えるけれども、それは特殊な例であると思います。今助役のお話を伺えば、僕たちもそういう世代ですから、路頭に迷わせているということが出てきているわけですから。","respondent":"古川人事課長","answer":"助役のほうからも既にご説明がありましたので、そういう中で、勧告をした。既に人事委員会のそういう勧告そのものに対して、２３区が必ずしも同意することができない様子があるということ自体、これは加えてご報告します。","id":"exchange-018"},{"speaker":"塚本委員","kind":"意見","question":"最後にしますけれども、これは勧告で、案が出て、お前たちが最終的にどう読むだろうという話も我が責任として承りましたけれども、いずれのときか、それじゃだめだという日が来るのかなと、その準備を我々もしなきゃいけないなというふうに個人的には思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと具体的に確認したいんだけれども、品川区の事業所というのは何社ぐらい入っているのか、何人ぐらい入っているのか。いわゆる労働時間についてはどういうふうに、労働時間というのは全く無視なんだということなのか、その辺ちょっと教えてくれますか。","respondent":"古川人事課長","answer":"先ほど申し上げた７２０社、区のそれぞれの職種に対応するもの、私どももちょっと今持ち得てございません。４月時点での比較という部分、それから期末・勤勉については１年間の総支給月数、私はストレートにちょっとできない処置と。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"１２時間、１３時間働かないと、その金額にならないというところも民間でいくと結構あるわけですよね。そうすると、東京都はどういうところと比較してやるわけか尋ねました。","respondent":"古川人事課長","answer":"ただ、エリアが２３区だけではなくて、都下全体に入る。家族手当、住宅手当など、こういったものは入ってございません。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"しかし、一義的には区長を初め、管理職と言ったらいいのか、いわゆる区の職員の中の指導者が決めていくべきだと思うんだよね。それで、この人事委員会の第三者的な立場というものに対して、それぞれの区としては、さっき勧告と言われたけれど、どういう関係にあるんか尋ねました。","respondent":"古川人事課長","answer":"議会の議決を経ていくという流れですが、２３区の場合はちょうど設置の人事委員会がありますので、そこが一括してやっている。勧告どおり実施する、２３区の区長がそれぞれの考え方の中で、そのことについては交渉の過程で明らかにしていく。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"あるいは今された勧告や何か、人事委員会は私の仕事はこういうものですからこうですよと言われて、要するにすれ違いになっちゃうわけですよね。その人事委員会の仕組みを２３区でどう扱っていくかというのは、直接的にかかわりを持っている課とか部で話が出るというのはあるんか尋ねました。","respondent":"古川人事課長","answer":"任命権者の実施する任用関係、このような勧告もある、こういうことです。従前どおりということに考えのある区もありますし、しかしながら、なかなかストレートなものが言える状況ではないというふうに思っております。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"意見","question":"現段階ではあるべき仕組み、それを一担当課長が要らないとか言うのは無理なんだろう、無理というよりも筋違いの話だろうと思う。やっぱり総務委員会なりでやっていってもいい話だろうというふうに思いますので、そういうようなことを委員長にお伝えをしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"もうさかのぼってというようなことが、それから、逆にはね返りとしてどうしても見られるようなことになりかねないんじゃないかな。こういうふうなことになぜならないんだろうかというふうにいつも思ってきたんだけれども、そこらあたりはどういうようなことなんか尋ねました。","respondent":"古川人事課長","answer":"これは社会一般の状況を勘案した上で、４月にさかのぼる部分と場合によっては１０月から実施とか、そういうことも過去にあります。本来の給与改定を４月の部分が民間の実態調査等々、予算等を検討していく、こういうふうに考えるというのが基本になっているというふうに思います。","id":"exchange-025"},{"speaker":"三上委員","kind":"質問","question":"そうすると、実施ということについては、先ほど来解説の、各区が独自性をもってそれは決めるということは可能なんですか、それとも２３区の人事委員会としてはそういうような形で今やっているわけですから、２３区のきちんとした統一性の考え方でいくのか。","respondent":"古川人事課長","answer":"各区はどう持つかということにつきまして、今の制度の中では、少なくとも人事委員会を共同設置する以上は、現状の中で物事を考えざるを得ない。立場上そう考えております。","id":"exchange-026"},{"speaker":"三上委員","kind":"意見","question":"〔「今年１０月昇給としてね」と呼ぶ者あり〕だから、そういうふうなことだっていいわけでしょう。〔「そのほうがわかりやすいよね」「最初に１回６カ月ずれるだけで」と呼ぶ者あり〕との意見を述べました。","respondent":"古川人事課長","answer":"それはもう既に閣議決定をされて実施するという勧告もありますし、１３年４月１日は実施日、こういう形で今回も勧告がなされております。レアケースではありますが、そういうこともあります。","id":"exchange-027"},{"speaker":"土井副委員長","kind":"質問","question":"だから、例えばこの人事委員会が給料表という、そしてこの表そのものをどうするのというところが大変大きな問題、本質的な問題だと思う。その辺を含めたものがトータルがどうなっているかということが非常に大きな動きだろうと思うんで、議会も含めて、その辺いかがか尋ねました。","respondent":"古川人事課長","answer":"過去の条例と、それが基づく人事給与制度の見直しの中で、例えばまず給料表のあり方が議論としています。研究・検討するようなことが必要という表現がありますけれども、総務課以下こういう考え方を持ってありますし、私どももそのように考えてあります。","id":"exchange-028"},{"speaker":"土井副委員長","kind":"意見","question":"社会は野球で言えば、１軍でも給与の高いのから低いのまでいて、しばらくしてＦＡ宣言をまともにできるのからできないものまでいろいろある。期待で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"そういうところを、こういうところの面とのところからの考え方というのはどういうふうにお考えになっているのかなというのをちょっと伺いたい。なんだけれども、それでいいのかなという気も反面するんですけれども、そこら辺の考え方をお伺いしたいというふうに思います。","respondent":"古川人事課長","answer":"成績主義、そういうことで先ほど申し上げましたように今の給与のあり方についても見直しが必要だろう、こういうふうに考えております。あるいは給与、この体系をどう適切なものにしていくか、これが大事であるというふうに考えております。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"１点伺いたいんですけれども、そこら辺のところをどういうふうに考えているのか、お伺いしたいというふうに思います。職員団体との話し合い等も進んできているわけですから、品川区のスタンスというんですか、考え方をお伺いしたいと思います。","respondent":"古川人事課長","answer":"２３区の統一的な事項と、その違いが徐々に明らかになってきているというふうに考えてありますが、こういうことです。これはそのときそのときの状況、本年度どうするかということについては、今はこの時点で申し上げることは得策ではないというふうに考えてあります。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"これまでのやっぱり決め方のルールというか、やり方があるわけですから、これはこれで踏まえていったほうがいいんじゃないかなというふうに思います。この点だけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"確認","question":"確認だけしたいんだけれども、この間、高層区民住宅の分と、これは別なんですか。この間高層部分の大きい三十何階建ての区民住宅部分とは別で、これは低層の部分じゃなくて、それも全部ひっくるめてというようなことなんか尋ねました。","respondent":"西島経理課長","answer":"それから地域センターも入りますけれども、それを含めて全体の、高齢者等複合施設のほうのガス施設です。","id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問","question":"クーラーとかそういう部分だけで、例えばお湯を沸かすのには、やっぱり従来どおり電気でやるんですよということなんですか。それとも高齢者住宅に関しても、いわゆるガスの炎が出るという仕組みになるんですか、その辺ちょっと説明を求めました。","respondent":"岡田施設課長","answer":"前回超高層棟の部分もそうだったんですけれども、基本的に湯沸かし、それから台所のこんろ、いろいろ検討した結果、ガスにしています。ガスいろいろ私ども検討した結果、前回の超高層のときもお話ししましたけれども、ガスのほうに踏み切ったいきさつがあります。","id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、安全性というのを最大限配慮して、電気を熱源としてこんろ類はやめたという考え方はなくして、安全であるという根拠は何なんですか。特に高齢者棟の場合に。","respondent":"岡田施設課長","answer":"あまり台所のこんろは使わないというのが実態ということもわかってまいりまして、ガスというところに落ち着いた経過があります。即大もとのところを緊急遮断弁でとめるようなシステム、こういうのをだんだんできてまいりまして、これは十分に採用しています。","id":"exchange-035"},{"speaker":"林（宏）委員","kind":"質問","question":"物を焦がしちゃうとか、そういう部分で焦がすというのは、料理をしているものを焦げつかせちゃうという意味ね。ただ、それについては十分な資料というか、安全性を確保できる資料があるんか尋ねました。","respondent":"岡田施設課長","answer":"しかしながら、ガスにつきましても、やはり同じような遮断関係が開発されてきておりまして、各区でもいろいろ超高層みたいなものをやっております。考えが及ばない部分でもありますけれども、通常の形の安全性は十分確立している、そういうふうに踏んです。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"上とか下とか横とか影響が大きいと思いますので、十分に安全については、利用する人だからね、これはつくった後は。使う人がそれを認識しておいてもらわなきゃいけないので、その辺もきちんと伝えていただきたいということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"随意契約になっていますけれども、ガスの配管工事ですね、これは同等の技術力、あるいは会社の信用度からいって、ほかにもこの仕事に対する会社はあるんだろうと思うんですけれども、その辺はどうなんか尋ねました。","respondent":"岡田施設課長","answer":"このくらいの大きさの規模になりまして、本管からの引き込みと、街のガス工事会社との契約はできないようなシステムになっております。小さな工事で、品川区でも何社か指定された工事会社がありまして小レベルならできますが、これはできないです。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"小さな修理、家庭のガス管をつくり出すようなのは、町の工事屋が実際に働きますよね。みんな自前、東京ガスが工事をするんですか、その辺はどうなんか尋ねました。","respondent":"岡田施設課長","answer":"一応東京ガスの本社がすべての技術的なものを管理しまして、中身は東京ガスのやはりそれなりのところに出しているのが実態だと思います。ガス会社が自分のところで抱えている部分と、それからとその指令下に基づいてやはり民間を活用している、こういう部分はあると思われます。","id":"exchange-039"},{"speaker":"塚本委員","kind":"意見","question":"それと、この大もとと契約するときに、その先がどういう種類になるかということは、契約書で知ることができるのかどうか、本体でやるのか、その辺は。あるいはそういうこともネグレクトして契約する習慣になっているのか、そこのところをちょっとの意見を述べました。","respondent":"西島経理課長","answer":"下請に出した場合は、下請届けというものを提出するようになっておりますので、それで私どもで確認をしていくことになろうと思います。〔「契約時に」と呼ぶ者あり〕 契約時ではなくて、契約後に、実際に契約をして、その後に実際に稼働するときという時期になろうかと思います。","id":"exchange-040"},{"speaker":"中島委員","kind":"意見","question":"さっきもちょっとわからなかった点があるんですが、基本料金の件で、電気だとどういうふうな感じ、ガスの場合は使わないときはかからない、そこのことが初めてご説明があったと思うんですが、そこら辺がちょっとわからなかったんですがとの意見を述べました。","respondent":"岡田施設課長","answer":"例えば通常一般の家庭ですと４０アンペアぐらいの契約、電気は使わなくても、これは毎月払っていかなくちゃならない。そういう意味合いで基本料金のウエートが高いか、はたまたうんと低いかと、このようなことです。","id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"それは相当な金額の違いがあるんでしょうか。品川はそういう料金の問題で決めるのであれば、安全性のほうを最優先したほうがいいのではないかなと思うんですが、かなりの差額が出るのか尋ねました。","respondent":"岡田施設課長","answer":"そういうものを検討していって、これは区民住宅も同じですけれども、このところの検討も大きなウエートという形であります。そういう意味合いでの基本料金のところも十分加味して両方比較した上でガスのほうに決めた、こういういきさつになっております。","id":"exchange-042"},{"speaker":"宮崎委員","kind":"確認","question":"１点ちょっと確認したいんですけれども、今の電気かガスかというのは、高齢者の部屋ごとに選べるとか、そういうことは可能なんか尋ねました。","respondent":"岡田施設課長","answer":"これはそこまでの自由性は、戸建ての住宅ですと、十分例えば一つの団地の中でＡというお宅は電気にする、Ｂはガス、これはあるんですけれども、複合施設で一つの建物ですので、ここまでの自由性は実はなくて、家庭用のガスこんろはガスならガス、こういう形です。","id":"exchange-043"},{"speaker":"宮崎委員","kind":"意見","question":"その一方で、安全性というものがあるので、できたら選べれば、そのほうがいいなと思ったんですけれども。難しかったらしようがないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"北野委員","kind":"質問・要望","question":"９月２６日から工事ということなんですけれども、内容を検討していたということなのかどうか、ちょっと確認させていただきたい。ガスのほうでは出ていたんですけれども、その詳細はなかったというところで、どうしてかなということをお伺いしたいんですけれども。","respondent":"西島経理課長","answer":"ちょうど２５、２６日が総務委員会が入っていたと思いますが、直近の総務委員会が今日ですので報告をさせていただいたです。","id":"exchange-045"},{"speaker":"北野委員","kind":"確認","question":"現在ガスのどういう機種のものをつけられているのかなというものを確認と、今すぐに、先ほどのお話の中にガスの機種がいっぱい出たものですから。普通のこんろなんか尋ねました。","respondent":"岡田施設課長","answer":"ですから、この工事は、湯沸かし器みたいな配管を接続しなければならないものに関しましては工事で設置します。そういう最新型のものであるならば、大体みんなどこのメーカーも安全装置みたいなものは、ほぼ標準的についているかなと考えています。","id":"exchange-046"},{"speaker":"林（宏）委員","kind":"質問","question":"何と言ったらいいのかな、わざわざこういうように書くものなんですか。要するに掘って、池をつくって、もとの公園の工事はまたお金がかかるんだろうけれども、平らに戻すというのは当たり前じゃないんか尋ねました。","respondent":"西島経理課長","answer":"次に今度は公園を整備するという工事が始まりますので、要するに現状復帰といいますか、するというのが工程に入っているです。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっと埋戻しにこだわって聞くと、その１というのはどこまで、掘ったまでなんですか。またその３というのが今度は誘導管というのかな、１と２はどういうふうに区切られているのか、説明を求めました。","respondent":"西島経理課長","answer":"その１工事ですけれども、これは土の量が約６,５００立法平米、ここまでがその１工事です。","id":"exchange-048"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、その仕事の内容については１というのと２と一緒に、工事会社というのかな、施工業者としては全然違う業種なんですか。ちょっと何で１と２が分かれないといけないのか尋ねました。","respondent":"西島経理課長","answer":"委員ご指摘のとおりでございまして、本来ですとその１、その２工事は一体の工事ですので、通常ですと、一体して発注をいたします。それから地元の方の説明等を考慮いたしまして品川区が受託したものですけれども、その関係でその１、その２工事を分割して発注したです。","id":"exchange-049"},{"speaker":"林（宏）委員","kind":"質問","question":"その３を何で品川がやらないのかなという、一般質問か何かでもどなたかが言っておりますけれども、通行どめにまたなっちゃうのかどうか。いわゆるその３工事をやるときは結構大きい管が埋められるとすると、この辺も今わかっていたら説明を求めました。","respondent":"西島経理課長","answer":"その３工事につきましては、今月中にはそろそろ発注ができるんではなかろうかというふうに聞いてあります。工事説明会を１１月１９日の説明会を予定しておるというふうに聞いておりますので、そこで細かい話をされるだろうというふうに聞いております。","id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問","question":"老朽化が著しいということでのヴィムのほうから解約したいということなんですけれども、中途解約となると、普通違約金とかそういう問題が出てくるんですけれども、そういうもののほうはどういうふうになっているのかお伺いしたいというふうに思います。","respondent":"西島経理課長","answer":"２次補修費を投入する計画はないというのが区側の考えですので、これに基づきまして、ヴィムからの申し出を了承したです。","id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、貸付料年間３００万円となっているんですけれども、それは中途で終わればその分までということになるんですか。これは解体ということなんか尋ねました。","respondent":"西島経理課長","answer":"３００万円の残りの話ですけれども、これから決めることですが、恐らくそういう形になるだろうというふうに思っております。売ったほうが有利になるかについては、どちらが可能性があるかということも含めて、これから検討してまいりたいというふうに考えてあります。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"確認","question":"建物付きで処分したほうが有利かどうかという、要するにこれは使用に耐えられないという、そういう話じゃないでしょうか。そこら辺のことは、今のお話ですと、まだ使用に耐えられるのかどうなのか、ちょっと確認したいというふうに思います。","respondent":"西島経理課長","answer":"その辺を判断しながら、その辺は要するに区にとってはどっちが有利かというところを基準にしながら進めていきたいというふうに考えてあります。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"意見","question":"３００万円掛ける何カ月ということになるんだという、今の、ヴィムとの関係もやっぱりそういうふうな立場でやるべきじゃないかなと思うんですよ。普通だったら、あと半年ぐらいだから、そこまでやるというのが普通じゃないかなと思うんですけれどもとの意見を述べました。","respondent":"西島経理課長","answer":"ただ、１０月末で営業を開始して、それをずるずる延ばしてしまうことで、区民の見る目がどうかということが一つあります。３月３１日までヴィムに貸しますと、７８万円というのは結局支払わなければいけなくなってくるという、その辺を含めて総合的に判断していくです。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問・要望","question":"教えていただきたいんですけれども、実際上、普通で考えるとかなり安い賃貸料ではないかなというふうに思うんですよね。そういうかなり応援してやってきたんですけれども、その事業としてどうだったのかというところはどうなんか尋ねました。","respondent":"西島経理課長","answer":"年４回、いろんな陶芸教室だとか、歴史散歩だとかというふうなものを実施しています。一碧荘廃止に伴った措置ですが、場所を変えて引き続き実施をするというふうに聞いてあります。","id":"exchange-055"},{"speaker":"塚本委員","kind":"意見","question":"こういうときに、大変売れない、はっきり言ってなかなか価格がかけられるかどうかということが疑問に。近傍でどのくらいの値がついているのかということと、それから解体費はどのくらい見込まれるのかとの意見を述べました。","respondent":"西島経理課長","answer":"どのぐらいで売れるかというのは、なかなか難しい。最近であの近辺では取り引き例はあまりないというふうに聞いておりますので、ちょっとこれからいろいろ努力をしていきたいなというふうに。","id":"exchange-056"},{"speaker":"林（宏）委員","kind":"質問","question":"その辺の検討の結果はもう出ているということなんですか、ここの土地を処分するという、そういう決定はされているんか尋ねました。","respondent":"西島経理課長","answer":"旧一碧荘については廃止処分という決定をしています。","id":"exchange-057"},{"speaker":"林（宏）委員","kind":"質問","question":"それから取得の金額だとかもろもろ考えていくと、幾らなら売るとか、幾らなら処分するんだというようなところまで相談はされているんですか。ただ単に処分と決めただけなんですか、それではいかにも僕は無責任過ぎると思うんだな。","respondent":"西島経理課長","answer":"決定するに当たりましては、一つはこの改修ということも検討いたしました。私どもで内部で調査をしてまいりまして、その数字を含めて検討をした結果、廃止決定という結論を出したものです。","id":"exchange-058"},{"speaker":"林（宏）委員","kind":"質問","question":"もっと前からあの土地をどうするかということは、菅家委員が一般質問で松崎のことや何かを含めてお聞きしていますけれども、そういうことなんですよ。ここをお返ししますと言ってきた時点でどうしようか、僕は行き当たりばったりだと思うけれども、いかがか尋ねました。","respondent":"中尾根企画部長","answer":"実はこの９ページですか、区が持っている保養施設およびこういう厚生施設については、長い間結局いろいろ検討してきた経過があります。あわせてやはり区の施設としての検討の素材に、この経過から言いますと、もう昭和６２年の時点のところです。","id":"exchange-059"},{"speaker":"林（宏）委員","kind":"質問","question":"選択肢はないんですかということを聞いているわけで、だから、幾つかのそういうようなものもあるんじゃないですかという。検討を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"これも企画部長ですか、まさしく７万だ、１５万だということの行政レベルでの有効性というようなものを肌で感じました。行政レベルのメッセージのほかに、それにかかわった民間のシンクタンクの室長の松田さんの話を伺えて、大変参考になりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"林（宏）委員","kind":"意見","question":"３行から５行ぐらいに、ああそうかというような指摘がされているんですよね。理解だとか、ちょっと１５０万人近い都市だと小回りがきかないのかなということで、品川の３０万人強の人口をいいなというのを改めて感じましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問・要望","question":"１点は、仕組みをもちろん検討していく中で、逆に効率性を求めたハードのあり方も将来的には検討しなきゃいけないのかなというのを感じました。見やすさから言うと、１ページ目のこの表に出ていたのは、一方では品川区としては参考にしていくべきではないかなというようなことを感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"三上委員","kind":"質問・要望","question":"佐賀市の近くに三カ月町というんでしょうか、人数が３０何人、こういうようなことがあれば。どちらがどうなのかということで、そういう中から区長部局のほうに要望をしていく中から改善が図られたというやり方にあって、やり方。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"中島委員","kind":"質問","question":"町の中の唐津くんちですか、何か品川区に取り入れられるものはないのかなという、そんな思いで帰ってきたわけなんですね。それから、福岡市なんですが、初めにこの自治体のＤＮＡ革命というんですか、これは私は非常に興味を持って聞いてまいりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"宮崎委員","kind":"質問","question":"こういう状況なものですから、私も担当課長に財政状況のほうはどうなんでしょうかと聞いたら、そんなのもちょっと感じたんですよね。本、自治体でＤＮＡ革命の本はまだちょっと私も途中でなものですから、こっちのほうはまだ意見が言えないというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"北野委員","kind":"意見","question":"そういう部分ではいろんなところで市民への情報公開も含めて、品川区もこれから検討するべき、学ぶべきことがあるんではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"土井副委員長","kind":"質問","question":"福岡市ですから、政令指定都市ですから、その方向で進んだ。区内全域というデスクがあるんだということになるわけですから、それも可能なんではないかなと思って帰ってきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"林（宏）委員","kind":"質問","question":"１点だけいいですか。ごみのカレンダーもありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/517525?Template=document&Id=1562#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":65537,"voices":164}},{"id":"h13-20011106-6","meetingId":"h13-cm11","date":"2001年11月6日","dateIso":"2001-11-06","committee":"区民委員会","time":"午後１時０２分～午後２時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"私のほうから、紹介議員に私と、石田副委員長がなっておりますので、お願いかたがたお話をさせてほしいと求めました。ぜひ一定継続をしてほしいという強い要望があるですので、ぜひ採択していただきたいと、お願いいたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"本田委員","kind":"質問・要望","question":"減額２分の１ですから、それは推測できますけれども、そういうことがよくわからないんです。これは目的税ですから、それはどういうふうに、そもそも税金がどういうふうに使われているのか。","respondent":"松崎税務課長、小栗区民生活事業部長","answer":"私どもの税目ではないので正確にお答えできないところもありますが、地方税の体系からいきますと、基本的には市町村税に位置づけられてあります。申し訳ございませんが、都市計画税が東京都にいって… 補助１８号線、補助３２０号線、区の都市計画交付金として歳入になってあります。それに見合うような形で歳出のほうで組まれているというような内容です。","id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"こういう請願は、本来、区が直接でないから、実態もなかなかつかめない。都に意見を出してくれということでありますけれども、請願紹介人もいらっしゃるんですが、これは都にもこういう請願というのは出ているわけか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"原委員","kind":"意見","question":"今どこのというのはわかりませんけれども、話によると、そこからまた話がいっているというふうなことを聞いております。ここの団体、直接は多分東京都である青色申告会連盟のほうからいっているのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"本田委員","kind":"意見","question":"どうも全体的には、国の減税を渋っている態度があるというようなことでもあるのかどうなのか。その辺は何か情報は入っていますかとの意見を述べました。","respondent":"松崎税務課長","answer":"平成９年ぐらいから継続して、その後の取り扱いにつきましては、都議会の各会派で反対しているところは今まではなかった。今回もおそらくないだろうというふうには聞いてあります。","id":"exchange-005"},{"speaker":"堺委員","kind":"意見","question":"景気回復に与える影響が危惧されます」、なおかつその下にもそのようなことが書いてありますが、私も全く同感です。そういう意味では、本田委員がおっしゃるように全会一致で採択していきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"金高委員","kind":"提案","question":"私は、結論から言って、これは提案に賛成するということを表明します。東京都の中において厳しい状態で生活をしている方々ですから、これが２分の１がなくなると、もっと厳しい生活を余儀なくされるということですからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"今の時代の中で税の軽減というのは何としても必要になっていると思います。私どもの会派でもこの請願については採択してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"購入負担金利ですか、0.５％というのは、これ自体も区で利子補給をしていくという形というのは考えられないものか尋ねました。","respondent":"市川産業振興課長","answer":"ただ、私どもは0.５％というのは、世間相場で言ってもかなりの低金利だという認識があります。融資のあっ斡をしている資金が事業資金であるということを考えますと、私は0.５％という金利が、今のところそういう認識を持ってあります。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問・要望","question":"据え置き期間が１年ということで、この１年間の間にお客さんが戻ってくれば、１年ぐらいでお客さんが戻るような形というのはできるかどうか。そのあたりをお聞かせほしいと求めました。","respondent":"市川産業振興課長","answer":"これに対して、事業者側もただ黙っているだけでなくて、懸命のいろいろな努力をなさっていることは私どもも聞いてあります。特に年末の厳しい状況の中で、第一弾としてこういう手を打ったわけでございまして、引き続き経過を見ていきたいというふうに考えてあります。","id":"exchange-010"},{"speaker":"原委員","kind":"提案","question":"ちゃんとした形で見ていたかどうかという印象がないんですけれども、ここの中でいろいろな意味で、提案していかなければいけないのなと考えています。数年のところで結構ですとの意見を述べました。","respondent":"市川産業振興課長","answer":"ここ４年ばかり実施してきてありますけれども、その前の年が２０億円、さらに１年前が４０億円出てあります。ただ全体としては実績がしぼみつつあるという傾向にあろうかと思います。","id":"exchange-011"},{"speaker":"原委員","kind":"意見","question":"そうすると、やはりこの辺の枠を広げ方というものは、その辺のところはどうお考えになっているのか。例えばそれも含めて４０億円になる可能性もあるのかどうかということの意見を述べました。","respondent":"市川産業振興課長","answer":"４０億円に伸びたときもそうでございましたけれども、その枠以上には受け付けませんという、そういう対応はとりません。特段の配慮をお願いしたいということで、私自身伺って、先方の所長に要請をしてまいりました。","id":"exchange-012"},{"speaker":"原委員","kind":"意見","question":"今のお話のとおり、ひとつお願いをしたいなと思います。３６件が６０件になっていて、そういう意味では、それだけ対応をうまくやれますようにお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"堺委員","kind":"提案","question":"確認をしたいんですが、１１月１日から始めて正味３日間で相談件数が９７件でしたね。最終的にそのうち狂牛病関連の対象になったのは１１件ということか尋ねました。","respondent":"市川産業振興課長","answer":"１３件のうち１１件は即日に紹介状を発行して、２件が持ち越しになって、そういう理由で持ち越しになったです。全体の相談件数の９７件に対して１０％強というような割合です。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問","question":"ですから、相談にお見えになったのが１３件ですから、数的には少ないですね。３日間だから、これから増えてくるかどうかわかりませんが、その辺のつかんでおられる感触はどうなんか尋ねました。","respondent":"市川産業振興課長","answer":"国や東京都の対応策も遅れぎみなんですが、いずれにしても、こういう状況に今あるのかなというふうに見てあります。この１週間、２週間の状況を見ないと、全体の動向についてはつかめないかなというふうに見てあります。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"今回のそういうのと関連して、経営相談といいますか、そういうところまで踏み込んだ形でのご相談もあるんですか。ちょうどいい機会だから、この際、自分のところの経営全般についても相談に乗ってもらおうという形でお見えになる方もいらっしゃるんか尋ねました。","respondent":"市川産業振興課長","answer":"その後のフォローもできるようにということで考えてはおりますが、待てないとおっしゃる方もいるんですが、一応体制としてはそういう体制を敷いてあります。","id":"exchange-016"},{"speaker":"石田副委員長","kind":"質問・要望","question":"そういうものをお考えに、考え直すというような方法をお考えになったことがあるのかどうか、そこら辺だけ聞きたいというのが１点。現実こうやってあるんだなどと今思ったんですけれども、そういうのが幾つぐらいあるのか、もし分かれば教えてほしいと求めました。","respondent":"市川産業振興課長","answer":"これは区の融資の制度が幾ら変わっても、この大枠の信用保証の制度というのが変わらないとなかなか難しい。これについては注意深くそういった制度の変遷を見ながら検討をしていきたいというふうに考えております。","id":"exchange-017"},{"speaker":"石田副委員長","kind":"質問・要望","question":"要望だけしておきますけれども、銀行でも、プロパー融資は本当にしなくなってきて困っているという業者が多い。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"本田委員","kind":"質問","question":"今のご説明だと、そういう飛ばし方をした場合に、八潮団地の上空にかかってくるんか尋ねました。","respondent":"金井環境課長","answer":"現在も年間で二十数便飛んでいるそうですが、八潮上空には基本的に飛ばしていないです。ただ、風具合によっては、多少寄ったりする可能性はあるかもしれないけれども、基本的には八潮団地の上空は飛ばないということを聞いております。","id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"今の課長の説明でわからなかったところで、２で、有視界飛行による運航を前提としたノースバード運航を希望する会社は皆無だったと。３番の(1)にある、公用機だったら使うという、その違いがよくわからないんですとの意見を述べました。","respondent":"金井環境課長","answer":"前にもちょっとご説明したかと思いますが、視程が８kmでないと降りられない、非常に難しいと。そういう意味では、採算といいますか、商売的なことも含めてということだと思います。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"2)、3)と書いてあるんだけれども、その部分をどう解釈していいのか。現状も環境基準を上回っていて、なおかつここで工事を始めて、こういう形にすると、またそれも上回りますよということなんか尋ねました。","respondent":"金井環境課長","answer":"東京都は来年の５月からディーゼル車の規制も始まったり、ＮＯXは来年の５月から厳しくなりまして、規制が始まります。車が走行するけれども、それを低減させますということはなかなか難しいということで、そういうことでご理解をいただければと思います。","id":"exchange-021"},{"speaker":"本田委員","kind":"質問・要望","question":"そういう場所ですから、確かに原委員がおっしゃっているように、そういう場所なんだと。どっちから出ようと大気汚染は大気汚染のはずですから、それは東京二十三区清掃一部事務組合のほうに、１部ほしいと求めましたけれども。","respondent":"金井環境課長","answer":"そういったことをきちっと説明して、こういう場で私どもが説明するというのもあれなんですが、１０年になったら大気環境は非常によくなりますよと。追いかけて法律も厳しくなってまいりますので、地域住民の方に説明をしながら、こういう政策を区はやっています。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問・要望","question":"そこに八潮団地という大きな団地があるわけですから、その辺総合的に配慮した環境改善というものが求められているわけですから、単発。ぜひそこら辺は配慮して、総合的に環境改善をやっていくようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"原委員","kind":"意見","question":"報告書の中身の中に文章だけでなくて、写真の掲載等はどうかということです。写真いいですよということか、あるいは個人で写真を入れてほしいということがあれば、入れられますよとかというのはとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/217714?Template=document&Id=2310#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":24496,"voices":72}},{"id":"h13-20011106-7","meetingId":"h13-cm11","date":"2001年11月6日","dateIso":"2001-11-06","committee":"厚生委員会","time":"午後１時５分～午後２時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"公募委員がもっと増えてほしいと思っていますけれども、どういったことが検討された上で３名になったのでしょうか。例えば４名であるとか、地域に密着して健康づくりができるというが目的にもなっているわけですから、どうして３名だけになってしまったのか尋ねました。","respondent":"田中健康課長","answer":"３名だけという形ですが、３名もというのも私どもの気持ちでございまして、なかなか難しゅうあります。今、最終的にできる限り入っていただきたい団体のほかは、公募の形でお願いをしたいということで３名になったという結果です。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"どういう構成になっているのか、今の話じゃないけれども公募のほうで少し整理をしてあげたりとかというようなことがあると思うんですけれども。それから、医療関係で、前から我々は柔道整復師もどうだというようなお話をしたんだけれども、その辺のところはいかがなものか尋ねました。","respondent":"田中健康課長","answer":"今回、企業という形で検討させていただきましたが、そこのところまで具体的な団体というところまでは至らなかったというのが現実です。いろいろご意見をいただく機会があろうかと思いますが、当面区民会議のメンバーの中では、このような設定でさせていただきたいという内容です。","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問","question":"医療関係団体が６名ということで、地区医師会・歯科医師会、薬剤師会というと、品川、荏原と分けて今までずっと来ているんですね。ですから、この委員会から話が出て、それではということができるのかどうか説明を求めました。","respondent":"田中健康課長","answer":"実は、従来の保健所運営協議会等がある程度網羅的にお願いしていたせいがございまして、そこに引きずられた面は確かにあります。委員ご指摘のような考え方は当然していくべきだろうとは思っておりますし、今回はこれでお願いをさせていただきたいというふうに考えてあります。","id":"exchange-003"},{"speaker":"須藤委員","kind":"質問・要望","question":"あるいは政策要望についても区長側に出して、若干我々が予想した絵と違ってきているので、今のようなお話をさせていただきました。内容的については、我々も会派としていろいろ要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"プラン２１の策定ができた後、例えば普通でしたら品川区が事務局をやって、品川区との係わり方がどういうふうになっていくのかということが一つ。それから、それを品川区がどういうふうに展開していくかということの、今のところの見通しを教えていただければありがたいんですが。","respondent":"田中健康課長","answer":"それから、ここがまさしく私どもが一番プラン２１に対して皆さんにご検討いただく中身と思ってあります。効率的・一体的な実施に向けて体系化・重点化を図る、体系的な見直しの一つの形の流れにできていければなというふうに考えてあります。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"障害をお持ちの方も区民なわけですから、考え方も変えていかなきゃいけないんじゃないでしょうかという思いがありますので、将来的なことも含めて答弁をいただければありがたいんですが。","respondent":"田中健康課長","answer":"先ほどもご答弁申し上げましたが、今回企業のご意見を何らかの形で反映したいということもございまして検討はしてまいりました。それから、別の何らかの形でご意見をいただいて、連携ができるような形の設定はしていきたいというふうに考えているところです。","id":"exchange-006"},{"speaker":"鶴副委員長","kind":"質問","question":"委員の構成を見ますと、それぞれのセクションごとに推薦をしてくださいということになるわけでしょうか、推薦区分というふうにありますけれども、委員の指名は公募以外はどうなるんか尋ねました。","respondent":"田中健康課長","answer":"この推薦区分のほうへ推薦をお願いいたします。ある程度設定をした上でお願いをするということで、ご本人の内諾もいただいておきながら、団体には推薦をお願いしています。","id":"exchange-007"},{"speaker":"鶴副委員長","kind":"質問","question":"いいじゃないですか」と、集約大成されていくものなのかどうか、第５回を迎えるようになっております。プラン２１を策定して公表するという段取りですけれども、そして提示して論議をしてもらうんですか、どういうことなんか尋ねました。","respondent":"田中健康課長","answer":"このベースは、やはり私どもが現在まで進めてきております保健衛生行政といいますか、私どももとらえ直そうという作業にかかってあります。","id":"exchange-008"},{"speaker":"鶴副委員長","kind":"質問","question":"ということは、要するに行政主導型の品川健康づくりプラン２１ということになるのか、今の話を聞くと、どうもそのように聞こえるわけです。どうも課長の答弁によると、それでお話をされて、どちらに重きを置いた品川健康づくりプラン２１ということになるわけか尋ねました。","respondent":"田中健康課長","answer":"ただ、それが今申し上げたようなお話といいますか、これからの進め方になるのではなかろうかというふうに思ってあります。その中で進めていきたいと思ってあります。","id":"exchange-009"},{"speaker":"鶴副委員長","kind":"質問","question":"今回は全く議会サイドの委員というのはないわけですから、議会の議員を気にすることのない論議が展開されるのかなというふうには期待はしております。そしてそれが「品川健康づくりプラン２１」という形でまとめられていくのかどうかという、そこのあたりが気になる点なんです。","respondent":"田中健康課長","answer":"ただ、体系づけていこうですので、そういう意味でご意見をいただいて進めさせていただきたいというふうに思ってあります。ただ、整理をして皆さんにご参加をいただいて立ち上げていこうかなというふうに考えているところです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いきいき２１ですか、ボランティアというのが今回入っていないんじゃないかと思うんですけれども、そこのところがどうなっているのか教えてください。ボランティアの登録というのは、実際何人ぐらいになっているのかも合わせて教えてほしいと求めました。","respondent":"田中健康課長","answer":"それから、そういう皆さんにもっとご協力をしっかりいただけるようなシステムを考えていきたいというふうに思っているところです。まだ何十名という段階ですので、これから先、いろんな形で参加いただけるように考えていきたいというふうに思ってあります。","id":"exchange-011"},{"speaker":"船波委員","kind":"質問","question":"それによって効果もどうなのかなと思うんですが、これから流行すると思われる型に対して予防接種をするという型は合っているということがわかっているんでしょうか、予防接種の効果についてお伺いしたいんです。","respondent":"小林品川区保健所保健サービス課長","answer":"ですから、ここ何年もの間は、大体一致しているという現状ですので、ウイルスと予防接種のタイプは合っている。集団の防止効果は確かに接種率が８０％以上超えないと効果が薄いと言われておりますけれども、そのような考えに基づいております。","id":"exchange-012"},{"speaker":"船波委員","kind":"質問","question":"この説明によりますと、希望する個人がはがきによって申込むということになっていますが、高齢者の施設に入っているような方はどうなるんでしょうか。そういった施設に入っている方はどういうふうに希望を取るとか、あるいは集団で接種するとか、その辺はどうなんか尋ねました。","respondent":"田中健康課長","answer":"高齢者の施設に関しましては、今までも個別に施設で対応いただいております。今回も同じ立場でご利用いただけるものというふうに考えてあります。","id":"exchange-013"},{"speaker":"船波委員","kind":"質問","question":"個別にということは、施設ごとということですか、それとも施設に入っている個人個人ということなんか尋ねました。","respondent":"新美保健高齢事業部長","answer":"それぞれの施設ごとに対応をやっているところですので、そういったことを踏まえつつ、施設との連携調整をしていくという考え方でおります。","id":"exchange-014"},{"speaker":"船波委員","kind":"質問","question":"施設ごとに決めるということですけれども、今までは施設の場合、大体接種をしていただくということなんでしょうか。それから、区の負担が２,３００円ということですが、この財源はどうなるんか尋ねました。","respondent":"田中健康課長","answer":"これが各自治体も悩み中の悩みでございまして、今回につきましては国のほうは何の財政的手当てもしてこなかったという状況です。これは各自治体とも大変な思いで持ってきまして、自己負担の考え方につきましても大変な議論をしてきたところです。","id":"exchange-015"},{"speaker":"船波委員","kind":"質問","question":"この法律が１０月３１日に成立したということですが、今後は毎年この法律に基づいて、同じように行われていくということか尋ねました。","respondent":"田中健康課長","answer":"ですから、来年以降も同じような形で、予防接種について対応する必要があろうかというふうに考えてあります。ただ、先ほども申し上げましたとおり、財源措置が全くないですので、どう推移するかは非常に難しい部分も残っているところです。","id":"exchange-016"},{"speaker":"船波委員","kind":"質問","question":"そういった幾つかの要素を考えて、一人ひとりの方が受けようかどうしようか決めるんだと思いますけれども、そういうことをどのように広報するのか。区としては、なるべくやったほうがいいというようなスタンスなのかどうか伺いたいと思います。","respondent":"小林品川区保健所保健サービス課長","answer":"国のほうから啓発用のガイドラインが早急に示される予定ですので、その上で主治医と相談していただいて接種をするという形になろうかと思います。","id":"exchange-017"},{"speaker":"嶋委員","kind":"質問","question":"今の時代にはがきというより、電話とかファックスとかというのはお考えにならなかったのか、まずお聞きをしたい。だんだん近くに医者がなくなっていくということがあるんですけれども、どのぐらいの協力医療機関に協力をいただけるのかお聞きをしたいと思います。","respondent":"田中健康課長","answer":"今、その中の３０％ぐらい現在お受けいただけるかなというふうに見込んで、一応考えているところです。ここはこういう診査がうけられますというのは、一覧表で住所・電話番号で載せているところですので、同じ方式になるかなというふうに考えてあります。","id":"exchange-018"},{"speaker":"鶴副委員長","kind":"質問","question":"ようやく成立したけれども、国は財源措置をちゃんと考えるべきだという論調を高めていかなければいけないというふうに思っているんです。やっぱり１回じゃだめなんだと、２回必要なんだというふうに言われているじゃないですか、そこあたりはどうなんか尋ねました。","respondent":"小林品川区保健所保健サービス課長","answer":"それは、やはりそのような研究の結果に基づくものでございまして、１回と２回とでは特に差がなかったという結果に基づいたものです。ただ、どうしても２回希望される場合は、任意で接種していただくという形になります。","id":"exchange-019"},{"speaker":"鶴副委員長","kind":"質問","question":"後で、統一的にここで４,５００円で本当にやってくれるのかどうかという問題も、自己負担が２,２００円で区負担が２,３００円。気になっていたのは、乳幼児医療費の範疇に含まれていることなのかどうなのかと、そこのあたりはどうなんか尋ねました。","respondent":"田中健康課長","answer":"三者協という形で決めたのが４,５００円という単価でございまして、また別途の考え方もありますし、というところで動いているところです。今回のものは高齢者のインフルエンザです。","id":"exchange-020"},{"speaker":"鶴副委員長","kind":"質問","question":"だから、含まれていないのですか、除外されているのですかということを聞いただけのことなんですよ。その中に含まれているか含まれていないかということを、僕はちゃんとほかのところで聞いてこなかったものだから、今聞いているわけです。","respondent":"日下部障害者福祉課長","answer":"基本的には自由診療ですので、助成の対象には入らないのではないかと理解をしております。改めて、その辺の事実関係については、再確認をさせていただきたいというふうに思います。","id":"exchange-021"},{"speaker":"鶴副委員長","kind":"確認","question":"乳幼児医療費助成には所得制限がありますけれども、その対象に含まれているのですか、含まれていないのですかということをただ聞いただけなんですよ。おそらく含まれていないというふうに思っているんですが、それを確認しないと次のことにいけないから、それで念のために聞いたんですよ。","respondent":"日下部障害者福祉課長","answer":"基本的には、乳幼児医療費助成制度の対象外と、副委員長のご指摘のとおりだというふうに受け止めております。","id":"exchange-022"},{"speaker":"鶴副委員長","kind":"提案","question":"新しく考えてみたらどうかと、こういうふうに思ったので、確認の意味で聞いたんです。高いでしょう、普通どのぐらいですか教えてほしいんですが、三者協で４,５００円、通常予防接種する場合、どのぐらいになっていますかとの意見を述べました。","respondent":"小林品川区保健所保健サービス課長","answer":"はっきりとしたことは申し上げられないんですけれども、情報として区民の方からいろいろ聞いているところによりますと、安いところで２,０００円、高いところで１万円というような幅があります。","id":"exchange-023"},{"speaker":"鶴副委員長","kind":"質問","question":"専門の先生に聞いておきたいんですけれども、予防接種のインフルエンザが医療機関によってどうしてそんなに差が出てくるんですか。Ａというところに行ったら２,０００円、Ｂというところに行ったら１万円、効き目の中身が違うんか尋ねました。","respondent":"青山品川区保健センター所長","answer":"ワクチンそのものに差があるということはほとんど考えなくていいかと思います。資質等のことや設備そのほか、それから何か起こったときの対応とか、そのために非常な幅が出てきてしまっているというのが現状であろうかと思います。","id":"exchange-024"},{"speaker":"嶋委員","kind":"質問・要望","question":"ですから、打つなら今が一番いいという朝のニュースでした。これだと１１月２１日号の予定で、なるべく早い時期に予防接種の実施ができるようにご配慮ほしいと求めました。","respondent":"田中健康課長","answer":"広報ですが、医療期間からいろいろご連絡をいただいて、もう今回のやつにはまらないんですかという問い合わせが随分来ているそうです。私どもとのご説明と連動してやらせていただいておりますし、今、できる限り何らかの方法を考えてみたいというふうに考えております。","id":"exchange-025"},{"speaker":"須藤委員","kind":"意見","question":"１点だけ、むしろ先ほど言われているように、こういう法律ができて変わりはないのかというようなことをお尋ねしたいと思います。そこについてやはり公的に２,３００円を負担して、医師をそこに派遣をして接種を進めていくというような対応を取るのかどうかとの意見を述べました。","respondent":"新美保健高齢事業部長","answer":"基本的には、予防接種対応を各施設でやっているというふうにいろいろなところで聞いておりましたけれども、改めて区内の全施設確認をし予防接種は徹底するように、集団生活ということがありますので、その辺は今回していきたいというふうに思っております。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"これと同じ状況になってくるわけですよね、区の負担が２,３００円、自己負担が２,２００円だよと。施設ではどういう形になっていたか、いわゆる保険外の自由診療の形ですから、その辺のところはいかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"これまでは区内の各施設は施設の処遇上の対応として、基本的には可能な人には全員予防接種対応をしてきているというふうに聞いております。","id":"exchange-027"},{"speaker":"船波委員","kind":"質問","question":"入居登録者４０名程度を募集するというのは、４０名に設定したのは、１年間の間に登録していれば入れるのではないかという予測に基づいて、大体はこのぐらいということになっているのか尋ねました。","respondent":"野田口高齢事業課長","answer":"平均すると大体２０名程度が何らかの形で高齢者住宅から退去していくと、そのほかは今回のように新規施設の部分もあるということ。それから、そういった意味で幅を見て通常３０名から４０名ですけれども、４０名の登録ということで考えているものです。","id":"exchange-028"},{"speaker":"船波委員","kind":"質問","question":"そうすると、はじめから４０名を登録するけれども、決められて１年間の間に入れなくて残ってしまう人というのは既に折り込み済みなんでしょうか。そういった場合、残ってしまった方は指定されている期間の後はどうなるんか尋ねました。","respondent":"野田口高齢事業課長","answer":"それから、来年度の場合、先ほど宮川ハウスが７戸の新規住宅ということをまず想定しているということ。すべて区のほうで対応したということではございませんけれども、自力での解決も含めて、そういった意味では解決が進んでいるです。","id":"exchange-029"},{"speaker":"嶋委員","kind":"質問・要望","question":"毎年ひとり暮らしの方は、１２月しか申込みができないというのが多いと思うんですが、昨年もたくさん見えていたと思うんですが、昨年の見えた方の人数を教えてほしいと求めました。","respondent":"野田口高齢事業課長","answer":"途中で取り下げた人が１２名ということで、入居要件の該当者が１９８名です。これは幅広く取った場合、そういったことです。","id":"exchange-030"},{"speaker":"嶋委員","kind":"質問・要望","question":"これは登録制ということなんですが、１回登録をすると何年間保証というのか、１回申込めば何年間大丈夫だというお話を聞く方もあるとか情報的なものが違うので、教えてほしいと求めました。","respondent":"野田口高齢事業課長","answer":"例えば今の時点でまだ入居できない１３年度の登録者の場合には、ご案内を申し上げているところです。そういった意味では、１年間です。","id":"exchange-031"},{"speaker":"嶋委員","kind":"質問","question":"何年間通用するということを聞いたことがあったものですから、１年１年切りかえだと、１年にかけるしかないのかなと思っています。やはり自力でも大変厳しい方もいらっしゃるんですが、１２月に入れなかったらほかに何か区のほうであっせんというのがあるんか尋ねました。","respondent":"野田口高齢事業課長","answer":"同時に、両方とも申請していただきまして、どちらかで解決していく。有料老人ホームとか私どもの持っている情報を、一人ひとりに合った解決につなげていくという方法で取り組んでいきたいと考えています。","id":"exchange-032"},{"speaker":"嶋委員","kind":"質問","question":"では、きちっとフォローをしていただいているということで、よろしいんか尋ねました。","respondent":"野田口高齢事業課長","answer":"登録なさっても、「まだですか」というような問い合わせは定期的にありますので、そういった時点できちっとフォローしていきたいというふうに思ってあります。","id":"exchange-033"},{"speaker":"鶴副委員長","kind":"質問","question":"そういう施設はどういう施設であったというか、それで十分じゃないですか。見てきたことを書けばいいんじゃないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鶴副委員長","kind":"質問","question":"できれば、定例会が始まるまでにということでいいじゃないですか、あれはいつ招集でしたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"須藤委員","kind":"意見","question":"それをまた提示するとなったんですけれども、出したものを見ていただいて、正副委員長で決めてもらったほうが早いと思うんです。長ければカットするなり、きちんと合わせていただいたやつを持っていったほうが、また戻ったああだこうだというと時間がかかっちゃうでしょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"鶴副委員長","kind":"質問","question":"現実的には提出されたものをそのまま、あるいは原稿用紙で４００字詰めで書く人も、全部そのままというやつでいいんじゃないですか。長いからといって切るわけにいきませんし、皆さんが出していただいたやつを清書して、それをまとめるということにしたほうがいいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"まとめるのは正副委員長、そして、またこっちに戻してというと大変じゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鶴副委員長","kind":"質問","question":"資料もあることだし、主だったところを、一番印象に残ったところをお書きいただければいいんじゃないですか。まとめるときにはＡ４の用紙で、原稿用紙でも構いませんけれども、原稿用紙でもできればＡ４の原稿用紙みたいな形でお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/723274?Template=document&Id=3002#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":25913,"voices":104}},{"id":"h13-20011106-9","meetingId":"h13-cm11","date":"2001年11月6日","dateIso":"2001-11-06","committee":"文教委員会","time":"午後１時５分～午後３時５８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"川西委員","kind":"質問","question":"３０人とか４０人の受入れに対してというようなことをおっしゃったんだけど、本来、これだけの子どもが来ると見てよろしいのかどうか。ちょっと見方を説明するよう求めました。","respondent":"久保田学務課長","answer":"４０人を基本に考えておりますけども、あらかじめ、ここだけ受入れ枠を３０人としているです。４１人ということで、１人上回っているわけですけれども、そのまま受け入れるという考え方です。","id":"exchange-001"},{"speaker":"川西委員","kind":"意見","question":"この数字を当てはめて、来年度の新１年生はどのぐらいの学級になるかということを判断して、想定しないとわからないですね。そういうことですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"今度はマイナス６１人というふうに幾つか特徴があるわけですけど、学校ごとの分析というんでしょうか、教えていただきたいというのが一つ。二つ目には、その定着の要因というんですか、大きく定着をした要因というのをどういうふうに考えているのか。","respondent":"久保田学務課長","answer":"定着という意味合いですけども、申請者の数が伸びているということは、やはりこの制度がよく活用されていることの反映ではないかと考えています。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問・要望","question":"それなりの背景があるわけですから、それに対してやっぱりどういうふうに指導的援助というのを、この１年間なりにされているのか。だけど、学校だけでなくて、そういう制度も設けた教育委員会ですから、それについてのコメントが私はあると思うんですけど、その辺はどうなんか尋ねました。","respondent":"久保田学務課長","answer":"それこそ１年がかりで、検討をして、ここまで取り組んできたというところはある程度あります。やはり１年とか、やはりもう少し長い目で見ることも必要ではないかということを、率直に感じているところです。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問・要望","question":"それっていうのは、どういう形で評価していくのか、どういう形でやっていくのかなんていうことは、全然、委員会の中で報告がないじゃないですか。ちょっと委員長にお願いしたいのは、次回でもいいですから、きちっと説明をいただきたいということをお願いします。","respondent":"青木指導課長","answer":"学校の評価について検討しているということにつきましては、本会議でも、このような形で答弁しています。ただ、内容につきましては、今、検討中であるということで、私どもも進めているところであります。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"決まってから、来年度報告しますというのでは、やっぱり、これを見たお母さんから質問されたんですよ、きのう。次回にでも、今の段階でもいいですから、ぜひ報告をほしいと求めました。","respondent":"青木指導課長","answer":"こちらのほうから抗議をしたわけなんですけど、まだ検討中の内容です。残念ながら、私どもは大変この記事内容については、内容的にも問題があるということで抗議をしています。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問","question":"内部では気がつかない点を指摘してもらい、改革に結びつけたい」となっているんですよ。教育長は抗議しなかったんか尋ねました。","respondent":"若月教育長","answer":"内部の評価も合わせて、いい学校にしていこうという検討をしている、このことは事実です。先ほどの課長の話じゃありませんけども、これからどういう評価のあり方がいいかを検討してもらっている最中ですよ」と、そう言ったんです。","id":"exchange-007"},{"speaker":"桜井委員","kind":"質問","question":"教育長のコメントも載っている。それで、抗議したんか尋ねました。","respondent":"若月教育長","answer":"今やっていることとか、自分の夢なんかを語っちゃうことが、場合によってはあるのかもしれませんね。こういう形になったということは、ほんとうに他意のないことであるということで、ひとつご理解をいただきたいと思います。","id":"exchange-008"},{"speaker":"山路委員","kind":"質問","question":"要するに、生徒の数が一番多い学校、一番少ない学校は、平均的にはどのぐらいの生徒数を受け入れるのか。差し支えなかったら、学校名か、数か、できたら数で説明を求めました。","respondent":"久保田学務課長","answer":"一番多い学校は鈴ケ森中学校でございまして、〔「一番右を見てくれと言えばいい」と呼ぶ者あり〕１５９人です。荏原第四中学校、荏原第六中学校、平塚中学校という状況です。","id":"exchange-009"},{"speaker":"山路委員","kind":"質問","question":"本年度の対象児を考えていましたので、昨年度じゃなかったんですけど、昨年度に沿って、ご説明していただいたんですが、大体、本年度も同じ傾向の入学者数だと考えていいんか尋ねました。","respondent":"久保田学務課長","answer":"登録数を見ていただけるとわかると思うんですけども、昨年より、今年は１７０人ほど少うあります。したがいまして、入学者数も、それに準じて、１５０人ぐらいは少なくなるんじゃないかとは思っております。","id":"exchange-010"},{"speaker":"山路委員","kind":"質問","question":"先ほどの４日付の毎日新聞の評価制導入ということを読みましたら、品川区はこういうふうになっていくのかと、まず感じるんです。影響を心配するんですが、その辺については、どのようにお考えか尋ねました。","respondent":"指田教育次長","answer":"一番考えていますのは、その点で、ご理解いただければと思ってあります。いずれにしましても、今回の新聞報道は、今のところ、これには直接影響はないと考えています。","id":"exchange-011"},{"speaker":"山路委員","kind":"質問・要望","question":"私も３チャンネルで何回か見たんですけど、定着しつつあるかなと感じているのは、そこにあるわけなんです。こういう問題が出てきますと、そういうことに右往左往しないように、しっかり管理をしていただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"この住民基本台帳による予定数ですけども、たしか、小学校は増えているような話を聞いたんですけども、この先二、三年、推測的には、中学校の基本台帳の予定数というのはどうなっていくんか尋ねました。","respondent":"久保田学務課長","answer":"その後、平成１５年度に若干５０人ぐらい増えまして、これも平成１５年度だけでございまして、その後、やはりまた下がっていくというような傾向です。平成１５、１６年でこのぐらいあって、やや回復してくるというような推測をしています。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"２年生が１８０人、１年生が１４８人ですか、減ってますよね。この辺の分析はどうか尋ねました。","respondent":"久保田学務課長","answer":"現時点で、完全にさっ引きますと１５人ということなんで、ゼロにはならないんじゃないかとは思っています。これから、転出、転入等もありますので、そういう点も含めても、このぐらいでいくのかなというふうに思っております。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"今回、それが４６人でマイナス１５人ですから、課長、ほんとうにそんなことはないと言えるんですか。言えないですかね、言えなければいいんですけど。","respondent":"指田教育次長","answer":"新１年生、５年生から６年生とかということはやってまいっていますけど、もう少し分析をきちっとやったほうがいいかなというのが一つ。プラン２１の教育改革によって、教育委員会と一緒になって考えていくべき話だと、こういうふうに思います。","id":"exchange-015"},{"speaker":"高星委員","kind":"質問・要望","question":"新しい施策が入ってくるということになると、一生懸命頑張っている先生方をどうするんですかという意見があることも事実です。そういうふうにならないんか尋ねました。","respondent":"久保田学務課長","answer":"ほかの学区から９人、それから出たのが５３人ですので、４４人が減ったということです。本来なら６０人が入ってこられるんですけど、引っ越しされて転出される方もいらっしゃいますので、最終的には３７人ということになったです。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"じゃあ単純に、今年の住民基本台帳で、平塚中学校の９３人が、こうなってくると、予想として何人ぐらいなんですか。概算で２７人ぐらいになるんじゃないか尋ねました。","respondent":"久保田学務課長","answer":"「国・私立入学者／指定校変更／転居者等があり、確定数ではありません」ということなんで、現時点ではわからないわけです。来年度がどうなるかというのは、まだわからないわけなので、そこら辺はこれからの話かなと考えています。","id":"exchange-017"},{"speaker":"高星委員","kind":"質問","question":"それが１クラス３０人、４０人ぐらいで、３学年でどうなっちゃうのかわからない。その辺のところをどう具体的に考えて、どうするつもりなのか、具体的に金をかけていくのかどうなのかということを、ちょっとお聞きしたい。","respondent":"指田教育次長","answer":"ここのところを認めていこう、ここはこういうふうにしていこうという形で、これから予算要求をする予定でいます。２７人、そこに至る経過というものも、ひとつよろしくご判断していただければありがたいなと思います。","id":"exchange-018"},{"speaker":"高星委員","kind":"質問","question":"平成１３年度、５３名がほかの学校に行かれて、３７名になったと。今年も、５６名が行かれて、この１年間、具体的に効果があることはできなかったんでしょ。","respondent":"若月教育長","answer":"もう１回、学校は間違いなく、みんな積極的な気持ちで取り組んでいるという状況であります。ぜひ、その辺をご理解いただいて、また学校を応援していただければと、こんなふうに思っているところです。","id":"exchange-019"},{"speaker":"川西委員","kind":"質問","question":"４日にいろいろ、まちの方から質問をいただきまして、恥ずかしい思いをしていたんです。どういう方が入っているかぐらいのことは、その間に、住民の方にちょっと説明できるということです。","respondent":"青木指導課長","answer":"アセスメント部会ですが、区内の校長が４名、教頭が４名、それぞれ小学校、中学校２人ずつです。","id":"exchange-020"},{"speaker":"川西委員","kind":"質問","question":"もう一つ、私も自分の置かれている立場とか、いろいろほかにもありまして、評価ということに対しては、悪いとは思っていないんですよ。ですから、将来、こういう趣旨のものを考えていこうと思っていることは確かですね。","respondent":"青木指導課長","answer":"外部の方の評価も取り入れて、学校改善に役立てようと、そうした学校評価のあり方を考えようと。教頭、小中学校合わせて８名の先生方に、具体的な内容について詰めていただいているです。","id":"exchange-021"},{"speaker":"桜井委員","kind":"質問・要望","question":"次回、ご報告いただきたいと思うんですけど、いかがでしょうか。それのお答えがなかったものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"続きまして、請願・陳情審査に移ります。 (1)の二〇〇二年度教育予算編成に関する陳情","agenda":"続きまして、請願・陳情審査に移ります。 (1)の二〇〇二年度教育予算編成に関する陳情","exchanges":[{"speaker":"山路委員","kind":"質問","question":"今、説明していただきましたが、１と２は検討されているようでありまして、３番の休憩室につきまして、お聞きしたいことは、私立中学校、小学校においてはどういうふうになっているのか、わかる範囲で説明を求めました。","respondent":"鷹倉庶務課長","answer":"いわゆる公務センターという形で、いろいろな部屋がオープン化される。ああいうような形態をとっている場合については、隠れ場所的に休憩室を取られている形態のところもあるのかなと思われます。","id":"exchange-023"},{"speaker":"山路委員","kind":"意見","question":"それで、休憩室に先生がいるのは、そこを考えた場合に、どうとらえていいのかなということを、ちょっと迷うんです。子どもたちがどういうふうにとらえるのかなということが一つ、ちょっとどうなのかなと悩んでいるところなんですけど、どういうふうに思われますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"委員長、時間短縮のために、関連がありますから、いいですか。１時間休憩を取ると、そういうのがどうなっているか伺えば、山路委員の質問と一緒に答えてほしいと求めました。","respondent":"青木指導課長","answer":"教員の休息、休憩の問題ですけども、このたび、４月からですけども、それぞれの学校で休憩、休息時間の割り振りということで、徹底しています。それぞれの学校の中で割り振りの時間を使って、休息、休憩が取れるような形になっております。","id":"exchange-025"},{"speaker":"高星委員","kind":"意見","question":"全体の流れの中で、やっぱりゆとりのある教育というところにもやっぱり目を当てるべきだと、この中身はこういう趣旨にとらえているんです。大きな意味で、休憩室というよりも、休憩する場所という意味なんでしょ、僕はこういうふうに理解するんですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほどちょっと、例えば主事室とか給食室に休憩室があるというお話がありましたけど、そこは使ってはいけないという規定か何かあるんか尋ねました。","respondent":"鷹倉庶務課長","answer":"いわゆる主事室に行って、先生方がたばこをお吸いになったり、お茶をお飲みになっている現況があるのはご存じだと思います。使っちゃいけないとか、そういうことではございません。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そういう点を考えた場合、学校の中で、新たに休憩室を設置するという必要性が出てくるのかどうか。そうすると、なぜここで休憩室を設置しろということが出てくるのか、私はちょっと疑問に思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問","question":"質問していいかどうか、ちょっと迷っていたんですけど、お願いします。","respondent":"青木指導課長","answer":"そういう意味で、先生が自分のそばで自分を見つめていてほしいというような形での、子どもの教師像というのはあると考えております。それぞれの教員の適切な時間の中で、休憩、休息は対応しているんだということで、子どもの目には、そういうふに見えると考えています。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"暑さへの影響というのですか、養護の先生なんかのご意見もあるのかどうか、その辺を聞きたい。もう１点、部分的にやったら幾らぐらいかかるのか、その辺を研究されているのかどうか。","respondent":"鷹倉庶務課長","answer":"この辺を当然含みながら、十分検討していきたいということがあります。今後、計画的にやる部分につきましては、ああいう形で明るく、きれいなトイレを目指してやっていきたいと考えています。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"要望に関しては、私が聞いている範囲では、女の子はスカートの間から下敷きでぱたぱたあおぎながら勉強しているんだという声も聞いています。研究は、いろいろ多方面にわたって研究をしていただいて、現場の声にこたえていただきたいなと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"川西委員","kind":"質問","question":"すみません、私の質問はどうなりましたか。まだ答弁できてない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"川西委員","kind":"質問・要望","question":"休憩時間は、服務規律や規則ではどうなっているのか。休憩室の問題は別ですよ。","respondent":"青木指導課長、指田教育次長","answer":"４５分間の休憩時間を取るということでやっております。授業が終わった後に、３時ごろか３時半だったと思うんですが、その辺に休憩時間を持っていくという形にしています。","id":"exchange-033"},{"speaker":"川西委員","kind":"意見","question":"そうしますと、内部規則とか、どういう名前の規則になっていますかとの意見を述べました。","respondent":"指田教育次長","answer":"これに基づいて、全部きちんと取るようにという形で、今年の４月に、その辺について全部やりとりして変えてきたという形になっています。もしあれでしたら、後ほど、その点については、ご参考にお持ちしたいと思ってあります。","id":"exchange-034"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、児童が帰ってしまって休憩時間を取っているときに、校長が何か頼んできたら、断ってもいいんか尋ねました。","respondent":"指田教育次長","answer":"休憩時間については、勤務命令を発することは、よほどのことがない限りできませんから、断ることは自由です。当然のことながら、その後、どこかしらでその時間を取ってもらうような形でやらなければいけないというような形になっています。","id":"exchange-035"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、そういう２３区、あるいは東京都の主なところの状況も調べたいし、トイレの問題も、中学校でやる場合、具体的にどの程度あるのか。他区の状況を教えていただきたいのと、どのぐらいの計画でやるのかという幾つかお願いしたいということで、できれば継続をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"山路委員","kind":"質問","question":"いろいろ先ほどから教えていただきまして、状況から見ると、陳情されている気持ちは非常にわかるんです。そういうことになりますと、きょう、結論出していいんじゃないかというのが、私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"川西委員","kind":"意見","question":"１、２、３と、意見はいろいろ私もあるんですが、学校関係の改築問題を含めて、これからいろいろありますし、設備関係の問題で、ここだけ解決して、学校現場がどうなるかという問題もありますから、ちょっとこれは願意に沿いがたいような気がして、結論を出して結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"高星委員","kind":"意見","question":"空き教室を休憩室にしろなんて、だれも考えているわけじゃなくて、原則的に休憩する場所が欲しいということなんだろうと理解するんです。２番のほうも、私は趣旨を採択すべきだと、そういうふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"桜井委員","kind":"質問・要望","question":"２は一致できるなら、３が一致できるかという形で、それはあまりにも酷だなと思うんです。だから、これをもし一致するとしたら、そういう項目的な採択を、私はしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"松澤委員","kind":"質問・要望","question":"休憩室をつくってほしい」と、私たちは、そぐわないなと思います。ですから、一括してやっていただきたいし、結論を出すならば、願意に沿いがたい、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"山路委員","kind":"意見","question":"今言われた、ウォシュレット云々とか、この陳情書に対して賛成することはできない。着実に進められていると信じていますので、そこを言いたいわけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"川西委員","kind":"質問・要望","question":"１番と２番について、将来に向かってどうしていくかというときに、やはり十分入れてもらいたい。ほんとうに場所をつくればいいだけの要望じゃないんだということは、私は思いまして、さっきの結論を出しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、そういう点では、これはぜひ、積極的に進めていってほしいと求めました。１年でやれるとかという問題じゃないと、今、聞いたら１億５,０００万円でできる話でしょ。","respondent":"鷹倉庶務課長","answer":"１けた間違っていました。２５０万円×６００校で１５億円です。","id":"exchange-044"},{"speaker":"桜井委員","kind":"質問","question":"だから、そういう点で、３番目が第一義的だから願意に沿いがたいというのは、ちょっと言いすぎじゃないかと、私は思います。ですから、趣旨の採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、ちょっと声が出たんですけど、予算面の措置や負担は六行会の負担か尋ねました。","respondent":"志村品川図書館長","answer":"そもそも、ここの建物の管理をやっています管理事務局というのがありますので、そこが工事主体になります。ただ、私ども、その中の入居者になってありますので、応分の負担をするということになります。","id":"exchange-046"},{"speaker":"桜井委員","kind":"意見","question":"だって、外壁って相当な金額でしょ。それを、通常の予算の中からやるというのは、ほかにしわ寄せしますから、私はそれは反対ですとの意見を述べました。","respondent":"志村品川図書館長","answer":"先ほど、委員からもちょっとお話がありましたように、予備費を含めまして対応をしていきたい。大変申しわけございません、説明が粗くて申しわけないです。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この間、聞いていたんで、それで大体はわかったんですけど、こういうビルの点検というのは、中の借りている人間が払うものなんですか。あの辺からの負担金というのは、当然、区ももらっているという考え方になるわけか尋ねました。","respondent":"指田教育次長","answer":"都税事務所、法務局も含めて、きちんと持ち分割合に応じて請求が後で来るという形です。管理組合でその話が出され、管理組合でこういう話があって、いこうという形になろうかと思っています。","id":"exchange-048"},{"speaker":"川西委員","kind":"質問","question":"ちょっと質問しておきたいんですが、区の規定で５,０００万円以上とか、３,０００万円から５,０００万円とかありますね。その範囲を超えた場合に、業者を選定するときは、こういう共同ビルの場合はどうするんか尋ねました。","respondent":"志村品川図書館長","answer":"今ちょっと次長がお答えしたように、私どものほうのやり方というんですか、その辺についてはお話をしていこうと考えています。","id":"exchange-049"},{"speaker":"桜井委員","kind":"質問・要望","question":"文化についてどうレベルアップをしていくのか、どう水準を上げていくのかというところに、改めて痛感したところだったんです。今回、全体の概況説明はいただきたいんですけども、品川区がどういうふうに生涯学習を推進していくのかというのを知りたいなというのは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"松澤委員","kind":"質問","question":"プラン２１のことが話題になりましたけども、「質問していいでしょうか」なんて方がいらっしゃるけど、あれは初めてのことだったんですね。そういう意味では、品川区のよさのことを先に聞きたかったというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"川西委員","kind":"意見","question":"それから、品川区と違うところが１点、学校開放については、地域での管理運営、やはり、地方だからできるのかなと思いました。都会のここへ持って来てできるのかなというふうなところが、ちょっと残念だなと思いまして、それなりに勉強になりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"山路委員","kind":"意見","question":"これもまたシステムの違いはあったんで、品川区でそのまま受け入れるかどうかということは別にしまして、非常に勉強になりました。ただ、品川区のほうを、むしろ地方の人が参考にしたいというのが強いのは感じてまいりましたけど、それについてはまとめてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"桜井委員","kind":"質問・要望","question":"委員長、今後の運営についていいでしょうか。これは要望なんで、正副委員長でご検討ほしいと求めましたけど、平成１３年度の事務事業評価が出ましたよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問","question":"私もいいですか。まだここは歴史館ですからあれだったですけど、他区なんかに行く場合に大変に失礼なんで、なるべくそれは重ならないような形にできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/605950?Template=document&Id=4420#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":34205,"voices":133}},{"id":"h13-20011107-13","meetingId":"h13-cm11","date":"2001年11月7日","dateIso":"2001-11-07","committee":"清掃・リサイクル特別委員会","time":"午後１時0６分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"１１月１日に大井地区で開催されたということで、出ていたご意見がありましたらまず聞かせてほしいと求めました。ここは連絡会が一つということで、開催がかなり困難というか、時期的に集まるのが困難ではないかなと思うので、その点について説明するよう求めました。","respondent":"中山清掃リサイクル課長","answer":"改めてご説明申し上げたんですが、先ほど簡単にご説明しましたけれども、推進員の主な役割の１点目として。委嘱のときにもそういったご説明を、まだまだ役割の認識について、それで「なるほどな」というふうなご意見をいただきました。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見を言うときにぜひ腕章か名札か、役割が地域の人にわかるようにしてほしいという声が出ましたので、その辺をぜひ具体化していただきたい。平成１３年度の予算が２４８万４,０００円と載っていたんですけれども、この辺の予算はどういうふうに使われていくか教えていただきたいんですが。","respondent":"中山清掃リサイクル課長","answer":"この会議の設置の中に地域の実情に合わせた話をということが基本になっているんですけれども、実際の会議の設定とか、そういうことを考えたときに。先ほど今後施設見学会等を実施する予定ですということで、今年度３地区、来年度２地区という形で実施していきたいと。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ皆さんの意見を大いに聞いていただいて、充実をしていただきたいとともに、この委員会にも内容を今後報告をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"ですから、そういう報告をされるのかとか、そういう返し方をどういうふうにしたらいいのかというのが一つの大事なポイントだというふうに思うんです。ですから、その辺はどういうふうにお考えになっているか伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"したがって、それはこの３８０人掛ける何倍という形に広がっていきますから、培ったものを広げていただきたいというふうに考えている次第です。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひやっていただきたいんですけれども、受けきれないとかというふうになっていくとまずいですから、なかなか壁が厚いと思うんです。その辺はできるだけ、せっかく受けていただく大事な役割ですから、進みやすいようにして協力いただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"船波副委員長","kind":"質問","question":"生ごみを集めたことによって可燃ごみがどう減ったかという数字が出ているわけですけれども、一般の住宅のほうでは１世帯当たりだと１カ月で７kg前後とか出ているわけだけれども、そういったことは考えていないんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"先ほどの資料の１番の表にありますように、強制はもちろんできませんから、ご協力いただける世帯において回収したということがあります。したがって、この辺は全体として実施する際には、例えば協力いただけなかった方への意見も分析するというのは必要かなというふうに思います。","id":"exchange-006"},{"speaker":"船波副委員長","kind":"質問","question":"コストがどうなるのかということが説明ないわけですが、差し引きというか、その辺はどうなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"今、６０円前後という価格になっておりますけれども、このモデル事業ですと１００円を超えてしまうような数値が出てまいります。したがって、可燃ごみよりも今段階では高いコストがかかってくるというのが、現段階での区の認識になっているところです。","id":"exchange-007"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"私も緊急補助対象事業になっているということを思ったので、この補助事業がなくなってきたときに区としてどう対応していくのか、この辺をお聞きしようと思ったんですけれども。","respondent":"中山清掃リサイクル課長、野本環境清掃事業部長","answer":"２カ年の事業を分析した上での判断ということになるんですけれども、可燃ごみよりも高いコストになってくるということを考えたときに、率直に言って難しいというふうに考えている次第です。そのときにお答えしたのは、区が生ごみの回収を将来区民の皆さんを相手に全面的に対応するという考えは、基本的には取らない。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"当然、今の答弁だと「あれ」という不安を感じたものですから発言をさせていただいたんです。ですから、そういうスタンスでやっていただけているのかなと期待していたんですが、そういう点でどうなんか尋ねました。","respondent":"野本環境清掃事業部長","answer":"このコンポストにやるということについては、一般の方なり何なりの認識で、すっといくと思うんです。要するに、完全な線になるかならないか程度で、面という格好でどう対応するかということをあまり経験していない。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"部長の今の話、また民間が今ごみの問題は収集と処理はほとんど自治体任せですから、私もいかがなものかなというふうに思っているんです。一つひとつがきちんとやっていくことが大事なことだと思うわけですから、生ごみ分野でも欠かさないで持つべきだと思うんです。","respondent":"中山清掃リサイクル課長","answer":"実際、やはりコストというものも考えないと、やはりコストが大きな要素ですというふうにお答えした次第です。じっくり検討していきながら、部長もご答弁申し上げましたデータを知らしめていくということで、生かしていきたいというふうに考えております。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういうシステムじない堆肥化の方法というものもあるはずですし、今地方ではいろいろ実践している例がたくさんありますね。補助金の問題、コストの問題だけでこれでやめにしちゃっていいものかというのはすごく思うものですから、いかがなものか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"端的にこの事業の継続ということになるかは別にしまして、今回のモデル事業を何らかの形で区政の中、あるいは対外的にオープンにしていくという流れの中での検討、およびそういった意味での活用について考えていきたいと考えています。","id":"exchange-011"},{"speaker":"土井委員","kind":"質問・要望","question":"これから先ほどのように理念的にそうすべきだ、したがってこれもお伝えいただけるんですねという確認をしていくためにも絶対に必要なことですから。","respondent":"中山清掃リサイクル課長","answer":"まさに認識しているとおりですが、先ほど全国的には生ごみの活用がいろんな方法が出てきて、研究ネットワーク等もあります。現実に東京２３区、今のご意見も貴重なご意見として、今後の材料にしていきたいと考えています。","id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"先ほどモデルになったところは各世帯あるんだけれども、手を挙げてもらったというようなお話で、こういった状況をよく考えているご家庭の方だろうと思うんですけれども、この中に先ほど言ったごみ減量化推進員という方々はどのぐらい入っていらっしゃるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"申し訳ございません。荏原地区内で１３１人ですから、詳しい人数は名簿と照らし合わせて、後ほどご提出したいと思います。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問","question":"一般の分別するよというのであっても、今のまちの中に出しているのは、そういうこともできていないメンバーたちが随分いるわけですね。ですから、そうでないような気がしたけれども、「概ね良好」という表現でいいかどうか。","respondent":"中山清掃リサイクル課長","answer":"それと、資源回収事業を２３区に先駆けて品川区で実施する前に、非常に協力の度合いが高いところだからまず乗ってくれるんじゃないかと。そう考えると、やはりもっとある意味での数値、あるいは成分も問題になるものが出てくる懸念はあるというふうに考えております。","id":"exchange-014"},{"speaker":"須藤委員","kind":"質問・要望","question":"これを見させていただいてそんな感じがしたので、そちらはそちらで対応というのは、コストも先ほどのコストから違ってくると思うんです。ですから、そういうところもまたどういうお考えがあったか、後で聞かせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤委員","kind":"意見","question":"３００部という数字は、今言ったようにどういう形で出てきたのかな、配布先等を考慮してきているのか、単に見学者が来ているのが３００部なのか、予算的に３００部しかできなかったというのかとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"予算の中で大体従来から３００部という形で設定しているわけですけれども、若干関心が高まるだろうということで、従来の配布部数との見合いで３００部ということを設定しているものです。","id":"exchange-016"},{"speaker":"須藤委員","kind":"意見","question":"できたら推進員のメンバーにも、そうするとまたＰＲの形になってこようかと思うので、その辺のお考えはいかがなものかなと。し尿処理で品川区は７５世帯があるということなんだけれども、これもどうしようもない場所なのか、配置的にチェンジしていく方法ができないかとの意見を述べました。","respondent":"中山清掃リサイクル課長、金井環境課長","answer":"実際に区内に１００％下水道整備がされていると言いながら、斬減しておりますけれどもなかなかゼロにはならないことです。毎年調査するたびに１０世帯、２０世帯の割合で減ってきておりますから、順次減っていくものだです。ですから、部数が例えば５００部あれば、それの５％ぐらい減らしていこうじゃないかと。","id":"exchange-017"},{"speaker":"須藤委員","kind":"意見","question":"それで結構です。これを全部というと勉強も大変だろうから、平易に解釈できるようにしてご協力いただいてもらえれば、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういう機会がありましたら、ぜひそのことも伝えていただきたいというふうに思っています。見解のところにちょっとわからないから教えていただきたいんですけれども、ここのところはどういうことなのか、システムも含めて教えていただきたい。","respondent":"金井環境課長","answer":"そういう計画書を事前に細かいものを出してやるようになってまいりますので、実際に解体とかそういう工事にかかってくるのは秋以降になります。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"日常的に地域センターだよりの中に、そういうことを含んでの質問だったんですが、それについてはどうなのかということを伺いたいと思います。ですから、今でもそういう交通渋滞があるときに、なお一層のその辺の配慮をしていただけるように姿勢を改めて確認していただきたいと思っています。","respondent":"金井環境課長","answer":"先ほどの区民委員会でもご説明しておりますが、窒素酸化物、ＳＰＮという黒いあれですね。平成２年から比べますとかなり下がってきて、下向きのほうにということでご理解をいただければというふうに思っております。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"ですから、１０年後に一層これを右肩下がりになっていくということで、もっと加速できるようにしていきたいというふうに思っています。その辺をいろんな角度から規制を強めていくという、きちんとさらに発言をしていただくということを、改めてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"土井委員","kind":"意見","question":"したがって、これもここに工場ができたら浄化装置ができたようになっちゃうんじゃないかな。だから、逆によくなるほうになるんだということをちゃんと説明したほうがいいと思いますよ、意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"私の考えが違ったら質問にならなくなっちゃうんですけれども、この事業者意見というのは清掃一部事務組合のほうでつくっているわけですね。この清掃車両は今で言うと品川区が担当する部分じゃないかと思うんですけれども、この文章はどうなっているのかなという質問なんですが。","respondent":"中山清掃リサイクル課長","answer":"ここで言っているのは、そういったものを低公害車の使用拡大が進められてきますというふうな、受け手としての表現になるのが正確かと思います。","id":"exchange-023"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"お聞きしている範囲でガスの充てん除去の問題も大井清掃工場は出ていましたが、やはりガスの充てん場がないので不便だというお話を聞いています。その辺のところで、お答えをいただければ。","respondent":"中山清掃リサイクル課長","answer":"現在清掃工場自体は清掃一部事務組合で実施していますが、まさに平成１７年度末を目途に地域処理という中で、今後は各区が清掃工場を運営すると。","id":"exchange-024"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"清掃一部事務組合で管理しているうちに、品川区が借地として借り取るような形を考えるのも一つの方法じゃないかと思うんですが、この辺はどうですか。やはり、形状でやりようがないというのでしたら、やむを得ない部分ですが。","respondent":"中山清掃リサイクル課長","answer":"明確な方針があってということであれば、今申し上げたような更新期間中に全面的に敷地を平成１８年３月まで工事を行い、工事車両を入れ。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"今の委員長がおっしゃったことは、次回の委員会の運営を議長にご出席をいただいて、清掃一部事務組合等の所管する問題について、委員会の中で理事者への質問も含めて質疑をするという、そういう運営をしていきたいということですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/301337?Template=document&Id=5650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":31294,"voices":69}},{"id":"h13-20011107-16","meetingId":"h13-cm11","date":"2001年11月7日","dateIso":"2001-11-07","committee":"街づくり特別委員会","time":"午後１時０４分～午後４時４０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"最初にちょっと基本的なことを教えていただきたいんですが、これが有効だというか、そういうような判断だと思うんです。手法というんでしょうか、わかれば教えていただきたいと、最初にちょっとお願いしたいんですが。","respondent":"浜脇住環境整備課長","answer":"２００％使うためには、こういった誘導型のものを使うというふうに判断したものです。さまざまな地区計画をご提案したんですが、皆さん方から見て、使いやすいと思われたのがこの街並み誘導型地区計画であったです。","id":"exchange-001"},{"speaker":"上山委員","kind":"確認","question":"ちょっと確認だけしたいんで恐縮なんですけども、２００％使えるということになると、そういうことでよろしいんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"できるだけ耐火のものを建てたいのにいろいろな規制あって建てられないといった場合に、少しでも建つ条件として何かないかというのがまず発端です。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"ここに方針区域が８.１ha、１.２ha、地区計画をやってこられた。品川区が５０m2という指導をしているんであれば、私はこれは５０m2するべきだと信じているんですけど、そこら辺の点はどうお考えになるか。","respondent":"浜脇住環境整備課長","answer":"５０m2ということで、品川区全域にそういう考え方で指導していますが、やはり一定の規制と緩和というのがあるわけです。それについて、まちの方からは異論はなかったというのが、現在の６０m2になったという理由です。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"例えば、今、ほかのところも平均的に６０m2だという前例を引っ張ってこられたけれども、だから進んでないんじゃないですか。この地域の８.１haをどういうふうにしていくんだということを考えるんであれば、どうかなと、意見だけ表明しておきます。","respondent":"山室住宅指導担当部長","answer":"繰り返しになりますが、ここでは地元の皆様方と話し合いをして、指導要綱で定めているぎりぎりの数値より１ランク上のものを進めていきたいと。都市計画の手続を踏んでまいりますので、現時点で、６０m2をご提案をさせていただているということをご理解いただければと思います。","id":"exchange-004"},{"speaker":"本田委員","kind":"確認","question":"地区計画の網は８.１ha全部にかかるわけですか。３回の意見交換会をやったという報告が、どういうふうに生かさせるというのか、確認したいと思います。","respondent":"浜脇住環境整備課長","answer":"方針だけですから、地域といたしましては、８.１haに地区計画がかかっているとご判断いただきたいと思います。この地区の方針の方につきましては、緩やかな方針ですけども、開かせていただいております。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"１.２haの１４０世帯のところが、３回ぐらいの意見交換で、一度の話もよく聞いてなかったという人もいるんではないかと思うんです。くれぐれも、見切り発車になってはならないなと思うんですが、その辺のとらえ方はどうなんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"その方については、またもう１回お話をして、ご協力をお願いしてまいるということです。私どもとすれば、これは地元から出たものですから、ぜひ、区としては成功させたいといいますか、成立させたいと思って、今後やってまいります。","id":"exchange-006"},{"speaker":"藤田委員","kind":"質問","question":"あのときに、かなり細い通路のような道路があったんですけれども、それについては、あれは全部２項道路に指定をされているのかどうか。それをまず、ちょっとお聞きしたいと思います。","respondent":"浜脇住環境整備課長","answer":"一部区道と、一部私道ですけども、２項道路です。","id":"exchange-007"},{"speaker":"藤田委員","kind":"質問","question":"限られた土地ですから、有効に建てたいというのは、だれしもの思いですから。まだ０.５ｍ下げるなんていうと、これから逆に多くなるんじゃないかと心配するんですけども、その辺をどう受けとめられているのか。","respondent":"浜脇住環境整備課長","answer":"道路を１本入った方も何軒かいらっしゃいますので、それは、今後の詳細なマニュアルといったものはつくっていかなくちゃいけないなと考えております。ただ、そういうことがあるという問題点は、今、考えておりまして、これは間もなく整理してまいりたいと思っています。","id":"exchange-008"},{"speaker":"藤田委員","kind":"意見","question":"それから、門や塀はだめと書かれていますけど、「等」なっていますが、この「等」が非常にトラブルのもとなんですよ。例えば空調の室外機をもし置かれたら、どうしますかとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"委員、ご承知のとおり、工作物についてはこれでやっているんですが、今の室外機については、工作物とみなせませんので、その辺も、今の間隔と同じように、室外機はどういうふうに見るかというのは、やはり認定といいますか、内規の中で定める必要があると考えています。","id":"exchange-009"},{"speaker":"藤田委員","kind":"意見","question":"もう設計の段階で、どんどん０.５ｍの中に出てきちゃいますよ、これは。きょうは、そのぐらいにしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"少なくとも１.２haの１４０世帯のうちで懇談会をつくったわけじゃないでしょうから、どのぐらいの人たちがここにいたのか。とりあえず、そこからあたり、ちょっと教えてくれますか。","respondent":"浜脇住環境整備課長","answer":"方針になりますとまだいるんですが、ちょっとそこまで資料がなかったものですから、整備地区内では、１０名中１人です。４番目に駐車場の件がございましたけども、あるいは、懇談会の方々と一緒になって検討してまいるとなっております。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/506587?Template=document&Id=6218#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":16504,"voices":30}},{"id":"h13-20011108-14","meetingId":"h13-cm11","date":"2001年11月8日","dateIso":"2001-11-08","committee":"行財政改革特別委員会","time":"午後 １時１５分～午後４時２９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503251?Template=document&Id=5694#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":312,"voices":2}},{"id":"h13-20011126-6","meetingId":"h13-cm11","date":"2001年11月26日","dateIso":"2001-11-26","committee":"区民委員会","time":"午前１０時０５分～午後１２時５０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"意見","question":"てにをはの部分は後にしまして、基本的にこれでよろしいんじゃないかというふうに思っておりますので、それにご同意いただければと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"この辺、私どもが受けて伺った感触とちょっと違うものですから、ハローワークとの話で中身がありましたら教えていただきたい。一緒にあわせてお聞きしますけれども、職員なのかどうかちょっとよくわかりませんけれども、これもあわせてお聞きをしたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"要は今の雇用対策としてお聞きをしているというふうに考えているんです。ですから、今、課長が言われた内容で十分かと思われます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/217714?Template=document&Id=2312#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":5674,"voices":32}}]);
